window.BYB=window.BYB||{};BYB.themes=[["La foi",0,"Hébreux 11:1 ; Romains 10:17","Croire en Dieu, croire en Sa Parole, la foi vivante, la foi parfaite, la guérison divine, la confiance et la victoire sur l'incrédulité.","foi"],["La divinité de Jésus-Christ",0,"Jean 1:1-14 ; Colossiens 2:9","L'identité de Jésus-Christ, Sa divinité, la révélation de Dieu en Christ, Son Nom, Sa prééminence et Sa manifestation.","divinité"],["La repentance et la conversion",0,"Actes 2:38 ; Actes 3:19","Reconnaître ses péchés, se repentir, abandonner l'ancienne vie, se réconcilier avec Dieu et porter les fruits de la conversion.","repentance"],["La sanctification et la vie sainte",0,"Hébreux 12:14 ; 1 Thessaloniciens 4:3","Se séparer du péché, vivre dans la pureté, abandonner les mauvaises habitudes, marcher dans l'obéissance et manifester le caractère de Christ.","sanctification"],["Le Saint-Esprit et la nouvelle naissance",0,"Jean 3:3-8 ; Actes 1:8 ; Galates 5:22-23","La nouvelle naissance, le baptême du Saint-Esprit, la conduite de l'Esprit, les dons spirituels et le fruit de l'Esprit.","nouvelle naissance"],["La Parole de Dieu",0,"2 Timothée 3:16 ; Matthieu 24:35","L'inspiration des Écritures, la Parole originelle, la semence, l'autorité biblique, la révélation et la nécessité de revenir à la Parole.","Parole"],["Le Message du temps de la fin",0,"Malachie 4:5-6 ; Luc 17:26-30 ; Apocalypse 10:7","La reconnaissance de l'heure, le Message du temps de la fin, le réveil spirituel, la restauration et la préparation de l'Épouse.","temps de la fin"],["L'Église et l'Épouse de Christ",0,"Éphésiens 5:25-27 ; Apocalypse 19:7-8","L'Église véritable, l'identité de l'Épouse, l'unité spirituelle, la préparation de l'Épouse et sa relation avec Christ.","Épouse"],["La prière et la communion avec Dieu",1,"","Intercession, adoration, consécration, intimité avec Dieu.","prière"],["La guérison divine et les miracles",1,"","Guérison, délivrance, témoignages et foi pour la guérison.","guérison"],["Le baptême d'eau",1,"","Repentance, immersion, formule baptismale et signification du baptême.","baptême"],["La rédemption et le Sang de Jésus",1,"","Sacrifice du Calvaire, pardon, justification et salut.","Sang"],["L'amour chrétien",1,"","Amour divin, charité, pardon, humilité et compassion.","amour"],["L'obéissance à Dieu",1,"","Volonté divine, obéissance à la Parole et soumission à Dieu.","obéissance"],["La prédestination et l'élection",1,"","Semence, élection divine, adoption et position du croyant en Christ.","prédestination"],["Les âges de l'Église",1,"","Les sept âges, leurs messagers et les conditions spirituelles des Églises.","âges de l'Église"],["Les Sept Sceaux et les mystères bibliques",1,"","Révélation des Sceaux, symboles et interprétations prophétiques.","sceau"],["Les prophéties bibliques",1,"","Daniel, Matthieu 24, Apocalypse, Israël et les nations.","prophétie"],["Le retour de Jésus-Christ",1,"","Seconde Venue, enlèvement, résurrection et espérance chrétienne.","enlèvement"],["Le discernement spirituel",1,"","Vraie et fausse onction, faux enseignements et discernement des esprits.","discernement"],["L'antichrist et l'apostasie",1,"","Marque de la bête, séduction religieuse et avertissements bibliques.","antichrist"],["La communion fraternelle",1,"","Unité, communion, réconciliation et vie communautaire.","communion"],["La famille et le mariage",1,"","Mariage, divorce, rôle des parents et éducation des enfants.","mariage"],["La conduite chrétienne",1,"","Habillement, langage, modestie, discipline et témoignage.","habillement"],["La victoire sur le péché",1,"","Tentation, délivrance, persévérance et croissance spirituelle.","tentation"],["Le ministère et les dons spirituels",1,"","Appel, prophétie, évangélisation, leadership et service.","ministère"],["Les types et symboles bibliques",1,"","Figures de l'Ancien Testament, ombres et accomplissements en Christ.","type"],["La résurrection et la vie éternelle",1,"","Résurrection des morts, jugement, nouvelle Jérusalem et destinée éternelle.","résurrection"],["La délivrance et les combats spirituels",2,"","","délivrance"],["La peur, l'inquiétude et le découragement",2,"","","peur"],["Le doute et l'incrédulité",2,"","","doute"],["La patience et la persévérance",2,"","","patience"],["La confiance dans les promesses de Dieu",2,"","","promesse"],["Le pardon et la réconciliation",2,"","","pardon"],["L'humilité et le renoncement à soi",2,"","","humilité"],["La consécration et le sacrifice",2,"","","consécration"],["La sagesse et le discernement",2,"","","sagesse"],["La fidélité dans les épreuves",2,"","","épreuves"],["La préparation spirituelle et la vigilance",2,"","","préparez"],["La reconnaissance et les actions de grâce",2,"","","reconnaissant"],["Le témoignage et l'évangélisation",2,"","","témoignage"],["La mort, le deuil et l'espérance de la résurrection",2,"","","espérance"]];
window.BYB=window.BYB||{};BYB.tq=[[["sermons/1964/64-1205.html?q=foi#s72","64-1205 § 38 — Le chef-d’oeuvre identifié de Dieu","Eh bien, Abraham représentait l’oeuvre de la foi, la foi, en effet, Abraham était un homme de foi. Il avait une grande foi, car il ne douta point par incrédulité au sujet de la promesse de Dieu. Comme nous le dirions, les choses n’allaient pas et tout était contre lui, il s’est malgré tout accroché à Dieu."],["sermons/1957/57-0610.html?q=foi#s26","57-0610 § 10 — La foi qui a été transmise aux saints une fois pour toutes","Maintenant, vous entendez beaucoup de gens dire aujourd’hui : « Oh ! la guérison divine, c’est contraire à ma foi. Le baptême du Saint-Esprit, c’est contraire à ma foi. » Il n’y a qu’une seule foi. Et cette foi-là ne vient pas par l’adhésion à l’église. Cette foi vient de ce qu’on entend, et ce qu’on entend de la Parole de Dieu."],["sermons/1955/55-0819.html?q=foi#s98","55-0819 § 45 — Être conduit par le Saint-Esprit","Ne doutez pas. Croyez. Vous avez reçu ce que vous avez demandé. Ayez la foi. C’est votre foi qui le fait. C’est votre foi qui tire le don de Dieu. Ce n’est pas moi. Je ne connais rien de vous. Je pourrais aller vers chacun de vous, mais je ne le saurais pas. C’est votre foi ; c’est votre foi qui fait cela. Ayez la foi en Dieu."],["sermons/1960/60-0611E.html?q=foi#s236","60-0611E § 160 — La foi, c’est le sixième sens","Cet homme et cette femme qui se tiennent ici (ce frère et cette soeur de couleur) avec leur petit garçon, croyez-vous ce soir ? Ayez foi, mon frère. Ayez foi, ma soeur. Le petit ami est trop petit pour savoir ce qu’est la foi ; croyez que Dieu guérira votre enfant. La dame qui se tient ici avec ce petit garçon ici. Ayez foi..."],["sermons/1947/47-0412.html?q=foi#s175","47-0412 § 48 — La foi est une ferme assurance","La foi est le seul sens précis et sûr, et c’est le sixième sens. La foi est plus que la vue. La foi est plus que le toucher. On ne touche pas la foi. On ne goûte pas la foi. La foi n’a pas d’odeur. On ne voit pas la foi. La foi est une ferme assurance des choses qu’on espère, une démonstration de celles qu’on ne voit pas."],["sermons/1956/56-0304.html?q=foi#s56","56-0304 § 48 — Ouvrir une voie","J’ai foi dans ce que Dieu a dit, et j’accepte simplement cela. Ainsi, la foi ne repose pas sur le sable mouvant des–des conceptions émotionnelles. Mais la foi repose sur l’Etalon, la Parole éternelle de Dieu, le Rocher des âges. C’est là que la foi trouve son lieu solennel de repos et elle n’est jamais ébranlée lorsqu’elle repose là même."],["sermons/1964/64-0209.html?q=foi#s120","64-0209 § 105 — Le compte à rebours","Vous voyez : «Ta foi t’a sauvée.» Maintenant, il y a des érudits assis ici, je le sais. Ce mot, c’est sozo. «Ta parole t’a sauvée. Ta foi t’a sauvée.» De même que votre foi vous sauve du péché, votre foi vous sauve physiquement de la maladie, vous voyez. Donc, vous devez le croire."],["sermons/1954/54-0803.html?q=foi#s38","54-0803 § 38 — Jaïrus","Tout d’abord, cette foi agissait en elle, le Seigneur Jésus s’est retourné et a dit (Il avait senti quelque chose sortir de Lui, une force.), Il a dit : « Ma fille, ta foi t’a sauvée. » Amen. La perte de sang s’est arrêtée, elle s’est arrêtée à l’instant. Sa foi avait arrêté Jésus, sa foi avait obtenu ce dont elle avait besoin."],["sermons/1955/55-0620.html?q=foi#s14","55-0620 § 6 — Combattre pour la foi","Eh bien, au début, quand la foi a été présentée au monde, la foi pour laquelle nous devons combattre ardemment, c’était Jean-Baptiste qui l’avait présentée. Il avait présenté Jésus au monde et Jésus a présenté la foi. Eh bien, retournons pour voir quelle foi Il avait présentée au monde, et alors nous verrons de quoi nous parlons."],["sermons/1956/56-0722.html?q=foi#s74","56-0722 § 18 — Tout est possible à celui qui croit","Bien, c’est simplement essayer de se cacher derrière une certaine doctrine ecclésiastique, au lieu de venir et de dire : «Vous n’avez pas de foi.» C’est tout. Satan n’a jamais reçu le Saint-Esprit; il n’a donc rien pour vous donner la foi. C’est Dieu qui a la foi. Et autant vous êtes rempli de Dieu, autant vous êtes rempli de foi."],["sermons/1955/55-0109M.html?q=foi#s50","55-0109M § 47 — Melchisédek, le grand prince et roi","Pouvez-vous vous représenter Jésus dire : «Eh bien, laissez-Moi vérifier Ma foi pour voir si J’ai assez de foi pour faire ceci. Voir s’il Me faudra jeûner un peu, pour voir si J’ai assez de foi pour faire ceci»? Il était tout à fait inconscient de la foi qu’Il avait. Il déclarait simplement la chose, et savait qu’il en serait ainsi."],["sermons/1957/57-1208.html?q=foi#s91","57-1208 § 31 — Je me tiens à la porte, et je frappe","Tant que cette foi est ancrée, les médecins peuvent m’abandonner tous, tout, mais je serai là. Je serai guéri. Dieu l’a dit. Je vais Le laisser entrer dans la porte de mon coeur. Ma foi Lui a été donnée et Il m’a donné la promesse, et rien ne pourra interférer. C’est là, la foi, la porte de la foi."]],[["sermons/1958/58-0515.html?q=divinit%C3%A9#s40","58-0515 § 17 — Jésus-Christ est le même hier, aujourd’hui et éternellement","Dieu a donné à Jésus Son Esprit sans mesure. En Lui habitait corporellement la plénitude de la Divinité. Il était Dieu manifesté dans la chair. La Bible déclare : « Dieu était en Christ, réconciliant le monde avec Lui-même. » Mais en donnant Son Esprit à nous les fils adoptés, Il nous En donne un seau plein provenant de cet océan. Lui avait toute la plénitude de la Divinité ; nous, nous n’En avons qu’une portion, comme un don du Saint-Esprit."],["sermons/1955/55-1113.html?q=divinit%C3%A9#s49","55-1113 § 16 — Jésus-Christ est le même hier, aujourd’hui et éternellement","J’ai dit : « Quand Jésus était ici sur terre, nous savons qu’Il était Emmanuel. » Nous le croyons tous. Il n’était pas simplement un Prophète. Il était Dieu, manifesté dans la chair. Alors, quand Il était ici sur terre, toutes les puissances que le Père Lui avait données, tout ce qui était en Lui… Il était Emmanuel, Dieu en Christ, réconciliant le monde avec Lui-même."],["sermons/1950/50-0819.html?q=divinit%C3%A9#s170","50-0819 § 49 — Montre-nous le père et cela nous suffit","Maintenant, rapidement, prenons Dieu dans Son Fils. Croyez-vous que Dieu était en Christ ? Je le crois de tout mon coeur. La Bible déclare que Dieu était en Christ, réconciliant le monde avec Lui-même. Il était Emmanuel. En d’autres termes, Il était l’empreinte de la Personne de Jéhovah ici sur terre, Jéhovah voilé dans la chair, vivant ici sur terre, le Fils unique du Père, dans Son sein."],["sermons/1960/60-0329.html?q=divinit%C3%A9#s132","60-0329 § 41 — C’est moi, n’ayez pas peur","Mais quand Dieu était ici sur terre sous une forme humaine, Jésus-Christ était Dieu fait chair et demeurant parmi nous. Or, toute la Plénitude de la Divinité habitait corporellement en Lui. Il était Dieu rendu manifeste. Personne n’a vu le Père, à aucune époque, mais le Fils unique du Père L’a manifesté. Le... Dieu se manifestait, ce qu’Il était, à travers Son Fils Jésus."],["sermons/1958/58-0519.html?q=divinit%C3%A9#s44","58-0519 § 16 — La vie","« Eh bien, à quoi voulez-vous en arriver, Frère Branham ? » Voici ce qu’il en est. Quand Jésus était sur la terre, Il était Dieu manifesté dans la chair. Nous, nous avons l’Esprit avec mesure. Lui L’avait sans mesure. Toute la plénitude de la divinité habitait corporellement en Lui. Il n’était pas juste un homme ; Il était Dieu."],["sermons/1960/60-1204E.html?q=divinit%C3%A9#s251","60-1204E § 144 — La vision de Patmos","La plus grande de toutes les révélations, c’est celle de la Divinité, la Divinité suprême de notre Seigneur Jésus-Christ. Vous ne ferez pas de progrès tant que vous n’aurez pas cru à Cela, vous sortirez... C’est pourquoi Pierre a dit : « Repentez-vous, puis voyez la Divinité. Soyez baptisé au Nom de Jésus-Christ pour le pardon de vos péchés, alors vous serez prêts à entrer dans l’Esprit. »"],["sermons/1962/62-0711.html?q=divinit%C3%A9#s81","62-0711 § 40 — Écoutez-le","Eh bien, à mon avis, ce qu’Il faisait… Dieu n’a jamais demandé à quelqu’un de faire quelque chose qu’Il ne fait pas Lui-même. C’est pourquoi je crois dans la Divinité de notre Seigneur Jésus-Christ, qu’Il était plus qu’un homme. Il était–Il était plus qu’un prophète, pourtant Il était un Prophète ; pourtant Il était un Homme. Mais Il était plus que cela. Il était Emmanuel. Il était Dieu manifesté dans la chair. Je crois cela."],["sermons/1955/55-1119.html?q=divinit%C3%A9#s144","55-1119 § 52 — Rédempteur, rédemption","Mais, regardez, pour que Dieu rachète Sa race humaine, Dieu a dû descendre et devenir aussi un Humain. Jésus-Christ était Dieu manifesté dans la chair. Voyez-vous ce que je veux dire ? Dieu était en Christ, réconciliant le monde avec Lui-même. Dieu a été fait Parent de la race humaine ; en effet, Il a été fait chair et Il a demeuré parmi nous."],["sermons/1958/58-0610.html?q=divinit%C3%A9#s63","58-0610 § 20 — Le puissant Conquérant","J’ai dit : «Si, d’après la Parole.» Elle a dit : «Si je vous expliquais et vous prouvais par la Parole qu’Il n’était qu’un homme… Mais vous essayez de faire de Lui la Divinité.» J’ai dit : «Il était la Divinité.» J’ai dit : «Dieu était en Christ, réconciliant le monde avec Lui-même.» J’ai dit : «S’Il n’était qu’un simple prophète, nous sommes tous perdus.»"],["sermons/1955/55-0522.html?q=divinit%C3%A9#s160","55-0522 § 141 — L’arche, un type de Christ","Le croyant, une fois entré, le couvercle se ferme, la chose est réglée pour toujours. Amen. L’or, la Divinité, recouvrait l’arche, au-dessus, en-dessous et tout autour ; elle était enveloppée dans la Divinité. Tous ceux qui viennent à Christ sont enveloppés dans le Saint-Esprit et deviennent des fils et des filles de Dieu."],["sermons/1953/53-0611.html?q=divinit%C3%A9#s253","53-0611 § 72 — Montre-nous le père et cela nous suffit","Eh bien, Il était plus qu’un philosophe. Certains ont dit : « Oh ! C’était un Enseignant », c’est ça la conception de la science chrétienne. « Il était un Enseignant. Il était un Homme de bien. » Soit Il était Dieu soit Il était un séducteur. C’est vrai. Il était Dieu Emmanuel : Dieu manifesté dans la chair, et habitant parmi nous. La Bible dit que Dieu était en Christ, réconciliant le monde avec Lui-même. C’est exactement ce qu’il y avait."],["sermons/1964/64-0318.html?q=divinit%C3%A9#s103","64-0318 § 90 — Messieurs, nous voudrions voir Jésus","Cela faisait donc de Lui la Parole, ce Maître-Prophète, ce Dieu-Prophète, Il était plus qu’un prophète. Lui, c’était tout ce qu’étaient les prophètes, plus le reste de Dieu. Voyez-vous? Il était Emmanuel, Dieu, représenté dans la plénitude dans le Fils, Christ Jésus. Eh bien, nous voyons que Dieu était en Christ, réconciliant le monde avec Lui-même."]],[["sermons/1960/60-1126.html?q=repentance#s135","60-1126 § 44 — Pourquoi ?","Les gens ont peur de la nouvelle naissance. Cela ne fait que vous changer. Si vous n’êtes pas changé, alors vous n’êtes pas converti. Vous pouvez être converti en entrant dans une dénomination. Vous pouvez être converti en entrant dans une autre atmosphère ou quelque chose du genre. Mais lorsque vous êtes converti à Dieu, alors vous menez une vie sainte."],["sermons/1957/57-0325.html?q=repentance#s28","57-0325 § 15 — L’agneau et la colombe","C’est comme le disait un évangéliste ; un soir il avait prêché sur la repentance. La soirée suivante, il a prêché sur la repentance. Deux semaines passèrent et il continuait de prêcher sur la repentance. Quelques diacres sont venus le voir et ont dit : « Pasteur, ou évangéliste, n’avez-vous pas un autre sermon en dehors de la repentance ? »"],["sermons/1963/63-0122.html?q=repentance#s129","63-0122 § 55 — Se souvenir du Seigneur","Vous les dames ici, vous direz : « Je suis fatiguée après quelque temps. » Non, il ne le fera pas. Je serai comme cet homme qui a dit une fois qu’il s’est mis à prêcher pour un réveil. Il a dit qu’il prêchait sur la repentance. La troisième soirée, la repentance ; la quatrième soirée, la repentance. Il a prêché sur la repentance toute la semaine."],["sermons/1953/53-1205.html?q=repentance#s68","53-1205 § 22 — La résurrection","Une fois, un vieux ministre est allé prêcher la repentance un soir. Le soir suivant il est revenu et il a prêché la repentance. Il a prêché cela toute une semaine, et il a commencé la seconde semaine avec la repentance. Quelques-uns des anciens l’ont croisé à la porte et ils ont dit : « Ne pouvez-vous prêcher rien d’autre en dehors de la repentance ? »"],["sermons/1962/62-0610M.html?q=repentance#s206","62-0610M § 51 — Présumer","Si vous vous êtes converti à un credo, si vous êtes un converti d’une organisation, si vous êtes un converti d’une église, vous ferez ces choses-là. Mais une fois converti à Christ, vous êtes né de nouveau, vous êtes mort à ces choses, et vivant… Mais les gens continuent carrément, présumant que c’est en ordre de faire cela, s’aventurant sans autorité."],["sermons/1954/54-0329.html?q=repentance#s28","54-0329 § 26 — La rédemption par la puissance","Ainsi, c’est comme cet évangéliste qui est venu dans la ville. Il a prêché un soir. Il a prêché sur la repentance. Le soir suivant, il a prêché sur la repentance. Le soir suivant, il a prêché sur la repentance. Après environ quatre ou cinq soirées, le comité des diacres est allé le voir et lui a demandé : «Frère, ne pouvez-vous pas prêcher autre chose que la repentance ?»"],["sermons/1963/63-0605.html?q=repentance#s26","63-0605 § 26 — Il y a ici plus que Salomon","J’ai dit : « L’Amérique est remplie de la même chose. Tous les méthodistes veulent convertir les baptistes. Et les baptistes veulent convertir les pentecôtistes. Et les unitaires veulent convertir les binitaires. Les binitaires veulent convertir… » Oh ! la la ! je n’ai jamais entendu rien de pareil ! Mais une chose pour laquelle je suis reconnaissant, c’est que nous adorons tous le même Dieu. Mais là-bas, c’est différent."],["sermons/1962/62-0521.html?q=repentance#s80","62-0521 § 44 — Convaincu, et puis concerné","Jean savait qu’il était temps d’être–de se repentir, d’exiger la repentance, et de se préparer pour le Messie. Et si c’était le temps pour se repentir à l’époque, qu’en est-il de maintenant? Sa Venue était proche. Il était alors avec eux. Maintenant, regardez combien proche… Comparons ceci maintenant pendant un moment."],["sermons/1954/54-1205.html?q=repentance#s33","54-1205 § 8 — Nous voudrions voir Jésus","Maintenant, d’abord, tout au début de Son ministère, il y avait un homme–homme du nom de Philippe qui fut converti. Et aussitôt qu’il fut converti, il alla chercher son ami Nathanaël, c’était un bon, un vrai signe qu’il était converti. Une fois qu’un homme a été avec Jésus, il désire que tout le monde connaisse Jésus."],["sermons/1958/58-0326.html?q=repentance#s109","58-0326 § 27 — Unis sous une seule tête","Eh bien, peut-être que c’étaient des convertis de Billy Graham, peut-être que ce sont des convertis de William Branham; s’ils le sont, ils n’iront pas très loin. C’est ce que je dirai. Mais si ce sont des convertis de Dieu, ils le resteront pour toujours. Je me suis dit : « Billy, j’aimerais dire quelque chose ici. »"],["sermons/1962/62-0628.html?q=repentance#s156","62-0628 § 58 — Il y a ici plus que Salomon","Au bout d’un moment, le dieu de la mer est apparu, il a tiré la langue, et le prophète est sorti directement de sa bouche. Et il s’est mis à dire : « Repentez-vous. Repentez-vous, dans quarante jours, ce pays sera détruit. » Dieu sait comment faire les choses. Le dieu a vomi le prophète. Amen ! Il a carrément parcouru toute Ninive en disant : « Repentez-vous. » Oui."],["sermons/1963/63-0707M.html?q=repentance#s350","63-0707M § 277 — L’accusation","J’exige la même chose que Pierre. Il a exigé la repentance à cette génération-là. J’exige la repentance à cette génération, la repentance envers Dieu et le retour à la Vérité originelle de la Parole. Retournez à la foi de nos pères. Retournez au Saint-Esprit, car Dieu ne change pas cela."]],[["sermons/1963/63-1114.html?q=sanctification#s240","63-1114 § 213 — Influence","C’est la Présence de Dieu parmi nous maintenant qui suscite la sainteté, ce n’est pas ma sainteté, ni la vôtre, mais c’est Sa sainteté. C’est Sa Présence qui suscite la sainteté. Nous devons nous humilier, nous couvrir par révérence, par humilité, et dire : « Seigneur Jésus, reçois-moi dans Ton Royaume. » Sa sainteté, pas la nôtre. Saint-Esprit !"],["sermons/1954/54-0404M.html?q=sanctification#s65","54-0404M § 23 — Combattre ardemment pour la foi","Eh bien, ils n’étaient pas appelés des saints avant qu’ils aient été sanctifiés. Le mot sanctifié, je crois, signifie saints ou saint signifie sanctifié. Jusqu’à ce qu’ils ont été sanctifiés par le Sang de l’offrande de Jésus-Christ, une fois pour toutes, à ce moment-là, ils sont devenus des saints."],["sermons/1954/54-1003E.html?q=sanctification#s138","54-1003E § 132 — L’année de jubilé","Frère, ce qu’il faut, c’est d’être sûr! Maintenant, crier, c’est très bien. Je crois dans la sanctification; oui, monsieur, non pas la mienne, mais la Sienne. Voyez? C’est vrai. Non pas ma sainteté, mais la Sienne. Lorsque Lui, le Saint-Esprit, met Sa sainteté ici à l’intérieur, c’est Sa sainteté, non pas la mienne. Je suis un pécheur, mais Lui est le Seigneur."],["sermons/1965/65-0815.html?q=sanctification#s93","65-0815 § 37 — Et tu ne le sais pas","Disons qu’elle est méthodiste, parce que les méthodistes ont un peu plus de sainteté que les baptistes; tous les baptistes, sauf les baptistes du Nouveau Testament qui eux croient à la sainteté. Mais, généralement, les baptistes ne croient pas du tout à la sainteté, voyez. Ils n’y croient pas. Alors, disons qu’elle est méthodiste, parce qu’eux, ils croient à la sainteté."],["sermons/1955/55-0724.html?q=sanctification#s226","55-0724 § 161 — Les esprits séducteurs","Jésus, dans Sa prière, a dit : « Père, Je me sanctifie Moi-même. » Jésus s’est sanctifié pour l’Église. Il aurait pu se marier, mais Il ne l’a pas fait. Il s’est sanctifié. Il a dit : « Sanctifie-les, Père, par la Vérité. Ta Parole est la Vérité. »"],["sermons/1955/55-0123E.html?q=sanctification#s14","55-0123E § 3 — Combattre ardemment pour la foi","Le mot saint signifie celui qui est sanctifié. En d’autres termes, nous devons combattre pour la foi qui a été transmise une fois pour toutes à ceux qui sont sanctifiés. La sanctification signifie être appelé hors de, mis à part, purifié (Voyez-vous ?), purifié et mis à part pour le service."],["sermons/1959/59-1219.html?q=sanctification#s51","59-1219 § 42 — Questions et réponses sur le Saint-Esprit","Mes chers frères méthodistes, pèlerins de la Sainteté, et nazaréens, le baptême du Saint-Esprit est différent de la sanctification. La sanctification c’est la purification qui prépare la Vie. Mais quand le Saint-Esprit vient, Il est la Vie. La préparation consiste à purifier le vase; le Saint-Esprit c’est le remplissage de celui-ci. «Sanctification» signifie «purifié et mis à part pour le service». Le Saint-Esprit le met en service. Vous êtes le vase que Dieu a purifié."],["sermons/1960/60-1204E.html?q=sanctification#s161","60-1204E § 102 — La vision de Patmos","Or, si vous lisez bien votre Bible, il n’est pas dit : « La grande route de la sainteté. » Il est dit : « Il y aura là une grande route et un chemin, et il sera appelé non pas « la grande route de la sainteté », mais « le chemin de la sainteté ». « Et », c’est une conjonction qui termine votre phrase. Vous voyez, « il y aura une grande route et un chemin qui sera appelé le chemin de la sainteté », non pas « la grande route de la sainteté. »"],["sermons/1954/54-0829A.html?q=sanctification#s157","54-0829A § 36 — Je vous restaurerai, dit l’éternel","Il n’est pas question de savoir si nous tenons ferme, d’un réveil à l’autre, il est question de savoir si Christ tient ferme, au Calvaire. Ce n’est pas ce que moi, je fais, c’est ce que moi, je suis en Jésus-Christ, comme Lui est mort pour moi ; pas ma sainteté, pas votre sainteté, c’est Sa sainteté dans laquelle nous tenons ferme. Oui, oui."],["sermons/1960/60-1204M.html?q=sanctification#s453","60-1204M § 377 — La révélation de Jésus-Christ","Maintenant, vous pouvez être sauvé sans être sanctifié. Vous pouvez être sanctifié et ne pas avoir le Saint-Esprit. C’est vrai ! Avoir un esprit sanctifié sans être rempli. Votre coeur peut être sanctifié, purifié, sans pour autant être rempli de quelque chose... C’est ce qu’Il a dit. « Lorsqu’un esprit impur quitte un homme, il va dans des lieux arides. Puis il revient et trouve sa maison bien ornée ; alors, il y entre. La dernière condition de cet homme est de loin (sept fois) pire que la première. »"],["sermons/1965/65-0829.html?q=sanctification#s112","65-0829 § 50 — L’Éden de Satan","Avoir la foi dans toute Sa Parole, Sa Semence a produit un Eden de sainteté, d’amour et de Vie Eternelle. C’est ce que l’Eden de Dieu produit : la sainteté. Et cela a produit un Eden de sainteté, d’amour, de compréhension, de perfection et de Vie Eternelle. Voilà le programme de Dieu. Sa Parole, Sa Semence, c’est ce que Son Eglise sera à la fin, elle sera ainsi."],["sermons/1960/60-0611B.html?q=sanctification#s95","60-0611B § 31 — La communion","C’est là que je suis en désac... Vous les frères nazaréens et les pèlerins de la sainteté qui pensez que la sanctification, c’est toute l’oeuvre du Saint-Esprit, elle ne l’est pas. La sanctification vous purifie, mais le Saint-Esprit vous remplit. Le verre est mis à part pour le service, mais pas en service, avant d’être mis en service par le Saint-Esprit et rempli du Saint-Esprit. Voyez-vous ? C’est ça."]],[["sermons/1960/60-0221.html?q=nouvelle%20naissance#s148","60-0221 § 139 — Entendre, reconnaître et agir sur base de la Parole de Dieu","Le Saint-Esprit est la nouvelle naissance ; nous le savons. Il s’agit de naître de nouveau, de l’Esprit de Dieu. C’est ainsi que vous naissez, de l’Esprit. Etre né de l’Esprit, c’est la nouvelle naissance. Très bien. Vous naissez de l’Esprit ; puis quand vous êtes né de l’Esprit, vous êtes rempli du Saint-Esprit. Très bien."],["sermons/1953/53-0906A.html?q=nouvelle%20naissance#s105","53-0906A § 27 — Crois-tu cela ?","Et que chaque personne qui n’a pas le baptême du Saint-Esprit dise : « Seigneur, je n’ai pas le Saint-Esprit, et je connais tout sauf cela, eh bien, j’ai peur. C’est pourquoi je–je désire naître de nouveau, car Tu as dit : ‘Si un homme ne naît de nouveau, il n’entrera pas dans le Royaume.’ C’est pourquoi je désire naître de nouveau. »"],["sermons/1963/63-0608.html?q=nouvelle%20naissance#s151","63-0608 § 63 — Les conférences","Quand Dieu a dit naître de nouveau, Il voulait dire naître de nouveau. Il ne veut pas dire une poignée de main ou réciter un credo. Tout le monde a peur de cette nouvelle naissance. Le diable a remplacé cela par une poignée de main ou une espèce d’affaire psychique qui vous ferait reconnaître : « Oui, je suis né de nouveau. » Mais votre vie révèle ce que vous êtes, la vie qui est en vous."],["sermons/1954/54-0512.html?q=nouvelle%20naissance#s346","54-0512 § 273 — Les sept âges de l’église","C’est vous qu’Il veut ; il s’agit d’un individu. Et vous devez naître de nouveau et recevoir le baptême du Saint-Esprit, sinon ç’en est fait de vous. Voyez-vous ? Vous ne faites que la religion, vous ne faites qu’imiter tant que vous n’avez pas une véritable expérience de nouvelle naissance."],["sermons/1956/56-0128.html?q=nouvelle%20naissance#s186","56-0128 § 75 — L’inspiration spirituelle","Si vous ne comprenez pas ce que je veux dire par naître de nouveau, je veux dire quelqu’un qui n’a pas le baptême du Saint-Esprit. C’est ça la nouvelle naissance. Voudriez-vous lever la main et dire : «Je crois maintenant ; je veux recevoir le Saint-Esprit. Souviens-toi de moi, frère prédicateur » ? Que Dieu vous bénisse, soeur. Quelqu’un… Que Dieu vous bénisse, monsieur. C’est bien. Quel temps !"],["sermons/1959/59-0702.html?q=nouvelle%20naissance#s62","59-0702 § 18 — Où est partie ta force, Samson ?","Nous savons tous que la Bible enseigne la nouvelle naissance. Et ils ont substitué une poignée de main et tout le reste à la nouvelle naissance, mais cela ne prendra jamais la place de la nouvelle naissance. Ça doit être une expérience, une nouvelle naissance."],["sermons/1959/59-1001.html?q=nouvelle%20naissance#s85","59-1001 § 25 — Qu’êtes-vous allés voir ?","Jean a prêché le baptême du Saint-Esprit. Il n’a jamais prêché quelque chose qu’il n’avait pas. Il a prêché ce qu’il avait reçu. Et les hommes de Dieu qui sont envoyés dans les champs aujourd’hui n’ont aucun droit de prêcher l’Evangile sans avoir reçu le baptême du Saint-Esprit. C’est la première qualification d’un prédicateur : être rempli du Saint-Esprit."],["sermons/1960/60-0604.html?q=nouvelle%20naissance#s39","60-0604 § 13 — À qui irons-nous ?","Ce n’est pas là la question. Pour être chrétien, il vous faut être en Christ. Et il n’y a qu’un seul chemin pour entrer en Christ, et ce n’est pas par les credos ni par les églises, mais par le baptême du Saint-Esprit. Nous devons naître de nouveau. Et lorsque nous sommes nés de nouveau, alors nous sommes en Christ. Et si vous êtes en Christ, vous êtes sur le Chemin, car Il est le Chemin."],["sermons/1957/57-0901M.html?q=nouvelle%20naissance#s47","57-0901M § 45 — Hébreux chapitre 3","Ainsi donc, ni le fait de crier, ni rien de ce genre n’en est l’évidence. Jésus dit : «Vous les reconnaîtrez à leurs fruits.» Et le fruit de l’Esprit n’est pas le parler en langues. Ce n’est pas le fruit de l’Esprit. Crier n’est pas le fruit de l’Esprit. Pleurer n’est pas ce fruit de l’Esprit. Mais l’amour, la joie, la paix, la patience, la bonté, la bénignité, la foi, la douceur, la tempérance, voilà les fruits de l’Esprit. Ce sont là les fruits de l’Esprit. Très bien!"],["sermons/1964/64-0206E.html?q=nouvelle%20naissance#s31","64-0206E § 29 — La voie à laquelle Dieu a pourvu pour aujourd’hui","C’est là le problème, aujourd’hui, chez les gens. Une nouvelle naissance, ils esquivent tous ça. Ils n’aiment pas ça. Oh, ils ont substitué quelque chose à la nouvelle naissance : « Venez et croyez, c’est tout ce que vous avez à faire. » Le diable, lui-même, croit, et vous savez qu’il n’est pas né de nouveau. Il y a une nouvelle naissance. Il y a quelque chose qui va de paire avec ça, quelque chose qui, pour le monde, semble inconvenable, de mauvais goût."],["sermons/1964/64-0403.html?q=nouvelle%20naissance#s284","64-0403 § 258 — Jéhovah-Jiré 2","Demain soir, nous aurons une–une réunion pour le baptême du Saint-Esprit, demain soir, juste ici dans le bâtiment. Eh bien, il y a beaucoup de fanatisme qu’on appelle baptême du Saint-Esprit, mais cela ne signifie pas qu’il n’existe pas de véritable baptême du Saint-Esprit. Il y a un véritable et authentique Saint-Esprit de Dieu, malgré tout. Et je crois qu’Il va nous rencontrer ici demain soir."],["sermons/1958/58-0312.html?q=nouvelle%20naissance#s7","58-0312 § 4 — Jésus-Christ est le même hier, aujourd’hui et éternellement","Nous prêchons l’Evangile, nous croyons d’abord qu’un homme doit naître de nouveau. Il doit naître de nouveau. Et puis, eh bien, s’il n’est pas né de nouveau, alors il ne peut pas comprendre le Royaume de Dieu. C’est ce que Jésus a dit à Nicodème : « Si un homme ne naît de nouveau, il ne peut voir le Royaume. » Et le mot voir, là, c’est une traduction anglaise, en réalité ça veut dire : Il ne peut pas comprendre le Royaume de Dieu, tant qu’il n’est pas né de nouveau."]],[["sermons/1958/58-0209A.html?q=Parole#s53","58-0209A § 17 — Écoutez-le","Mais il n’en est pas ainsi des Ecritures. Les Ecritures sont inspirées. Les hommes, pendant deux mille ans, ont lu ce même passage des Ecritures que j’ai lu cet après-midi, cela les a inspirés, et cela inspirera toujours, parce que c’est la Parole de Dieu. La Parole de Dieu est une partie de Lui. Il ne vaut pas plus que Sa Parole."],["sermons/1959/59-0405A.html?q=Parole#s31","59-0405A § 12 — Au commencement, il n’en était pas ainsi","Et quand quelqu’un dit que la Parole de Dieu n’enseigne pas la guérison divine, il dit une chose que la Parole de Dieu ne dit pas. Et quand on dit que la Parole de Dieu n’enseigne pas que le baptême du Saint-Esprit est pour les croyants de tous les âges, on dit une chose que la Parole de Dieu ne dit pas. On met un substitut à la place."],["sermons/1957/57-0306.html?q=Parole#s101","57-0306 § 45 — Dieu tient sa Parole, 1","Maintenant, c’est ce que dit la Parole de Dieu là-dessus. Croyez-vous la Parole de Dieu ou la parole de quelqu’un d’autre ? Il serait mieux d’accepter ce que la Parole de Dieu dit là-dessus. C’est juste. Car les cieux et la terre passeront, mais Sa Parole ne passera point. Alors, restez avec la Parole de Dieu."],["sermons/1957/57-0407E.html?q=Parole#s5","57-0407E § 3 — Puis Jésus vint","Notre sujet ce soir commence avec l’un des plus beaux contextes des Ecritures. Je pense que toutes les Ecritures sont parfaites. On ne peut pas trouver à redire à la Parole de Dieu. Elle est tout simplement parfaite. Mais le texte que nous allons étudier est l’un des textes les plus remarquables des Ecritures. C’est un des sceaux de Sa qualité de Messie."],["sermons/1964/64-0216.html?q=Parole#s140","64-0216 § 83 — L’identification","Et cependant, vous voyez Jésus venir après et dire: «Les Ecritures déclarent que Je devais faire cela.» Et Il l’a fait. «Les Ecritures déclarent que Je devais faire ceci…et naître d’une vierge. Les Ecritures déclarent que Je devais telle autre chose.» Et Il l’a fait. Il a dit: «Sondez les Ecritures et voyez où J’ai failli.»"],["sermons/1961/61-0112.html?q=Parole#s302","61-0112 § 248 — Questions et réponses","Maintenant, voyons comment cela ne blague pas avec les Ecritures. Voyez? Eh bien, ça ne concorde pas, c’est ce que je veux dire. Pardonnez-moi, je n’ai pas voulu dire «blaguer» avec les Ecritures. J’ai voulu dire «concorder» avec les Ecritures, ou «se conformer, s’ajuster» aux Ecritures, c’est cela le terme approprié."],["sermons/1957/57-1208.html?q=Parole#s196","57-1208 § 60 — Je me tiens à la porte, et je frappe","Et Père, nous savons qu’il n’y a qu’une seule façon de recevoir la foi. La Bible déclare que la foi vient de ce qu’on entend, ce qu’on entend vient de la Parole de Dieu. La Parole de Dieu déclare que Jésus-Christ est le même hier, aujourd’hui et éternellement. La Parole de Dieu déclare que vous ferez aussi les oeuvres que Je fais. » La Parole de Dieu dit : « Toutes choses sont possibles à ceux qui croient. »"],["sermons/1963/63-1115.html?q=Parole#s253","63-1115 § 210 — La dislocation du monde","Que serait-Il ? Il serait identique à Hébreux 13.8, le même qu’Il était, qu’Il a toujours été. Il serait la Parole de Dieu rendue manifeste. C’est exact. Il était la Parole de Dieu ; Il est la Parole de Dieu ; Il sera éternellement la Parole de Dieu. Même la–l’annonce de Sa Venue, ça a toujours été les prophètes à qui la Parole de Dieu venait. Ici, la Parole était venue dans la Plénitude."],["sermons/1954/54-0719E.html?q=Parole#s72","54-0719E § 31 — Dieu a pourvu à la guérison pour cette génération","La terre doit recevoir le blé pour reproduire la vie. Et vous devez recevoir la Parole de Dieu dans votre coeur pour reproduire ce que la Parole dit qu’il y aura. Chaque Parole de Dieu est une Semence. Jésus a dit que C’en était Une. Le semeur est allé semer des semences. Il a dit que la semence, c’était la Parole de Dieu."],["sermons/1962/62-0124.html?q=Parole#s185","62-0124 § 102 — N’est-ce pas moi qui t’envoie ?","Ne connaissez-vous pas la Bible ? Hébreux 4 dit : « La Parole de Dieu est plus tranchante qu’une épée quelconque à deux tranchants, pénétrante jusque–jusqu’à partager la moelle de l’os, Elle discerne les pensées du coeur », la Parole de Dieu, quand Elle est en vous. Oui, oui. La Parole de Dieu était manifestée en Lui."],["sermons/1959/59-0329M.html?q=Parole#s62","59-0329M § 43 — Le baptême d’eau","Si les apôtres Lui ont désobéi, alors les Ecritures sont fausses. Vous devez attester que les Ecritures sont parfaites ou Elles ne représentent rien. Soit chaque Parole est vraie, soit aucune n’est vraie. Je ne sais pas laquelle serait vraie si le tout n’est pas vrai. Si une partie d’Elle n’est pas inspirée, alors le reste pourrait ne pas l’être. Et il n’y a pas de contradiction dans les Ecritures."],["sermons/1957/57-0322.html?q=Parole#s47","57-0322 § 26 — Écoutez-le","Maintenant, je sais, et vous frères, surtout les ministres qui sont ici, que la manière correcte d’aborder ceci serait de dire : « C’était l’ordre de la Seconde Venue de Christ. » Et c’est vrai. Mais la Parole de Dieu est si inspirée qu’Elle s’accordera avec n’importe quel autre sujet de la Bible parce que c’est entièrement la Parole de Dieu."]],[["sermons/1961/61-0117.html?q=temps%20de%20la%20fin#s166","61-0117 § 51 — Le Messie","Oh, il y a eu des centaines d’Elie qui sont apparus en ces derniers jours : Alexandre Dowie et tant d’autres, dans le monde aujourd’hui qui prétendent être Elie, être l’Elie du jour. Elie retournera à l’église originale de la pentecôte, d’Ephèse et il amènera le même Message aux gens avec les signes du Messie. La Bible l’a dit."],["sermons/1964/64-0313.html?q=temps%20de%20la%20fin#s97","64-0313 § 66 — La voix du signe","Jésus savait cela. Il était Elie. C’est ce que devait être sa nature. Il était identifié exactement comme l’était Elie. Il avait l’Esprit d’Elie. Il devait venir cinq fois, cet Esprit, pour être utilisé. Elie, Elisée, Jean, Malachie 4, et ensuite chez les Juifs dans les derniers jours dans lesquels nous sommes ce soir, l’Esprit d’Elie."],["sermons/1955/55-0612.html?q=temps%20de%20la%20fin#s218","55-0612 § 50 — La Présence du Seigneur Jésus","Elie était l’homme de Dieu de l’heure pour la nation. Et elle savait que Dieu était en Elie. Alors, elle a demandé à son serviteur de seller un âne et de conduire jusqu’à ce qu’elle arrive auprès d’Elie pour découvrir pourquoi son enfant était mort. Et vous connaissez l’histoire, comment Elie est venu et a ressuscité l’enfant pour elle."],["sermons/1951/51-0929.html?q=temps%20de%20la%20fin#s17","51-0929 § 9 — Notre espoir repose en Dieu","Il n’y a jamais eu dans un âge deux prophètes majeurs sur la terre au même moment. Il y a eu plusieurs prophètes mineurs, mais il y avait un seul prophète majeur. Et Elie était le prophète jusqu’à ce qu’Elisée fût venu. Alors, quand Elie était enlevé, une portion, une double portion de l’Esprit d’Elie, l’Esprit d’Elie est venu sur Elisée."],["sermons/1961/61-0428.html?q=temps%20de%20la%20fin#s157","61-0428 § 51 — Entrer dans l’Esprit","Et aussitôt que cet homme de Dieu a entendu que l’Esprit d’Elie reposait sur un autre homme, et que cet homme faisait la même chose qu’Elie autrefois, il a reconnu que c’était le vrai prophète. Il savait que si le véritable Esprit d’Elie était sur un autre homme, ce dernier ferait la même chose qu’Elie autrefois."],["sermons/1965/65-0219.html?q=temps%20de%20la%20fin#s260","65-0219 § 241 — Aujourd'hui cette Écriture est accomplie","De même qu’Elie escalada la montagne en surveillant–Elisée alla tout en surveillant Elie, il dit: “Je désire une double portion.” Et le manteau qui était sur Elie tomba sur Elisée. Il descendit, et plia le manteau en deux et frappa la rivière, disant: “Où est le Dieu d’Elie?” Et la même chose qui était arrivée pour Elie arriva pour Elisée."],["sermons/1964/64-0321E.html?q=temps%20de%20la%20fin#s239","64-0321E § 206 — La voix du signe","Et le signe du temps de la fin aura une Voix du temps de la fin. Et le signe du temps de la fin sera selon ce qui est prédit dans la Bible. Et la Voix du temps de la fin, qui suit le signe du temps de la fin, sera exactement identifiée dans les Ecritures, ça sera l’Ecriture qui a été promise."],["sermons/1962/62-0609E.html?q=temps%20de%20la%20fin#s171","62-0609E § 53 — Laisser échapper la pression","Eh bien, n’est-ce pas la même chose aujourd’hui ? Maintenant, nous sommes au temps de la fin, pour lequel Il a promis que ce–que ce Cep produirait une autre branche. Il a promis cela pour le temps de la fin, et nous voici au temps de la fin. (J’en arriverai au bourgeonnement de cette branche le matin, le Seigneur voulant.) Mais nous voici au temps de la fin avec le même Jésus."],["sermons/1963/63-0324M.html?q=temps%20de%20la%20fin#s242","63-0324M § 204 — Questions et réponses sur les sceaux","Non, ce n’est pas le même homme (Vous voyez ?) ; ce sont deux hommes différents. L’Elisée qui est venu sous forme d’Elie, n’était pas Elie. Et l’esprit d’Elie qui est venu sur un homme appelé Jean-Baptiste, ce n’était pas Elie. Et l’homme, le septième ange, le messager à la fin de l’Age de Laodicée, ne sera pas le vrai Elie. Ce sera quelqu’un des nations, qui viendra vers les siens."],["sermons/1963/63-0728.html?q=temps%20de%20la%20fin#s642","63-0728 § 574 — Christ est le mystère de Dieu révèle","Maintenant, il est promis, dans les derniers jours, que la même foi originale devait être restaurée aux enfants de Dieu, au temps de l’Arbre-Epouse (Malachie 4). Dieu a dit : «Avant que le monde ne soit embrasé, voici Je vous envoie Elie le prophète, et il restaurera la foi des enfants.» Eh bien, ce n’était pas le premier Elie qui était venu. Non, non."],["sermons/1964/64-0213.html?q=temps%20de%20la%20fin#s73","64-0213 § 53 — Puis Jésus vint et appela","Elie était un homme de Dieu, non pas comme Christ ; Christ connaissait toutes choses, parce qu’Il était Dieu. Elie était une portion de Dieu. C’était Christ dans Elie. Et c’était le Message de l’heure, car ce prophète avait la Parole de l’Eternel pour cette heure-là."],["sermons/1960/60-1218.html?q=temps%20de%20la%20fin#s455","60-1218 § 364 — Le son confus","Elle a dit : « Il est vrai, Seigneur, qu’il ressuscitera à la fin, dans les derniers jours. » Pourquoi ? Elle avait entendu cette Parole. Elle savait que c’était un Son certain. « Assurément, Seigneur, il ressuscitera, dans les derniers jours. C’était un bon garçon. Il ressuscitera à la résurrection générale, dans les derniers jours. »"]],[["sermons/1962/62-1014M.html?q=%C3%89pouse#s373","62-1014M § 257 — La stature d’un homme parfait","Alors, Dieu, représentant Son Eglise comme une Epouse, une femme... Dieu représente Son Eglise comme une Epouse. Et la façon dont Il amène chaque individu à être Son fils pour entrer dans cette Epouse, c’est la même façon qu’Il a aussi amené l’Epouse à travers ces âges, jusqu’à amener cette Eglise complète dans ceci."],["sermons/1963/63-0324M.html?q=%C3%89pouse#s276","63-0324M § 232 — Questions et réponses sur les sceaux","Lorsque Dieu a donné à Christ Son Epouse (l’Esprit a donné la chair, l’Epouse), Il a été pelu–percé dans le côté, sous Son coeur, et l’eau, le Sang et l’Esprit sortirent ; cela est devenu « chair de Sa chair, et os de Son os ». Nous sommes la chair et les os ; l’Epouse sera la chair et les os de Christ, exactement. Ils sont le... C’est Son Epouse."],["sermons/1961/61-0730E.html?q=%C3%89pouse#s91","61-0730E § 72 — Les six buts de la visite de Gabriel à Daniel","Et, souvenez-vous, quand il a été rejeté de ses frères, qu’a-t-il fait ? Il a pris une épouse des nations; il a pris une épouse égyptienne. Quand Jésus a été retranché de Ses frères, là-bas, les Juifs, Il a épousé une Épouse des nations. Mais voilà que, des années plus tard, après qu’il a eu des enfants, Éphraïm et Manassé, il avait une famille."],["sermons/1965/65-1125.html?q=%C3%89pouse#s174","65-1125 § 155 — L’union invisible de l’épouse de Christ","Mais, ce sont les Elus que Dieu appelle. Les Elus le savent. Il appelle l’Epouse vertueuse, la Parole, l’Eglise du dernier jour, la Dame Elue de notre Seigneur Jésus-Christ, la Parole. Si Jésus est la Parole... Combien croient cela? Très bien. En outre, l’Epouse est toujours une partie de l’Epoux; ainsi, l’Epouse ne sera pas une dénomination. Elle devra être la PAROLE MANIFESTEE pour être l’Epouse de Christ. Il a promis de le faire. Il a dit comment Il le ferait."],["sermons/1957/57-0807.html?q=%C3%89pouse#s22","57-0807 § 8 — Écoutez-le","Trois, c’est la perfection, comme Père, Fils et Saint-Esprit ; et l’eau, le sang et l’esprit, et autres. Et les trois Venues de Jésus : Il est venu une fois pour racheter Son Epouse. La fois suivante, Il vient prendre Son Epouse. La fois suivante, Il vient avec Son Epouse après le Souper des Noces."],["sermons/1964/64-0726M.html?q=%C3%89pouse#s72","64-0726M § 46 — Reconnaître votre jour et son message","Ensuite, Il a dit : « L’Epouse va réapparaître. » Et là, l’Epouse est arrivée derrière elle, Elle avait exactement la même apparence que l’Epouse qui avait défilé au commencement. Alors, mon coeur a bondi de joie, de savoir qu’il y aura une Epouse. Et Elle sera formée de la même chose et vêtue de la même chose, que Celle du commencement. Elle doit être appelée."],["sermons/1965/65-0429.html?q=%C3%89pouse#s134","65-0429 § 110 — Le choix d’une épouse","Remarquez encore maintenant comment l’épouse naturelle est le type de l’épouse spirituelle. La Parole dit qu’elle fut faite pour l’homme, mais pas l’homme pour elle. Maintenant, eh bien, je vais vous parler... de l’Epouse de Christ dans quelques minutes, mais j’essaye de vous en donner le fondement."],["sermons/1964/64-0705M.html?q=%C3%89pouse#s202","64-0705M § 155 — Le chef-d’oeuvre","Remarquez, l’Epouse. Si l’Epouse, au commencement, était la Parole, ou, l’Epoux, alors, si l’Epouse est tirée de l’Epoux, Elle doit, Elle aussi, être la Parole. Remarquez, c’est ce que l’Epouse doit être."],["sermons/1962/62-0318E.html?q=%C3%89pouse#s144","62-0318E § 139 — La Parole parlée est la semence originelle","La véritable Épouse qui a fait ses preuves, Elle aura, comme Marie, un sein vierge, pour être l’Épouse de la Parole, c’est-à-dire de Christ. Quand Christ, la Parole, viendra vers l’Épouse, Elle sera comme Lui : vierge par la Parole. Ô Dieu !J’espère–j’espère que c’est reçu, Frère Neville. Je..."],["sermons/1963/63-0627.html?q=%C3%89pouse#s273","63-0627 § 252 — Jésus-Christ est le même hier, aujourd’hui et éternellement","Il y a une différence entre l’église et l’Epouse. Je ne prêche pas la doctrine ; en effet, je ne le fais pas. Mais, d’après mon humble croyance, l’Epouse passe par le… ou plutôt la–l’église passe par la tribulation, le sixième sceau, pour être purifiée. C’est exact. Mais pas l’Epouse ; Elle va dans l’Enlèvement avant cela. Il est temps que l’Epouse soit appelée à sortir ; maintenant donc, je pense que c’est le temps de l’appel à sortir."],["sermons/1963/63-0320.html?q=%C3%89pouse#s165","63-0320 § 158 — Le troisième sceau","Maintenant, remarquez. Mais quand la Parole est venue à elle comme… exactement comme Dieu avait dit qu’Elle viendrait, elle se L’était représentée autrement. Je parle de l’épouse, de l’épouse juive, de l’épouse israélite. Au départ c’était Ève. Puis, quand la Parole en est arrivée là, elle n’En voulait pas. Elle voulait rester avec ses substituts."],["sermons/1953/53-0729.html?q=%C3%89pouse#s326","53-0729 § 269 — Questions et réponses sur la Genèse","Et c’est là que beaucoup d’érudits de la Bible s’embrouillent aujourd’hui, en pensant que l’Epouse est là-bas dans la Tribulation. Quelqu’un me parlait, il disait : «Je n’ai pas pu vous en parler, frère Branham.» Il dit : «J’ai vu l’Epouse là au Ciel. Et le dragon crachait de l’eau de sa bouche pour faire la guerre à l’Epouse. Et les cent-quarante-quatre mille qui sont l’Epouse, se tenaient sur le mont Sinaï.»"]],[["sermons/1961/61-0429E.html?q=pri%C3%A8re#s9","61-0429E § 4 — Un son confus","Eh bien, et alors, demain après-midi, vous qui viendrez pour des cartes de prière, j’aimerais inviter surtout les pasteurs demain. En effet, j’aimerais qu’ils m’aident à prier pour les malades. J’aimerais vous prouver que Dieu n’exauce pas uniquement la prière d’un seul homme ; Il exauce la prière de tout celui qui priera. Ainsi donc, venez nous aider."],["sermons/1961/61-0827.html?q=pri%C3%A8re#s8","61-0827 § 8 — Le message de grâce","Maintenant, inclinons la tête juste un moment pour un mot de prière. Avant de prier, y a-t-il ici quelqu’un qui voudrait qu’on se souvienne de lui dans cette prière et qui le ferait savoir en levant la main? Et à présent, dans votre coeur, pensez à Dieu pour ce qui est de vos besoins, et je vais prier pour qu’Il vous les accorde."],["sermons/1952/52-0224.html?q=pri%C3%A8re#s190","52-0224 § 113 — Croire en Dieu","Quand j’ai commencé à faire ces déclarations-ci, j’ai dit à mon église : « Restez sur vos faces et priez. » Dieu a commencé à agir. Bien vite, j’ai reçu des appels de l’Afrique, du monde entier. Comment les choses en sont-elles arrivées là ? Je l’ignore. La prière est montée. Priez. Croyez lorsque vous priez. C’était cela. Croyez."],["sermons/1956/56-1002E.html?q=pri%C3%A8re#s7","56-1002E § 4 — Le prophète Elisée","Et maintenant, ce soir, nous avons consacré ce temps à la ligne de prière, afin de prier pour les malades. Et ce soir, Dieu voulant, j’aimerais prier pour les malades, juste comme frère Roberts le fait, frère Tommy Hicks aussi, frère Valdez, et–et Jack Coe, frère Osborn et les autres, prendre juste les gens et prier pour eux."],["sermons/1961/61-1119.html?q=pri%C3%A8re#s7","61-1119 § 7 — La force parfaite par la faiblesse parfaite","Eh bien, l’autel est le lieu de prière où… Chaque personne qui arrive à l’église devrait d’abord aller s’agenouiller à l’autel, prier Dieu en silence et présenter sa requête dans la prière, et–et prier pour ses bien-aimés, et remercier Dieu pour Ses bienfaits à son endroit, puis retourner à sa place."],["sermons/1957/57-0811E.html?q=pri%C3%A8re#s149","57-0811E § 48 — L’expectative et la conduite de l’Esprit","Elle a dit… elle s’est mise à prier. Et, oh ! la la ! vous parlez de la prière, cette pauvre femme de couleur a adressé à Dieu une prière qui ferait pleurer le coeur le plus dur. Je me suis tenu là, me baignant simplement dans la beauté de Dieu pendant qu’elle priait. Elle s’est essuyé ses gros yeux; elle a dit : « Maintenant, voudriez-vous prier, pasteur ? »"],["sermons/1958/58-0215.html?q=pri%C3%A8re#s3","58-0215 § 2 — La reine de Séba","Et maintenant, vous qui avez des cartes de prière, pendant que nous faisons passer ces lignes de discernement, en prenant quelque part ici et là un petit groupe, pour lequel prier, tenez votre carte de prière, parce que nous allons prier pour tous ceux qui ont des cartes de prière. Gardez donc votre carte de prière. Prions maintenant."],["sermons/1964/64-0617.html?q=pri%C3%A8re#s219","64-0617 § 201 — Le Christ identifié dans tous les âges","Maintenant, écoutez, ne priez pas pour vous-même, parce que la personne qui vous a imposé les mains est en train de prier pour vous. Voyez, priez pour elle, et moi, je vais prier pour vous tous. Et si vous croyez réellement cela d’un commun accord, ceci sera l’un des plus glorieux moments que vous ayez jamais connus."],["sermons/1956/56-1215.html?q=pri%C3%A8re#s90","56-1215 § 29 — Écoutez-le","J’ai dit : « Tantine, le Seigneur Jésus a guéri votre enfant. Il s’agit de votre prière, pas la mienne, c’est vous qui êtes en train de prier. Je n’ai même pas offert une prière pour cette enfant, mais Dieu a exaucé votre prière. Je vois l’enfant dans une vision. »"],["sermons/1955/55-0604.html?q=pri%C3%A8re#s15","55-0604 § 4 — Jaïrus, le croyant en secret","Eh bien, nous apprécions vos prières. La prière change les choses. Il n’y a qu’une seule chose qui peut changer la pensée de Dieu et c’est la prière ; Dieu peut pourtant dire quelque chose, et la prière peut–peut la changer. Ça c’est un très bon morceau, n’est-ce pas ? Mais c’est la vérité."],["sermons/1959/59-0415E.html?q=pri%C3%A8re#s175","59-0415E § 78 — La foi d’Abraham","Maintenant, calmement, formez une ligne de prière ici même et préparez-vous à y entrer pour la prière pendant que nous prions. Les autres parmi vous… Tous ceux qui ont les cartes de prière, avec respect, mettez-vous le long du mur. Que les huissiers aillent là les aider, et nous aimerions nous occuper de chaque carte de prière que nous avons."],["sermons/1948/48-0302.html?q=pri%C3%A8re#s577","48-0302 § 122 — Expériences","Et nous sommes… Maintenant, nous allons faire passer les gens, et parcourir toute la ligne. J'aimerais prier pour chacun de vous. J'aimerais prier, pas juste vous faire passer sans prier pour vous. J'aimerais offrir une petite prière pour vous, mais nous allons devoir entreprendre une marche constante, comme cela."]],[["sermons/1955/55-0302.html?q=gu%C3%A9rison#s286","55-0302 § 89 — Le rideau du temps","Ayez la foi. Ne doutez pas. Vous voulez être guérie de cette arthrite, vous qui êtes assise juste là au fond ? Levez-vous ; votre foi vous a guérie, soeur. C’est juste, levez-vous, levez les mains et que les gens voient que vous êtes guérie. Absolument, vous en êtes délivrée maintenant. Amen. Votre foi vous guérit. Amen. Ayez foi en Dieu ; ne doutez pas."],["sermons/1957/57-0407M.html?q=gu%C3%A9rison#s335","57-0407M § 85 — Dieu tient sa Parole","Or, votre guérison n’est pas aussi permanente que votre salut. Votre guérison vous fera défaut. Vous pouvez être... Si vous êtes guéri, vous serez encore malade. Vous pourriez être guéri aujourd’hui d’une pneumonie, être en parfaite santé et bien portant, déclaré « bien portant » par le médecin, et mourir de la pneumonie la semaine prochaine. C’est vrai."],["sermons/1962/62-0729.html?q=gu%C3%A9rison#s110","62-0729 § 36 — Être persévérant","Vous ne pouvez pas faire mentir la Parole de Dieu. Il a dit : « Je suis l’Eternel ton Dieu qui guérit toutes tes maladies. » Et on n’a jamais eu un médicament qui guérit. Aucun médecin ne déclare que cela guérit. Cela tue seulement les germes pendant que Dieu guérit. Cela nettoie seulement la plaie, ou–ou quelque chose comme cela."],["sermons/1953/53-1206E.html?q=gu%C3%A9rison#s330","53-1206E § 93 — Vous croyez maintenant ?","Combien de gens souffrent de la nervosité ici dans la salle ? Levez la main. Approchez, soyez sincère. Chacun de vous peut être guéri maintenant même, tout aussi facilement que cette femme, et chacun de vous peut être guéri. C’est l’exacte vérité, chacun de vous peut être guéri maintenant juste comme cette femme sera guérie."],["sermons/1960/60-0713.html?q=gu%C3%A9rison#s167","60-0713 § 54 — L’aveugle Bartimée","Oh ! Depuis quand les jours des miracles sont-ils passés ? Quand les jours des miracles sont passés, les jours de Dieu sont passés, car qui dit Dieu dit miracles. Certainement, les jours des miracles ne passeront jamais, ne sont jamais passés et ne passeront jamais. Mais les gens disaient que–que les jours des miracles étaient passés."],["sermons/1957/57-0228.html?q=gu%C3%A9rison#s10","57-0228 § 5 — Il y a ici plus que Salomon","De nos jours, tant de choses ont été dites au sujet de la guérison, et cela a été abordé de différentes manières. Et il semble y avoir tellement de confusion au sujet de la guérison. Comme j’ai essayé hier soir de tout mon coeur de faire comprendre cela, il n’existe aucune autre guérison à part la guérison divine. Dieu seul opère la guérison."],["sermons/1960/60-1127E.html?q=gu%C3%A9rison#s108","60-1127E § 33 — La reine du midi","C’est comme avec la Parole de Dieu. C’est la guérison pour ceux qui peuvent la recevoir comme guérison, mais elle n’est pas la guérison pour ceux qui ne peuvent pas la recevoir comme guérison. C’est le pardon du péché pour ceux qui croient qu’ils sont pardonnés du péché, mais cela ne fera aucun bien à ceux qui ne reçoivent pas cela comme tel."],["sermons/1953/53-0219.html?q=gu%C3%A9rison#s23","53-0219 § 11 — Accepter le don de Dieu (les oeuvres que je fais rendent témoignage)","Bon, c'est la même chose pour la guérison. Acceptez-Le comme votre Guérisseur, renoncez à vos sensations. Ce n'est pas par les sensations; c'est par la foi. Dites que vous êtes guéri; croyez que vous êtes guéri; agissez comme si vous étiez guéri; associez-vous à ceux qui croient dans la guérison, et Dieu vous amènera directement à une parfaite santé : Il ne faillira pas."],["sermons/1953/53-0216.html?q=gu%C3%A9rison#s23","53-0216 § 11 — Les oeuvres que je fais rendent témoignage","Bon, c’est la même chose pour la guérison. Acceptez-Le comme votre Guérisseur, renoncez à vos sensations. Ce n’est pas par les sensations; c’est par la foi. Dites que vous êtes guéri ; croyez que vous êtes guéri ; agissez comme si vous êtes guéri ; associez-vous à ceux qui croient dans la guérison, et Dieu vous amènera directement à une parfaite santé : Il ne faillira pas."],["sermons/1959/59-0407.html?q=gu%C3%A9rison#s117","59-0407 § 36 — Conduit par l’Esprit","Eh bien, vous êtes déjà guéri, chacun de vous. Mais la seule raison pour laquelle vous ne pouvez pas accepter cela, c’est peut-être parce que vous tenez à passer par la formalité de l’imposition des mains. C’est bien. Mais cela ne vous guérit pas. Vous–vous êtes guéri par votre foi dans l’oeuvre achevée par Dieu pour vous au Calvaire. C’est par là que vient votre guérison."],["sermons/1961/61-0218.html?q=gu%C3%A9rison#s181","61-0218 § 52 — Du baume en Galaad","Eh bien, si le médicament guérit le corps humain, pourquoi ne guérit-il pas cela ? « Eh bien, direz-vous, c’est parce que vous n’avez pas de vie. » Donc, ce n’est pas le médicament qui guérit ; c’est la vie qui guérit. Dites-moi alors ce qu’est la vie, je vous dirai qui est Dieu. Dieu est la Vie. Tout à fait."],["sermons/1965/65-0117.html?q=gu%C3%A9rison#s139","65-0117 § 102 — Un paradoxe","Il a guéri le malade, qui était... qui avait la lèpre. En fait, jusqu’à ce jour, on n’a rien trouvé, la science n’a rien pour soigner la lèpre, mais Jésus a guéri cela par Sa Parole. C’était un paradoxe. Et Il est le même hier, aujourd’hui et éternellement. Sa Parole guérit toujours les malades. C’est un paradoxe, certainement."]],[["sermons/1959/59-0329M.html?q=bapt%C3%AAme#s63","59-0329M § 44 — Le baptême d’eau","Si donc Pierre a dit : « Repentez-vous, et que chacun de vous soit baptisé au Nom de Jésus-Christ », et qu’après cela tous furent baptisés au Nom de Jésus-Christ, alors que Jésus a dit : « Allez baptiser au Nom du Père, du Fils et du Saint-Esprit », cela semble être une contradiction flagrante ; mais ce n’est pas le cas, si seulement vous comprenez."],["sermons/1957/57-0825E.html?q=bapt%C3%AAme#s181","57-0825E § 208 — Hébreux chapitre 2, 2","Dans Actes 2:38, les Juifs furent baptisés au Nom du Seigneur Jésus-Christ par immersion. Et dans Actes chapitre 8, nous voyons que Philippe descendit prêcher aux Samaritains, et qu’il les baptisa au Nom du Seigneur Jésus-Christ. Les Samaritains. Et dans Actes 10:49, Pierre ordonna aux Gentils d’être baptisés au Nom du Seigneur Jésus-Christ."],["sermons/1958/58-0928M.html?q=bapt%C3%AAme#s138","58-0928M § 87 — Le baptême du Saint-Esprit le Saint-Esprit explique (le nom de Jésus)","Donc, ils ont commencé une dénomination, ce qui était faux. Ensuite, la chose suivante qu’ils ont amenée et qui était une erreur, c’était le baptême d’eau. Le baptême d’eau, tel que l’enseigne la Bible, est par immersion, mais l’Eglise catholique a amené l’aspersion ou le fait de verser, or il n’y a aucun passage de l’Ecriture dans la Bible qui appuie l’aspersion ou le fait de verser, il n’y a aucun passage dans la Bible. C’est par immersion."],["sermons/1962/62-0422.html?q=bapt%C3%AAme#s343","62-0422 § 167 — La restitution de l’abre-épouse","Le baptême d’eau. Là où ils ont reçu l’ordre de... Le jour de la Pentecôte, Pierre, sous l’influence du Saint-Esprit, a proclamé la Parole de Dieu, disant : «Repentez-vous, que chacun de vous soit baptisé au Nom de Jésus-Christ pour le pardon de vos péchés.»"],["sermons/1961/61-0129.html?q=bapt%C3%AAme#s67","61-0129 § 20 — Se tourner vers le nord","A présent, quant à ces réveils jumeaux, l’un produit un homme qui veut être un intellectuel et bâtir des écoles. Ils essayent d’éviter cette question de la nouvelle naissance. L’église essaye de l’éviter. Aujourd’hui, on reçoit les gens par le baptême d’eau, on les introduit dans l’église au moyen du baptême d’eau. Vous pourriez les introduire dans l’église au moyen du baptême d’eau, mais vous ne les introduirez jamais en Christ au moyen du baptême d’eau. On doit y naître de l’Esprit. C’est vrai."],["sermons/1953/53-0329.html?q=bapt%C3%AAme#s11","53-0329 § 10 — Israël dans sa patrie","On baptisera ce soir. Nous sommes des «baptistes», quant à la façon de baptiser. Nous devons simplement être scripturaires, c’est tout. Pas exactement des baptistes; mais l’Ecriture... Nous croyons au baptême par immersion. Et, maintenant, si vous ne croyez pas cela de cette façon, il n’y a malgré tout pas de problème. Mais nous croyons cela, le baptême d’eau par immersion."],["sermons/1961/61-0903.html?q=bapt%C3%AAme#s39","61-0903 § 12 — Que votre lumière luise ainsi devant les hommes","Et aussi, j’ai quelques personnes à baptiser au Nom de notre Seigneur Jésus-Christ, des trappeurs et–et le reste, lorsque je serai là-bas, des trappeurs norvégiens et ainsi de suite, que le... Ils ont vu la Lumière grâce à ces bandes qui ont été envoyées, et ils veulent que je les baptise au Nom de Jésus-Christ."],["sermons/1954/54-0513.html?q=bapt%C3%AAme#s141","54-0513 § 117 — La marque de la bête","Maintenant, regardez bien comment ça se retrouve de ce côté-ci. Ici, vous avez quoi? Un substitut du Saint-Esprit : une hostie. Un substitut du baptême d’eau au Nom de Jésus-Christ : Père, Fils, Saint-Esprit. Ils ont tout remplacé. Je peux prendre ça et le prouver par l’Ecriture; substitut après substitut."],["sermons/1959/59-0628E.html?q=bapt%C3%AAme#s202","59-0628E § 140 — Questions et réponses","Eh bien, ça c’est un point délicat. Maintenant, je sais que je m’adresse aux gens qui seront en désaccord avec ceci, mais en tant que Chrétien, je dois le dire. Il n’y a aucune autorité scripturaire dans la Bible concernant le baptême d’eau au nom du Père, Fils et Saint-Esprit. Personne dans la Bible n’a jamais été baptisé au nom du Père, Fils, Saint-Esprit. C’est une tradition catholique enseignée au sixième siècle."],["sermons/1962/62-1230E.html?q=bapt%C3%AAme#s272","62-1230E § 119 — Monsieur, est-ce le signe de la fin?","Le mystère du baptême d’eau, que le trinitarisme extrême a changé en des titres de Père, Fils et Saint-Esprit; et le mystère de la divinité s’accomplissant dans le baptême au Nom de Jésus-Christ, selon le Livre de l’Apocalypse, que l’Eglise, en ce temps, devait recevoir. Voilà certains des mystères."],["sermons/1961/61-1119.html?q=bapt%C3%AAme#s11","61-1119 § 11 — La force parfaite par la faiblesse parfaite","Notre–notre responsabilité est de prêcher la Parole. La Bible dit: «Tous ceux qui crurent furent baptisés.» Repentez-vous, et soyez baptisés au Nom de Jésus-Christ pour la rémission, le pardon des péchés. Quoi? Soyez baptisés au Nom de Jésus-Christ pour le pardon des péchés, voyez, et vous recevrez alors le don du Saint-Esprit."],["sermons/1954/54-0515.html?q=bapt%C3%AAme#s500","54-0515 § 352 — Questions et réponses","Et nous vous contraignons, mon cher frère chrétien ou ma chère soeur chrétienne à être baptisé au Nom de Jésus-Christ et à recevoir le Saint-Esprit. Si vous avez déjà reçu le Saint-Esprit après que vous avez été baptisé au nom du Père, du Fils et du Saint-Esprit, que Dieu vous bénisse! Vous direz: «Frère Branham, que devrais-je faire à ce sujet?» On a répondu à cette question. Je ne peux que dire comme Paul; vous devez être rebaptisé!"]],[["sermons/1950/50-0819.html?q=Sang#s84","50-0819 § 23 — Montre-nous le père et cela nous suffit","Du haut des cieux, Dieu regarda en bas et dit : « C’est ce qu’il faut. » Le sang parle ; de quoi parlait-il ? Des années plus tard, l’Agneau de Dieu allait être conduit. Le Sang… Vous êtes le sang de votre père et de votre mère. Mais par la nouvelle naissance, vous êtes devenu le Sang de Dieu, le Sang de Christ nous purifiant."],["sermons/1954/54-0720E.html?q=Sang#s127","54-0720E § 46 — C’est moi, n’ayez pas peur","Dieu Tout-Puissant, au Nom de Ton Fils Jésus-Christ, je condamne ce démon qui suce le sang. Et puissent la croix du Calvaire et la transfusion de sang… et que ce diabète sucré se change en un état normal d’un bon sang riche, au Nom de Jésus-Christ et par Son Sang. Amen. Partez sans douter de quoi que ce soit, et en vous réjouissant. Très bien."],["sermons/1963/63-0317M.html?q=Sang#s202","63-0317M § 184 — Dieu se cache, puis se révèle dans la simplicité","C’était cependant simple. Dans sa simplicité, il savait qu’il était né du sang de sa mère et de son père, qu’il était né du sang de sa mère par le sang de son père ; et c’était le sang qui avait causé la chute, c’était donc le sang qui devait rétablir cela. « Alors, il offrit à Dieu un sacrifice plus excellent, parce que cela lui avait été révélé. »"],["sermons/1961/61-0414.html?q=Sang#s110","61-0414 § 48 — N’ayez pas peur, c’est moi","S’Il était le sang d’un homme, alors Il n’est pas plus que moi ou vous. Mais Il est le Sang de Dieu. Le Saint-Esprit de Dieu a couvert la vierge de Son ombre et a créé une cellule de Sang, et c’est le Sang de Dieu. La Bible dit que nous sommes sauvés par le Sang de Dieu, pas celui d’un homme, de Dieu. Mais les gens renient cela."],["sermons/1961/61-0412.html?q=Sang#s142","61-0412 § 45 — Il y a ici plus que Salomon","Mais, Seigneur, ce soir, à Tes propres yeux, Tu as confié entre mes mains un trésor plus grand que ce Sang-là, pour Toi. En effet, Tu as confié entre mes mains ce soir les rachetés par ce Sang-là, car Tu as eu plus de considération pour Ton peuple que Tu en as eue pour Ton propre Sang ; c’est pourquoi Tu as répandu Ton Sang pour eux."],["sermons/1955/55-0223.html?q=Sang#s99","55-0223 § 32 — Job, serviteur de Dieu","Maintenant, ensuite le sang était appliqué sur le linteau de la porte à l’aide de l’hysope. Et alors, les Israélites étaient à l’intérieur. Il n’y avait plus rien qu’ils devaient faire, si ce n’est de venir sous le sang. C’était le plan de la rédemption de Dieu, sous le Sang, et une fois sous le Sang, on est en sécurité."],["sermons/1963/63-0731.html?q=Sang#s283","63-0731 § 253 — Il y a une seule voie à laquelle Dieu a pourvu pour tout","Et maintenant, Satan, je t’ordonne, par le Sang de Jésus-Christ, ce Sang tout suffisant ; par cette Vie qui était dans ce Sang-là, qui est maintenant dans nos coeurs, nous sommes changés de ce que nous étions autrefois en des chrétiens. Autrefois, nous étions des incrédules, maintenant nous sommes des croyants. Nos péchés sont sous le Sang."],["sermons/1963/63-1128E.html?q=Sang#s64","63-1128E § 59 — Le signe","Elle ne pouvait pas venir par le sang chimique de l’agneau, parce qu’il n’y avait là rien qui pouvait revenir; ce n’était que de la chimie. On ne pourrait pas transférer ce sang dans un être humain. Ça ne marcherait pas, le sang d’un animal ne peut pas passer dans le sang humain. Ainsi les éléments chimiques ne pouvaient pas agir, ce qui montre que c’était une ombre."],["sermons/1954/54-1204.html?q=Sang#s45","54-1204 § 17 — Dieu amène son église a la perfection","Là, cette cellule de Sang a continué à grandir, pour engendrer le corps de Jésus-Christ. Jéhovah Lui-même tabernaclait en Lui afin que, par le brisement de cette cellule de Sang au Calvaire, Il puisse engendrer des fils et des filles, de la cellule de Sang au Sang du Seigneur Jésus-Christ en Lui-même. Et nous devenons une partie de Dieu. Amen."],["sermons/1963/63-0428.html?q=Sang#s121","63-0428 § 115 — Regarde","C’était le sang qui avait engendré un enfant. C’était uniquement le sang, uniquement. Le sang vient du sexe mâle. Le sang vient de l’homme. La femme, elle produit l’ovule, une matière de remplissage. Mais l’homme, c’est l’hémoglobine; en fait, c’est de là que vient le germe. Et dans le germe, il y a–il y a la vie."],["sermons/1950/50-0716.html?q=Sang#s98","50-0716 § 27 — Crois-tu cela ?","Nous sommes sauvés par le Sang de Dieu. Le… Nous sommes le sang de notre père. Jésus était le Sang de Son Père, qui était le Sang saint et sans mélange, non pas par le désir sexuel, mais c’est par le Saint-Esprit qu’Il est né, qu’Il a été conçu dans le sein de Marie, et Il est né. Je crois cela de tout mon coeur."],["sermons/1964/64-0208.html?q=Sang#s39","64-0208 § 37 — Le signe","Le sang chimique ne pouvait pas être aspergé sur chaque coeur, nous savons cela ; en effet, il a été versé au Calvaire. Il a été répandu au sol. Mais là… Quand cette cellule de Sang a été brisée, elle a libéré Dieu au travers de la puissance sanctificatrice, pour montrer que le Sang était revenu sur les croyants."]],[["sermons/1957/57-0519E.html?q=amour#s170","57-0519E § 52 — L’amour","C’est l’amour, frère, l’amour opère le stratagème. C’est l’amour qui fait cela. Il y a quelque chose de noble là. Dieu veut que vous preniez cet amour et qu’avec cela, vous soyez brave, non pas l’amour à conserver pour vous-même. Manifestez votre amour. Prouvez votre amour. Montrez mon… votre amour par vos oeuvres. Vous y êtes. Prouvez que vous aimez Dieu."],["sermons/1954/54-0103E.html?q=amour#s258","54-0103E § 178 — Questions et réponses","Je vais vous fixer sur cela dans quelques minutes. Dieu est amour; l’amour parfait; mais vous ne savez pas ce que c’est que l’amour. Voilà pourquoi les gens ne savent pas aujourd’hui ce que c’est que la foi. Dieu est amour. Il doit aimer; Il est souverain quant à Sa Parole. Et Il faut qu’ Il tienne Sa Parole. Il faut qu’ Il vous aime. Et s’Il vous aime, Il doit vous protéger."],["sermons/1958/58-0313.html?q=amour#s23","58-0313 § 12 — L’amour","Mais l’amour agapao vous amènerait à prier pour l’âme pécheresse de cet homme. Voilà la différence entre les deux amours. L’amour de Dieu est le commencement de l’amour. C’est la fontaine de l’amour. Et c’est ce qui manque à l’église aujourd’hui, ce véritable amour agapao qui vous fait aimer vos ennemis."],["sermons/1962/62-0610M.html?q=amour#s261","62-0610M § 67 — Présumer","Qui peut avoir plus de gentillesse et avoir plus de ce qu’on appelle amour que la science chrétienne ? C’est tout ce qui les préoccupe, l’amour. Ce n’est pas le véritable amour. Ils nient même que Jésus était divin, ils nient la mort, la naissance, la–la naissance virginale, ils nient Son Sang ; et ils ne parlent que de l’amour."],["sermons/1957/57-0419.html?q=amour#s20","57-0419 § 18 — La perfection","Mais si nous rentrons donc un peu plus loin en arrière, nous découvrons les attributs même de Dieu… La Bible nous dit clairement que Dieu est amour. Mais cependant, étant amour, Il doit être juste. Ainsi, l’amour ne signifie pas quelque chose qui peut être chouchouté et avec lequel on peut jouer. L’amour, c’est la justice de Dieu."],["sermons/1955/55-0610.html?q=amour#s75","55-0610 § 27 — Vous croyez maintenant","Eh bien, prenez par exemple l’amour phileo, lorsque vous l’avez, cet amour-là, avec cet amour-là, une mère entrera directement dans des flammes de feu pour sauver la vie de cet enfant. Cela amènera un homme à sacrifier sa vie n’importe quand pour sa chérie. Voyez-vous ce que je veux dire ? C’est… C’est tout simplement l’amour humain."],["sermons/1957/57-0725.html?q=amour#s54","57-0725 § 15 — Écoutez-le","Des hommes qui, dans tous les âges, ont essayé d’expliquer ce grand amour de Dieu, c’est aussi insondable que les cieux. Il n’y a donc aucun moyen d’essayer, nulle part, aucun homme, d’entreprendre, d’expliquer les profondeurs de l’amour de Dieu. Car Dieu est Amour. Son Etre même est amour. Il est la Fontaine de l’amour."],["sermons/1955/55-0123E.html?q=amour#s98","55-0123E § 20 — Combattre ardemment pour la foi","Maintenant, suivez. Croyez-vous que Jésus avait de la compassion ? Il était plein d’amour. Mais, parfois c’est simplement comme les gens qui s’aiment. Ils oublient de quel genre d’amour ils parlent. L’amour phileo et l’amour agapao : un… les deux sont l’amour, mais l’un, c’est l’amour d’En Haut, et l’autre c’est l’amour d’ici sur la terre."],["sermons/1955/55-0220E.html?q=amour#s122","55-0220E § 46 — Combattre pour la foi","Et ainsi, Jésus, plein d’amour et de compassion, passait au milieu de ces gens, avec amour et compassion… Mais, quand nous pensons : « Ce pauvre vieil homme couché là. Ce pauvre petit enfant mourant là. » C’est ça. C’est l’amour agapao. Ça, c’est l’amour. C’est la compassion que nous éprouvons, humainement parlant."],["sermons/1958/58-0209A.html?q=amour#s62","58-0209A § 21 — Écoutez-le","Et remarquez donc ceci après qu’Il les eut amenés là-haut. Il avait amené Pierre, Jacques et Jean. J’aime me référer à eux comme l’espérance, la foi et la charité. Jacques, c’est l’espérance. Pierre, la foi. Jean est le disciple de l’amour, la charité. L’espérance, la foi et la charité."],["sermons/1960/60-1225.html?q=amour#s143","60-1225 § 82 — Le don enveloppé de Dieu","L’Eglise ne veut pas de Cela. Ils veulent des credos. Nous avons besoin de l’amour. L’Eglise se meurt par des credos. Elle ne peut vivre que par l’amour, parce que l’amour est la Vie Eternelle. L’amour conquiert tout. L’amour est la force la plus puissante qui existe. Non, ils n’ont pas voulu de Lui, parce qu’ils savaient ce qui était dans ce Don."],["sermons/1955/55-0311.html?q=amour#s93","55-0311 § 32 — Le sceau de l’antichrist","L’amour... Dieu est amour. «L’amour est patient; l’amour ne s’irrite point; l’amour ne s’enfle pas d’orgueil.» Quand vous vous enflez d’orgueil, l’amour s’en va. Et quand il y a toute cette malice, ces luttes, ces guerres, cette envie et cette malice les uns vis-à-vis des autres, frère, Dieu S’en va tout simplement, c’est tout. Et c’est un fait; vous pouvez voir cela. Amen."]],[["sermons/1964/64-0207.html?q=ob%C3%A9issance#s4","64-0207 § 2 — Le patriarche Abraham","Quelle promesse à cause de l’obéissance! L’obéissance, c’est ce que Dieu exige. Il a été dit une fois: «L’obéissance vaut mieux que les sacrifices.» Obéir au Seigneur vaut mieux que n’importe quel sacrifice que vous pourriez offrir."],["sermons/1955/55-0301.html?q=ob%C3%A9issance#s237","55-0301 § 65 — Elie","Maintenant, soyez respectueux. Vous dites : «Qu’est-ce qui fait cela, Frère Branham?» Il s’agit de se soumettre à l’Esprit de Dieu, savoir juste se soumettre. Et vous, faites de même. Vous pourriez ne pas être en mesure d’avoir des visions, mais vous pouvez vous soumettre pour que le Saint-Esprit travaille."],["sermons/1960/60-0804.html?q=ob%C3%A9issance#s243","60-0804 § 62 — Pareil à l’aigle qui éveille sa couvée","Oh ! la la ! Dieu n’a pas peur de soumettre Ses aigles à–à une épreuve d’envol. Il n’a pas peur ; Il compte sur vous. Il n’a pas eu peur de soumettre Abraham à une épreuve d’envol. Il comptait sur lui. Il n’a pas peur de soumettre la postérité d’Abraham à une épreuve d’envol, car Il compte sur vous."],["sermons/1957/57-0725.html?q=ob%C3%A9issance#s120","57-0725 § 26 — Écoutez-le","Combien cela plaît à Dieu de trouver Ses enfants obéissant à Sa Parole ; non pas aux petits ismes, mais obéissant à la Parole ; pas obéissant à l’église, obéissant à la Parole. C’est la chose qui va subsister, Ceci est le patron, Ceci est le standard, Ceci est l’unique chose. « Celui qui retranchera ou ajoutera, sa part sera retranchée du Livre de Vie. » Je ne veux rien de moins que ce que cette Bible a, ça se trouve ici même, et je ne veux rien d’autre ; je veux exactement ce qu’Elle dit."],["sermons/1963/63-1103.html?q=ob%C3%A9issance#s177","63-1103 § 154 — Allez réveiller Jésus","Eh bien, ils auraient dû savoir qu’Il devait... que tout devait Lui obéir. Nous devrions savoir la même chose. Nos corps devront obéir à Sa Parole. « Je suis l’Eternel qui te guérit de toutes tes maladies. » Est-ce la Parole ? Eh bien, ce corps doit obéir à cela."],["sermons/1957/57-0317.html?q=ob%C3%A9issance#s21","57-0317 § 21 — Écoutez-le","Et vous les prédicateurs ici, je parle du placement d’un fils, vous savez, dans la Bible. Maintenant, dans Galates, ou plutôt Ephésiens 1.5 : « Car Dieu nous a prédestinés à l’adoption, ou au placement des fils, par Jésus-Christ. » Eh bien, il était un fils pour commencer, mais maintenant, il est donc si obéissant. Laissez-le être dans n’importe quelle dénomination, cela n’a rien à faire avec la chose. Il s’agit de l’obéissance à la Parole, de l’obéissance à Dieu."],["sermons/1960/60-0228.html?q=ob%C3%A9issance#s69","60-0228 § 27 — Les conférences","Après avoir obéi à Dieu, avoir accompli la mission qu’Il nous a confiée, parfois nous rencontrons des circonstances difficiles. C’est ce que Moïse a connu. Il est descendu en Egypte et il a exécuté exactement les ordres de Dieu ; il a obéi à la lettre à la Parole, et il suivait la Parole."],["sermons/1964/64-0208.html?q=ob%C3%A9issance#s123","64-0208 § 118 — Le signe","L’obéissance totale à toute la Parole de Dieu nous donne droit au Signe. Il n’y a pas un autre moyen par lequel on peut avoir droit au Signe avant d’avoir pleinement obéi à la Parole. Ce n’est pas ce que quelqu’un d’autre a injecté à Cela, ajouté à Cela, mais ce que Dieu a dit à ce sujet."],["sermons/1963/63-0801.html?q=ob%C3%A9issance#s45","63-0801 § 40 — Un paradoxe","Vous ne pouvez rien cacher, lorsque Dieu a ordonné la chose. Elle doit obéir à Dieu, lorsque Dieu donne l’ordre. C’est la raison pour laquelle je sais qu’Il aura « une Eglise sans tache ni ride ». Dieu l’a ordonné. Cela devra obéir. Dieu aura cela, car c’est ce que dit la Parole de Dieu."],["sermons/1954/54-0402.html?q=ob%C3%A9issance#s20","54-0402 § 9 — L’aveugle Bartimée","Juste comme le serpent d’airain. Eh bien, le serpent n’avait pas de vertu en lui ; c’était un morceau d’airain qu’ils ont amené depuis l’Egypte. La perche non plus n’avait aucune vertu en elle, pas du tout. Mais c’était l’obéissance à ce que Dieu ordonnait qui produisait la puissance, qui produisait la vertu, c’est l’obéissance à la Parole de Dieu. Et c’est pareil ce soir."],["sermons/1961/61-0209.html?q=ob%C3%A9issance#s128","61-0209 § 47 — Jéhovah-Jiré","Maintenant, nous voyons ensuite qu’il s’est séparé. Et Dieu n’avait jamais pleinement béni Abraham avant qu’il ne Lui ait totalement obéi et qu’il ne se soit séparé. Et Dieu ne bénira jamais une personne, une église, une assemblée ou une dénomination avant qu’elle ne se soit totalement abandonnée à Dieu, en Lui obéissant."],["sermons/1961/61-0318.html?q=ob%C3%A9issance#s207","61-0318 § 130 — L’alliance confirmée d’Abraham","Puis, il a dit : «Isaac, mets les mains derrière toi.» Il prit une corde et se mit à lui lier les mains. Alors, Isaac comprit. Observez son obéissance pareille à celle de Jésus, le véritable Fils de Dieu, obéissant jusqu’à la mort; Il prit la croix. Il lui lia les mains et les pieds. Abraham souleva le petit garçon et le plaça sur le rocher."]],[["sermons/1957/57-0908E.html?q=pr%C3%A9destination#s90","57-0908E § 294 — Hébreux chapitre 6, 2","Et ensuite Christ mourut pour sauver ceux que Dieu, par prescience, avait élus, afin qu’ils Le rencontrent là-bas sans tache ni ride. Avant la fondation du monde, Il vous a vu dans la Gloire. C’est ce que dit la Bible, Ephésiens, chapitre 1... chapitre 5, verset 1. Dieu a prédestiné par la prescience."],["sermons/1958/58-0328E.html?q=pr%C3%A9destination#s40","58-0328E § 13 — Écoutez-le","Mais premièrement, il devait être éprouvé, ou élevé, ou instruit. Galates 4, Paul en parle. Et c’était le placement du fils. Nous trouvons cela dans Ephésiens 1.5 : Nous avons été prédestinés à l’adoption des fils par Jésus-Christ. Dieu, par Sa prescience, a prédestiné cela, Ses enfants par l’adoption en Jésus-Christ, ou plutôt par Jésus-Christ."],["sermons/1957/57-0322.html?q=pr%C3%A9destination#s75","57-0322 § 45 — Écoutez-le","Galates 1 nous dit que nous étions prédestinés à l’adoption des fils par Jésus-Christ, prédestinés par Dieu, quoique beaucoup soient appelés mais peu sont élus. Les élus ont été élus au commencement. Eh bien, nous avons cependant été prédestinés à l’adoption des enfants de Dieu par Jésus-Christ."],["sermons/1947/47-0412-2.html?q=pr%C3%A9destination#s110","47-0412 § 38 — Notre position en Christ","Maintenant, regardez. Il nous a élus dans ce but, nous ayant prédestiné ou plutôt par la prescience, il a compris à l’avance ce que cela serait dès le commencement. Dieu, au commencement, sachant exactement ce qu’Il ferait à la fin, Il prédestina ou prédit ce que cela serait : c’est la prescience, savoir d’avance ce que cela serait d’être en Jésus Christ."],["sermons/1958/58-0927.html?q=pr%C3%A9destination#s111","58-0927 § 72 — Pourquoi nous ne sommes pas une dénomination ?","Je souhaiterais prêcher un sermon maintenant même là-dessus: les élus avant la fondation du monde, qui demeurent fidèles à leur appel. Alléluia! C’est cela. Ce sont les appelés, les élus et les fidèles. «Et» est une conjonction, voyez-vous? Les élus et les fidèles. Ils les vaincront. Peu importe combien ils deviennent importants."],["sermons/1962/62-1122.html?q=pr%C3%A9destination#s70","62-1122 § 35 — Le retour et le jubilé","Maintenant, nous voyons où nous en arrivons. Très bien! Souvenez-vous, les fils demeurent. Ils sont là pour toujours. Ils y sont amenés par prédestination (Ephésiens 1:5) : «Prédestinés à l’adoption des enfants par Jésus-Christ avant la fondation du monde». Ce sont des fils qui sont nés dans l’Eglise de Dieu, et ils y restent à jamais parce qu’ils y sont nés. C’est vrai."],["sermons/1958/58-0316E.html?q=pr%C3%A9destination#s238","58-0316E § 84 — La porte du coeur","Il ne veut pas, mais Sa prescience le Lui fait connaître. Il ne dit pas simplement : « Je vais sauver celui-ci et perdre celui-là. » Il veut que vous soyez tous sauvés, mais Sa prescience connaît qui le serait ; ainsi donc, Il pouvait prédestiner selon Sa prescience, et c’est ça l’élection. Jésus est venu, et les derniers à être sauvés seront sauvés ; l’Eglise rentrera à la Maison."],["sermons/1961/61-0117.html?q=pr%C3%A9destination#s183","61-0117 § 57 — Le Messie","L’autre jour, j’ai entendu Billy Graham dire dans un message, il a dit: «Les élus sont déjà séduits.» Non, non. Les élus ne seront pas séduits. Non. Non. Ils ne le seront pas. Non. Les membres de l’église le seront, mais pas les élus. Ils ont été choisis avant la fondation du monde. Ils ne peuvent pas être séduits. Hébreux 6 dit que c’est impossible. Ils ne seront pas séduits."],["sermons/1963/63-0721.html?q=pr%C3%A9destination#s147","63-0721 § 129 — Il prend soin. et vous ?","Bon, Il a fait cela aux–aux élus. Eh bien, nous le savons. Il a fait cela aux élus, uniquement aux élus, donc ! C’était eux qui avaient accepté ce germe de la Vie. C’était eux qui étaient prédestinés à voir cela. C’était eux. Nous tous, si nous croyons la Bible, il nous faut croire la prédestination. Voyez ? C’est vrai. Dieu ne veut qu’aucun périsse, mais Il savait qui accepterait cela et qui ne l’accepterait pas."],["sermons/1960/60-0518.html?q=pr%C3%A9destination#s140","60-0518 § 115 — Les fils de Dieu manifestés","Bon, maintenant nous y sommes. Or, voici ce qui froisse un peu les pentecôtistes. Ils disent : « Je suis né de nouveau ! Gloire au Seigneur, j’ai reçu le Saint-Esprit ! » Très bien. Vous êtes un enfant de Dieu. C’est vrai. Néanmoins ce n’est pas de ça que je parle. Vous voyez, vous avez été prédestiné à l’adoption. L’adoption, c’est le fait de placer un fils."],["sermons/1959/59-0424A.html?q=pr%C3%A9destination#s20","59-0424A § 18 — Le fidèle Abraham","Dieu rencontra Abraham, Il l’appela par élection, et nous avons vu que nous aussi nous sommes appelés par élection. Dieu, par Sa prescience, connaissait à l’avance toute chose, et nos noms ont été écrits dans le Livre de Vie de l’Agneau avant la fondation du monde."],["sermons/1955/55-0118.html?q=pr%C3%A9destination#s104","55-0118 § 44 — David, le vaillant guerrier","Il connaissait sa position. Alléluia! Chaque David qui est assis ici ce soir, tu es dans ta position en Christ. Dieu a confirmé cela. L’élection, l’appel, l’onction, le placement... Il vous a élu et vous a appelé. Il vous a élu et Il vous a appelé. Ensuite, Il vous a oint du Saint-Esprit, et maintenant Il vous a placé dans le Corps de Christ, chacun de ces David."]],[["sermons/1954/54-0513.html?q=%C3%A2ges%20de%20l%27%C3%89glise#s3","54-0513 § 3 — La marque de la bête","Et hier soir, nous étions sur les âges de l’Eglise, Les Sept Âges de l’Eglise. Et le–et ç’a commencé avec l’âge de l’Eglise d’Ephèse, celui d’Ephèse ; et ça s’est terminé par l’âge de l’Eglise de Laodicée, le dernier âge de l’Eglise. Et que le Seigneur ajoute maintenant Ses bénédictions à la Parole, alors que nous parlons."],["sermons/1961/61-0210.html?q=%C3%A2ges%20de%20l%27%C3%89glise#s32","61-0210 § 24 — L’alliance confirmée d’Abraham","Et maintenant, afin que vous puissiez comprendre, nous sommes tous d’accord que nous vivons dans l’âge de l’Eglise de Laodicée; nous le savons tous. Eh bien, ne l’oubliez pas, au sujet de l’âge de l’Eglise de Laodicée, c’est le seul de tous les âges où Jésus a été mis à la porte par Sa propre Eglise, Il frappe à la porte pour essayer de rentrer."],["sermons/1955/55-0403.html?q=%C3%A2ges%20de%20l%27%C3%89glise#s207","55-0403 § 64 — La communion par la rédemption","Eh bien, la chose suivante : le Sang de ce substitut innocent était appliqué sept fois, comme cela comme un témoignage public. Sept est le chiffre de Dieu de l’achèvement. Sept âges de l’église. Les sept derniers âges de l’église: l’église de Philadelphie, l’église de Laodicée, et l’église... Chaque âge de l’église doit passer par ce même Sang versé."],["sermons/1963/63-0627.html?q=%C3%A2ges%20de%20l%27%C3%89glise#s211","63-0627 § 191 — Jésus-Christ est le même hier, aujourd’hui et éternellement","Le Livre d’Apocalypse, dans les Âges de l’Eglise, l’Age de l’Eglise de Laodicée, le septième ange était censé… Aux jours de la voix de cela, « le mystère de Dieu serait terminé. » Et nous sommes dans l’Age de Laodicée ; paresseux, mous, pas bons, tièdes, et c’est la condition de l’Eglise pentecôtiste. Dieu a agité devant elle chaque don qu’Il pouvait."],["sermons/1964/64-0125.html?q=%C3%A2ges%20de%20l%27%C3%89glise#s130","64-0125 § 112 — Allumez la lumière","Rappelez-vous, ceci est le septième âge de l’église, l’Age de l’Eglise de Laodicée. Conformément à Apocalypse 3, ils rejettent Christ. De tous les âges de l’église qui sont mentionnés dans la Bible, l’Age de Laodicée est le pire de tous. Il L’a mis dehors, L’a rejeté, L’a mis à l’extérieur."],["sermons/1965/65-0815.html?q=%C3%A2ges%20de%20l%27%C3%89glise#s55","65-0815 § 24 — Et tu ne le sais pas","Oh! la la! Ça, là, c’est un peu la description de l’Eglise d’aujourd’hui! Maintenant, c’est, je–je pense que cet âge de l’Eglise ici, dont nous parlons... Bien sûr, je ferai bientôt sortir l’âge de l’Eglise sous forme de livre. Mais étant donné qu’il s’agit de l’âge de l’Eglise de Laodicée dans lequel nous sommes, considérons juste sa condition."],["sermons/1954/54-0514.html?q=%C3%A2ges%20de%20l%27%C3%89glise#s50","54-0514 § 48 — Le sceau de Dieu","Puis, on a vu comment l’Eglise d’Ephèse a commencé, ensuite le deuxième âge de l’Eglise, le troisième âge de l’Eglise, le quatrième âge de l’Eglise, 1500 ans, les âges des ténèbres ; et on est passé par l’âge luthérien, l’âge de Philadelphie, jusqu’à l’âge de Laodicée, le dernier âge."],["sermons/1962/62-1124B.html?q=%C3%A2ges%20de%20l%27%C3%89glise#s58","62-1124B § 15 — Les investissements","Bien, nous pensons à l’âge de l’église d’Ephèse, à Sardes, à tous les âges de l’église tels qu’ils sont, même jusque dans l’âge de Philadelphie, l’âge de l’église wesleyenne, et ainsi de suite, même dans tous ces âges, Il n’était pas chassé. Mais dans l’âge de l’église de Laodicée, Il était dehors, mais Il continuait malgré tout à frapper, essayant de rentrer dans Sa propre Eglise."],["sermons/1960/60-1127E.html?q=%C3%A2ges%20de%20l%27%C3%89glise#s74","60-1127E § 23 — La reine du midi","Le lundi soir, ça sera sur l’Eglise d’Ephèse, et ensuite, Smyrne, Sardes, ainsi de suite, Thyatire, jusqu’au dimanche matin en huit, je parlerai sur l’Eglise de Laodicée. Et, entre-temps, il y aura une porte ouverte placée entre l’Age de l’Eglise de Philadelphie et l’Age de l’Eglise de Laodicée. Et c’est la porte dont nous aimerions parler au… à ce service-là."],["sermons/1954/54-0512.html?q=%C3%A2ges%20de%20l%27%C3%89glise#s231","54-0512 § 189 — Les sept âges de l’église","Maintenant, arrêtons-nous là juste une minute, car nous ne pouvons pas laisser ce tableau-là juste comme cela, voyez-vous. Regardez ces chandeliers qui sont là donc. Eh bien, ces chandeliers, comme nous le verrons un peu plus tard, représentent les sept âges de l’Eglise. Ils représentent Ephèse, Pergame, ainsi de suite jusqu’à Philadelphie, et tout jusqu’à Laodicée ; sept âges de l’Eglise."],["sermons/1965/65-0829.html?q=%C3%A2ges%20de%20l%27%C3%89glise#s35","65-0829 § 16 — L’Éden de Satan","Or, souvenez-vous, Il s’adresse à l’église de cet âge-ci : « Malheureuse, aveugle, nue, et elle ne le sait pas. » C’est cette dernière phrase, c’est cette dernière Parole, qui rend cela si frappant. Ils pensent être bien remplis de l’Esprit. Ils sont déjà... L’âge de l’Eglise de Laodicée, c’est l’âge de l’Eglise pentecôtiste, puisque c’est le dernier âge de l’Eglise."],["sermons/1960/60-1204E.html?q=%C3%A2ges%20de%20l%27%C3%89glise#s80","60-1204E § 55 — La vision de Patmos","Puis, demain soir, nous aborderons l’église d’Ephèse pour commencer, et nous poursuivrons pendant sept soirées : Ephèse, l’âge de l’église d’Ephèse ; puis de Smyrne ; puis de Pergame ; puis de Thyatire ; puis de Sardes ; puis de Philadelphie ; et enfin de Laodicée, le dimanche prochain."]],[["sermons/1963/63-0317E.html?q=sceau#s89","63-0317E § 70 — La brèche entre les sept âges de l’église et les sept sceaux","Un sceau signifie... Maintenant, ça ce sont des termes que j’ai tirés du dictionnaire. Un sceau signifie une « oeuvre terminée ». Et, quand le Septième Sceau est brisé, le mystère de Dieu, qui est scellé dans ces Sceaux mystérieux, est mené à terme. Jusqu’au jour où ce Sceau sera brisé, et alors, ce qu’il y a là, à l’intérieur, est révélé."],["sermons/1963/63-0319.html?q=sceau#s239","63-0319 § 227 — Le deuxième sceau","Maintenant prenons le Deuxième Sceau, au moment où l’Agneau immolé et ressuscité L’a ouvert, et que le deuxième Etre vivant, semblable à un veau, a dit : « Viens voir quel est le mystère du Sceau. » Maintenant nous saisissons cela. C’est l’Agneau, souvenez-vous, qui doit ouvrir chaque Sceau. Et le deuxième Etre vivant..."],["sermons/1962/62-1014M.html?q=sceau#s67","62-1014M § 45 — La stature d’un homme parfait","Eh bien, après que nous aurons terminé avec les Sept Sceaux, alors, au moment où les Sept Sceaux se font entendre, ou sont brisés... Evidemment, nous savons ce qu’est un Sceau ; c’est pour délier un ministère, briser Sept Sceaux. Et nous verrons bien cela sur le graphique. Cela délie un message, quelque chose de scellé."],["sermons/1963/63-0318.html?q=sceau#s196","63-0318 § 165 — Le premier sceau","Maintenant, Il vient réclamer les Siens. Alors, Il prend le Livre, Il se tient là devant Jean, Il le tire, Il brise le Sceau, Il tire le Sceau. Il ouvre le Sceau ! Et, quand Il ouvre le Sceau, un coup de Tonnerre retentit d’un bout à l’autre de l’endroit. Et, quand le coup de Tonnerre a retenti, sans doute que Jean a dû sursauter, quand le Tonnerre a grondé."],["sermons/1965/65-0725M.html?q=sceau#s544","65-0725M § 248 — Les oints du temps de la fin","C’est exact. Pas de trinité! Non non. C’est une fausseté. Les Sept Sceaux, en ouvrant ces mystères qui «devaient s’accomplir», se dévoilent. Un Sceau ouvert expose, dévoile, montre clairement les Vérités cachées, que les Sceaux avaient cachées pendant toutes ces années, à travers toutes ces églises et ces dénominations."],["sermons/1963/63-0324E.html?q=sceau#s478","63-0324E § 389 — Le septième sceau","Bon, maintenant, est-ce que vous remarquez, à l’ouverture de ce Septième Sceau, il y a aussi un triple mystère ? J’en ai... j’en parlerai, et j’en ai parlé, il s’agit du mystère des Sept Tonnerres. Les Sept Tonnerres dans le Ciel vont dévoiler ce mystère. Ça se passera juste à la Venue de Christ, parce que Christ a dit que personne ne savait quand Il reviendrait."],["sermons/1963/63-1110M.html?q=sceau#s174","63-1110M § 141 — Les âmes qui sont maintenant en prison","Les mystères étaient dans les 7 Sceaux. Quand ces 7 Sceaux furent ouverts, la Bible entière s’ouvrit. Les 7 Sceaux étaient scellés de 7 mystères. Et dans ces 7 Sceaux était contenu le mystère entier de Cela. Et c’était le Livre de la Rédemption : le Nouveau Testament. Pas l’Ancien."],["sermons/1961/61-0618.html?q=sceau#s212","61-0618 § 195 — Apocalypse chapitre 5, 2","Maintenant, voici le Livre. C'est écrit au-dedans. Maintenant, juste au moment de la première révélation, Il ouvre alors ce sceau. Alors, faites attention et voyez ce qu'était ce premier sceau, quand nous arriverons aux sceaux. Quand c'est le moment pour le second sceau, Il brise le sceau suivant. Et savez-vous où nous en sommes? Nous sommes presque au septième sceau, en ce moment même et quand le septième..."],["sermons/1963/63-0728.html?q=sceau#s228","63-0728 § 205 — Christ est le mystère de Dieu révèle","Maintenant, la Venue du Seigneur est un mystère. Nous ne savons pas quand Il viendra, comment Il viendra, mais nous savons qu’Il vient. Voyez? Ainsi en était-il de tous les mystères de Dieu, qui attendaient ce dernier jour. Après que cela a déjà été accompli, alors Il révèle et montre ce qu’Il avait fait. Oh! la la! Il n’a jamais livré complètement Son mystère."],["sermons/1955/55-0312.html?q=sceau#s36","55-0312 § 14 — La marque de Christ","Bon, nous lisons maintenant là dans le livre des Ephésiens ce qu’est le Sceau de Dieu. Nous avons vu ce qu’est le sceau du diable. Maintenant, dans Hébreux 10... Nous verrons d’abord le Sceau de Dieu : «Car, si nous péchons volontairement après avoir reçu la connaissance de la vérité, il ne reste plus de sacrifice pour les péchés.»"],["sermons/1963/63-0630M.html?q=sceau#s266","63-0630M § 125 — Le troisième exode","Maintenant, tous les mystères de la justification, de la sanctification et du baptême du Saint-Esprit ont été déjà expliqués. Maintenant, il prend les points restés en suspens sur ce qui est tenu secret dans les Sept Sceaux; pas les sept églises, les Sept Sceaux ont révélé les Mystères. Et alors Il a ouvert cette chose par le sommet et on a vu là-dedans une pierre blanche, sur laquelle rien n’avait jamais été écrit, c’est un mystère."],["sermons/1963/63-0323.html?q=sceau#s131","63-0323 § 126 — Le sixième sceau","En comparant les Ecritures en rapport avec cet important événement, nous verrons ce grand secret ou mystère, qu’il y avait sous le Sixième Sceau du Livre de la Rédemption. Maintenant, souvenez-vous, ce sont des mystères cachés. Et les six Sceaux, ensemble, forment un très grand Livre, rien que les six rouleaux roulés ensemble, et c’est ce qui dénoue tout le Livre de la Rédemption. C’est ainsi que la terre toute entière a été rachetée."]],[["sermons/1956/56-1125E.html?q=proph%C3%A9tie#s7","56-1125E § 5 — Un prophète qui rougit","Eh bien, Israël se retrouvait dans l’un de ses états de rétrograde. C’est vraiment regrettable, ce qu’Israël avait fait. Or, Israël était un peuple choisi, élu, sélectionné. Dieu avait choisi Israël dans un but précis, afin que le sang d’Israël soit le sang le plus pur, car c’est de cette lignée que viendrait le Messie Lui-même."],["sermons/1963/63-0319.html?q=proph%C3%A9tie#s253","63-0319 § 239 — Le deuxième sceau","Oh ! les gens s’imaginent que la nation entière... Pas du tout. Israël est converti en tant que nation, pas individuellement. « Une nation naîtra en un jour. » C’est Israël. « Tout Israël sera sauvé. » Souvenez-vous bien de cela. C’est ce que Paul a dit : « Tout Israël sera sauvé. » Maintenant, remarquez. Tout Israël. C’est tout à fait juste."],["sermons/1960/60-0724.html?q=proph%C3%A9tie#s91","60-0724 § 20 — La Parole immuable de Dieu","Quel temps ! Vous savez quoi ? Cela va mettre fin à la dispensation des Gentils. L’Evangile ira chez les Juifs. Ils vont évangéliser leur–leur peuple avec cela. Israël est une nation. Nous tous, nous sommes les nations, mais Israël est une nation. Et le Royaume reviendra un jour à Israël."],["sermons/1963/63-0323.html?q=proph%C3%A9tie#s334","63-0323 § 283 — Le sixième sceau","Ici, Dieu est sur le point de délivrer Son deuxième fils, Israël, après la tribulation. Vous voyez, la seconde fois, Israël est... Israël est Son fils ; vous le savez. Israël est le fils de Dieu, alors Il va le délivrer, ici, pendant la période de la tribulation, exactement comme Il l’avait fait là-bas en Egypte."],["sermons/1956/56-0902.html?q=proph%C3%A9tie#s34","56-0902 § 13 — L’Écriture sur la muraille","Dieu avait traité avec les Juifs jusqu’à ce temps-ci, et maintenant, Il se tourne vers les Gentils. Et dans cette grande prophétie, des visions et des songes, de Daniel, de Nebucadnetsar, de Belschatsar, beaucoup de personnages qui sont dans le Livre de Daniel étaient tous placés en ordre afin que nous puissions comprendre aujourd’hui."],["sermons/1965/65-0426.html?q=proph%C3%A9tie#s211","65-0426 § 151 — Dieu confirmant sa Parole","Et écoutez ceci. Considérez où nous nous trouvons du point de vue de la position et de la prophétie ce soir. Eh bien, chacun de nous sait que le monde se trouve dans une condition sodomite. Nous connaissons toutes les prophéties en rapport avec Israël. Israël est dans sa patrie. Si vous voulez savoir où nous sommes en tant que nation, observez Israël, où en est Israël."],["sermons/1961/61-0730E.html?q=proph%C3%A9tie#s54","61-0730E § 44 — Les six buts de la visite de Gabriel à Daniel","Dieu les a aveuglés à dessein pour vous et pour moi. Ils ne peuvent pas voir, parce que Dieu les a aveuglés. Et tout Israël, le vrai Israël, sera sauvé. Qu’a dit l’ange ? Gloire ! « Pour faire cesser les transgressions d’Israël ! Je suis venu t’annoncer qu’il viendra un temps où les transgressions d’Israël cesseront. » Dieu retranchera la branche sauvage, et Il greffera de nouveau la–la vraie branche."],["sermons/1962/62-0908.html?q=proph%C3%A9tie#s113","62-0908 § 99 — L’état présent de mon ministère","Daniel a fidèlement pris position. Vous savez, j’ai trouvé cela dans Daniel 12 ou Daniel 9 je crois. Lorsque vous ... Daniel a fidèlement pris position pour la Parole. Qu’est-ce qui lui est arrivé? Alors qu’il était le bras droit du roi, il a pourtant pris position pour la Parole et fut excommunié et jeté dans une fosse aux lions. Un homme de Dieu qui restait fidèle à la Parole!"],["sermons/1963/63-1129.html?q=proph%C3%A9tie#s96","63-1129 § 92 — Le super signe","Et ce pays appartenait à Israël à condition qu’Israël reste fidèle à Dieu. Mais regardez quel renégat ils avaient là comme pasteur, qui avait tout bonnement laissé s’infiltrer l’idolâtrie et tout le reste. Mais les prophètes se sont dit que cela appartenait à Dieu, appartenait à Israël, que c’était un don fait à Israël, qu’ils devaient s’en emparer. C’est ce qui se passe aujourd’hui."],["sermons/1961/61-0101.html?q=proph%C3%A9tie#s398","61-0101 § 291 — Apocalypse chapitre 4, 2","C’est pour cette raison que dans Daniel 7, il... Qu’a fait Daniel–Daniel? Il a vu le jugement à l’avance, il a vu que les trônes mis en place étaient vides. Vous voyez, ils devaient êtres vides. Tandis que du temps de Jean, après l’enlèvement de l’Eglise, ils étaient occupés par les anciens qui étaient rachetés. Hm."],["sermons/1963/63-0322.html?q=proph%C3%A9tie#s326","63-0322 § 284 — Le cinquième sceau","Remarquez, au temps de Daniel… Maintenant, souvenez-vous, il a été dit à Daniel que le Messie viendrait, le Prince, ou plutôt le Messie, et qu’Il prophétiserait. Il restait encore soixante-dix semaines pour Israël. Et, au milieu des soixante-dix semaines, le Messie serait retranché, et le sacrifice quotidien serait supprimé. N’est-ce pas vrai ? Mais il restait encore trois semaines et demie qui ont été fixées. C’est dans cet intervalle-là qu’Il choisit Son Epouse des nations."],["sermons/1961/61-0429E.html?q=proph%C3%A9tie#s121","61-0429E § 54 — Un son confus","Elie s’est avancé là et a dit : « Ô Dieu d’Abraham, d’Isaac et d’Israël. » Remarquez, il ne l’a point appelé par son nom de supplanteur, Jacob. Il l’a appelé par son nom de prince, Israël. « Dieu d’Abraham, d’Isaac et d’Israël, que l’on sache aujourd’hui que Tu es Dieu et que je suis Ton prophète. »"]],[["sermons/1963/63-0320.html?q=enl%C3%A8vement#s66","63-0320 § 64 — Le troisième sceau","Mais l’Enlèvement sera un secret. Alors, si Sa Venue était tellement secrète, à combien plus forte raison l’Enlèvement sera ignoré ! Voyez ? Les gens veulent… Tout à coup, ils vont dire : « Eh bien, je pensais qu’on était censé avoir un Enlèvement. Et voilà tous ces jugements sur la terre ! »"],["sermons/1960/60-0303.html?q=enl%C3%A8vement#s67","60-0303 § 53 — La pluie de la première et de l’arrière-saison","Une chose étrange, notre Seigneur, lorsqu’Il était ici sur terre, Il a plus enseigné sur Sa Seconde Venue qu’Il le fit alors sur Son départ. Lisez les Ecritures, découvrez combien Il a parlé de Sa Seconde Venue. Plus de 80 % de ce qu’Il a dit était sur Sa Seconde Venue. Non pas ce qui se déroulait alors, Son sacrifice et le départ, mais la Seconde Venue. Il a donné des avertissements aux gens. Il n’a jamais eu peur de leur donner des avertissements. Voyons certaines choses qu’Il a faites."],["sermons/1958/58-0108.html?q=enl%C3%A8vement#s96","58-0108 § 94 — L’Écriture sur la muraille","Mais si c’est si proche (et tout enseignant sait que l’Eglise va dans l’Enlèvement avant que la tribulation ne s’installe), ainsi, si c’est si proche que cela pourrait arriver avant le matin, qu’en est-il de l’Enlèvement? C’est plus proche que cela! Oh! béni soit le Nom du Seigneur! La Venue du Seigneur est proche. L’écriture est écrite, et c’est écrit dans la Bible, et nous vivons pour voir cela."],["sermons/1958/58-1012.html?q=enl%C3%A8vement#s187","58-1012 § 150 — Le départ secret et soudain de l’église","Acceptez-vous de suivre ce chemin-là, de vous préparer pour la Venue du Seigneur? Si vous avez... Si vous l’acceptez, vous serez dans l’attente de Sa Venue. Vous vous réjouirez à Sa Venue. Ça ne sera pas une chose terrifiante. Ça sera le moment le plus heureux auquel vous puissiez penser, la Venue du Seigneur. «Tous ceux qui aiment Son apparition»."],["sermons/1965/65-1204.html?q=enl%C3%A8vement#s40","65-1204 § 30 — L’enlèvement","Bon, aujourd’hui, il se peut qu’en parlant sur ce sujet… Eh bien, certains d’entre vous peuvent être d’une autre opinion sur les voies que je prends; mais combien ici croient que la Bible enseigne qu’il y aura un enlèvement de l’Eglise? (Oui, monsieur. C’est vrai! C’est vrai.) Un enlèvement de l’Eglise. Que vous soyez Méthodiste, Baptiste, Presbytérien, ou qui que vous soyez, Pentecôtiste, il y aura un enlèvement."],["sermons/1957/57-0725.html?q=enl%C3%A8vement#s49","57-0725 § 14 — Écoutez-le","Ceci est plutôt un passage des Ecritures inhabituel. Et ce soir, je désire… Evidemment, nous connaissons le véritable sens, la plupart parmi vous les prédicateurs, vous vous référez à ce passage des Ecritures, c’est en rapport avec la Seconde Venue, l’ordre de la Seconde Venue de Christ, c’est vrai. C’est certainement vrai."],["sermons/1956/56-1004.html?q=enl%C3%A8vement#s33","56-1004 § 12 — Les témoins","Dieu ne voulant pas–ne voulant pas qu’aucun périsse, mais Il prenait certainement soin de Ses témoins qui avaient entendu Sa Parole, qui avaient cru Sa Parole, et qui ont agi avec crainte et ont préparé une voie. C’est un beau type de gens d’aujourd’hui qui témoignent de la venue du Seigneur et de l’Enlèvement de l’Eglise."],["sermons/1961/61-0516A.html?q=enl%C3%A8vement#s108","61-0516A § 37 — Jésus-Christ est le même hier, aujourd’hui et éternellement","C’est ce qui se passe aujourd’hui, frère. Le Message… Nous n’avons pas le temps pour quinze ans d’instruction. Le Message est urgent. Le monde est à la fin. Le temps est proche. Ces choses mêmes que vous verrez dans cette réunion prouvent que la prochaine action, c’est la Venue du Seigneur, l’Enlèvement de l’Eglise. C’est scripturaire."],["sermons/1957/57-0417.html?q=enl%C3%A8vement#s23","57-0417 § 19 — La seconde venue du Seigneur","Dans l’Ancien Testament, il y a plus de passages des Ecritures dans l’Ancien Testament en rapport avec la Seconde Venue du Christ qu’il n’y en a en rapport avec la Première Venue de Christ. Maintenant que l’expiation a été faite, tout ce qui concerne la race humaine dépend absolument de la Seconde Venue du Seigneur."],["sermons/1953/53-0614E.html?q=enl%C3%A8vement#s42","53-0614E § 15 — Je vois que tu es prophète","Et, ô Dieu, accorde aujourd’hui que nous puissions tous nous rassembler et voir tous ces neuf dons spirituels agir dans l’Eglise, faire marcher tout le Corps de l’Eglise. Alors, nous aurons l’enlèvement. Ça sera réduit et nous aurons l’enlèvement. Si nous ne pouvons pas avoir la foi pour la guérison divine, comment allons-nous avoir la foi pour l’enlèvement? L’église a encore du chemin à parcourir. Mais je crois que Dieu le fera."],["sermons/1958/58-1130.html?q=enl%C3%A8vement#s110","58-1130 § 93 — Sentinelle, qu’en est-il de la nuit ?","Et comme je les observais monter leurs scènes, je pensai : «Oh! Nous nous tenons, là sur la tour, loin au-dessus de toute chose de ce monde, et nous observons deux des plus grandes choses: la fin du temps et la Venue du Seigneur.» Bientôt, le temps ne sera plus. Il n’y aura plus de temps, et la Venue du Seigneur."],["sermons/1953/53-0326.html?q=enl%C3%A8vement#s44","53-0326 § 43 — Israël a la mer rouge, 1","Mais Dieu est juste en train de libérer l’église partout. Il la met en ordre maintenant pour qu’elle parte dans l’Enlèvement. Il doit lui donner la foi pour l’Enlèvement avant qu’elle puisse participer à l’Enlèvement."]],[["sermons/1961/61-0226.html?q=discernement#s261","61-0226 § 89 — Jéhovah-Jiré","Avant que nous appelions la ligne de prière… Il n’y aura pas de discernement dans la ligne de prière, parce que nous ne le pourrons pas avec trois ou quatre cents personnes qui doivent passer par ici. Je vais prier pour eux, mais on n’aura pas le discernement. Nous aurons donc la ligne de discernement, pour vous qui êtes là-bas dans l’auditoire."],["sermons/1960/60-0417M.html?q=discernement#s290","60-0417M § 220 — Allez dire","Eh bien, il ne s’agit pas du discernement. Dans le discernement, je découvre ces choses. Mais… et ceci n’est pas le discernement ; je suis en train de chercher un nouveau ministère. Est-ce que tous, vous comprenez bien ? Très bien. Maintenant, croyez. Maintenant, prions pendant que nous aurons la tête inclinée."],["sermons/1964/64-0122.html?q=discernement#s88","64-0122 § 82 — Tournez le regard vers Jésus","Oh! nous pouvons discerner le communisme; nous pouvons discerner toutes les autres choses, mais je me demande si nous pouvons discerner la portion de la Parole que Dieu a destinée pour aujourd’hui. Je me demande si nous pouvons voir le signe que Dieu nous a annoncé, qui devaient être ici sur la terre en ce jour. Je me demande si nous pouvons le voir."],["sermons/1965/65-1207.html?q=discernement#s312","65-1207 § 261 — Être conduit","De faux prophètes! La Bible dit: «Dans les derniers jours, il y aura de faux prophètes.» Jésus a dit: «Il s’élèvera de faux prophètes.» Pas de «faux Jésus» maintenant, personne ne supportera cela; mais «de faux christs». «Christs» veut dire «ceux qui sont oints». Faussement oints; ils sont oints, mais ils sont faux au fond, et ils accomplissent de grands signes et des miracles, parlent en langues, dansent dans l’Esprit, prêchent l’Evangile."],["sermons/1959/59-0812.html?q=discernement#s75","59-0812 § 63 — Discerner le corps du Seigneur","«Oh! direz-vous, il s’agit là des communistes.» Il s’agit des soi-disant chrétiens. Observez le verset suivant : «Ayant l’apparence de la piété, mais reniant ce qui en fait la force», n’ayant pas le discernement spirituel. Lorsque vous avez le discernement spirituel et que le Saint-Esprit est sur vous, vous avez le discernement spirituel. Il dit amen à chaque promesse de Dieu. Paul a dit que ce temps viendrait."],["sermons/1960/60-0626.html?q=discernement#s93","60-0626 § 82 — Les réalités infaillibles du Dieu vivant","Maintenant, que nous indique la carte routière? Les gens auraient dû le savoir. Jésus a dit, quand Il était ici sur terre, Il a dit : « Hypocrites, dit-Il, vous savez bien discerner le ciel. Quand il est d’un rouge sombre, vous dites que demain sera orageux; et s’il est clair, vous savez discerner le ciel. Et vous ne pouvez pas discerner les signes des temps. Si vous M’aviez connu, vous auriez connu Mon jour. »"],["sermons/1951/51-0503.html?q=discernement#s112","51-0503 § 27 — Je serai avec toi, comme j’ai été avec Moïse","Maintenant, il y a le discernement ici. Dieu est ici. Oh ! Oui, Il y est. Il est ici. Et je sais que l’Ange du Seigneur est avec moi depuis plus d’une heure. Et je sais que c’est vrai. La puissance du Saint-Esprit est juste sur moi maintenant (C’est vrai), cet Ange du Seigneur, Il est ici et Il peut discerner n’importe quoi. Et c’est vrai."],["sermons/1965/65-0725M.html?q=discernement#s46","65-0725M § 24 — Les oints du temps de la fin","Autrement dit, s’Il voulait l’expliquer pour que nous puissions plus au moins mieux comprendre cela, Il dirait: «Dans les derniers jours, il s’élèvera de faux oints.» Or, cela semble presque impossible, vous voyez, ces termes de «oints»... Mais remarquez les mots qui viennent juste après, «et de faux prophètes», p-r-o-p-h-è-t-e-s, au pluriel."],["sermons/1963/63-1113.html?q=discernement#s168","63-1113 § 152 — Le signe de ce temps","« Oh, tu devrais voir cela! Il n’y a rien de pareil. Ces gens ont un réveil là-bas. Tu... Ça touche tout le pays. Oh! ils ont un merveilleux réveil. Et leur Dieu a oint leur roi, et il a un don de discernement. Et tu n’as jamais rien vu de semblable. Rien ne peut dépasser une telle sagesse. Il peut tout révéler. C’est–c’est au-delà de la sagesse humaine. C’est un discernement qui vient de Dieu. » Et eux tous, eh bien, ils ont entendu."],["sermons/1961/61-1231M.html?q=discernement#s161","61-1231M § 119 — Vous devez naître de nouveau","Et si cette Parole qui vient du prophète est la Parole de Dieu, alors il est un vrai prophète, parce que la Parole vient aux prophètes, aux vrais prophètes. Nous avons toujours eu de faux prophètes. Vrai prophète, vraie Parole. Faux prophète, fausse parole. Ce sont nos credo, nos dénominations, joignez-vous à ceci, dites ceci. Croyez ceci, faites ceci..."],["sermons/1961/61-0730M.html?q=discernement#s185","61-0730M § 127 — Les instructions de Gabriel à Daniel","Je vois tant d’églises, tant d’organisations, tant de gens qui prennent telle direction ; les uns, c’est Je vous salue, Marie, et les autres adorent ceci, cela et autre chose. Il doit y avoir une Vérité quelque part. Il doit y avoir un Dieu quelque part. Il doit y avoir un Message quelque part. Je vois s’élever de faux prophètes qui imitent le discernement, et toutes sortes d’autres choses qui se passent. Il faut qu’il existe quelque part quelque chose de réel qui ait servi de modèle à cette imitation."],["sermons/1955/55-0626E.html?q=discernement#s54","55-0626E § 44 — Je restaurerai","Ô Dieu, s’il Te plaît, accorde à ces gens Ton Esprit. Et puisse Ta miséricorde reposer sur eux. Je les confie entre Tes mains. Ô Dieu, puissent-ils être capables de discerner le vrai et le faux. Puissent-ils vivre heureux et mener une vie victorieuse. Puisses-Tu marcher avec eux, les bénir, et leur accorder ce qu’il y a de meilleur dans le pays. Car je le demande au Nom de Jésus."]],[["sermons/1963/63-1124M.html?q=antichrist#s139","63-1124M § 90 — Que ferai-je de Jésus appelé Christ ?","Bon, cela ne contredit pas les Ecritures. C’est conforme aux Ecritures. «Et ils ont formé une image à la bête. » Unissant les dénominations du monde dans une seule dénomination protestante, formant la marque de la bête, l’image de la bête, selon Apocalypse 13.8 : «Et ils ont formé une image à la bête. »"],["sermons/1954/54-0514.html?q=antichrist#s115","54-0514 § 111 — Le sceau de Dieu","Savez-vous, amis chrétiens, que l’antichrist, est la marque de la bête ? L’antichrist, tout le monde sait que, l’antichrist, là, c’est sa marque, c’est le… de sa puissance. Et, voyez, c’est une bête, c’est une puissance. Il y a une puissance de l’Eglise catholique. Il y a une puissance de l’Eglise méthodiste."],["sermons/1963/63-0321.html?q=antichrist#s162","63-0321 § 158 — Le quatrième sceau","Dans la quatrième étape de son ministère, il s’appelle la bête. D’abord, il s’appelle l’antichrist, vous voyez ; ensuite il s’appelle le faux prophète ; puis il s’appelle la bête. Or nous le voyons ici, qui s’appelle la bête. Maintenant, j’aimerais que vous puissiez remarquer que, c’est après le quatrième cheval."],["sermons/1963/63-0630E.html?q=antichrist#s87","63-0630E § 63 — Votre vie est-elle digne de l’Évangile ?","Vous voyez, vous n’avez que deux choses: l’une c’est accepter Cela et recevoir le Sceau de Dieu; l’autre c’est rejeter Cela et prendre la marque de la bête. Rejeter le Sceau de Dieu, c’est recevoir la marque de la bête. Est-ce que tout le monde comprend? Rejeter le Sceau de Dieu, c’est recevoir la marque de la bête, car la Bible dit que tous ceux qui ne furent pas scellés du Sceau de Dieu reçurent la marque de la bête."],["sermons/1963/63-0628M.html?q=antichrist#s207","63-0628M § 180 — Ô Seigneur, encore une fois","C’est comme cela que cela devra se passer, et c’est ce que nous avons exactement là, maintenant. Et nous y sommes, les organisations avec la marque de la bête sur nous, très exactement comme la première bête, à son image, une fédération des églises se joignant au pouvoir. Et ils ont fait une image à la bête, afin qu’il puisse à la fois parler et faire la même chose que la première bête a faite avant elle. Juste dans nos griffes... Oh, les enfants."],["sermons/1963/63-0323.html?q=antichrist#s61","63-0323 § 62 — Le sixième sceau","Ensuite, nous avons vu venir un autre âge, et l’ennemi a envoyé l’antichrist sous le nom de la religion, sous le Nom de Christ, sous le nom de l’église. Oui, oui. Il est même sorti sous le nom de l’église. Il disait que « c’était la vraie église ». Voyez ? L’antichrist, ce n’est pas la Russie. L’antichrist, ce n’est pas ça."],["sermons/1958/58-0927.html?q=antichrist#s44","58-0927 § 38 — Pourquoi nous ne sommes pas une dénomination ?","L’écarlate, dans la Bible, représente la «royauté». La couleur écarlate veut dire « rouge ». Et une bête représente une puissance. Avez-vous remarqué la bête qui sortait de la mer? C’était dans Apocalypse 13. Et quand vous voyez la bête qui sort de la mer, cela veut dire que cette puissance a surgi parmi les gens."],["sermons/1963/63-0318.html?q=antichrist#s419","63-0318 § 361 — Le premier sceau","Maintenant, remarquez, au temps de la fin–à la fin des âges de l’église, eh bien, il est appelé... lui et ses enfants sont appelés l’antichrist, parce que tout ce qui est contre Christ est antichrist. Et tout ce qui est contre la Parole est contre Christ, parce que Christ est la Parole. Eh bien, il est antichrist."],["sermons/1955/55-0608.html?q=antichrist#s163","55-0608 § 40 — Abraham","Mais en Orient, voici comment ils font une alliance : ils tuent une bête. Et ils se tiennent au milieu de cette bête, entre les morceaux du corps mort, et ils concluent leur alliance, peu importe ce qu’ils font, et ils signent cela de leur nom. Ils déchirent cela en deux, l’un en reçoit une partie, et l’autre garde l’autre moitié. Et alors, ils font un serment sur le corps de cette bête morte. Si l’un d’eux brise cette alliance, qu’il soit comme cette bête morte."],["sermons/1961/61-0402.html?q=antichrist#s244","61-0402 § 198 — Le véritable sceau de Pâques","Et les fils de Satan seront scellés en ces derniers jours. Il y a maintenant un temps, dont la Bible parle, où tous ceux qui n’avaient pas le Sceau de Dieu attraperaient la marque de la bête. Et nous savons que la marque de la bête, c’est l’incrédulité. La première fois... «Où dites-vous que la marque de la bête a commencé?» Dans le jardin d’Eden. La marque de la bête et le Sceau de Dieu ont eu lieu dans le jardin d’Eden. Exactement. Cela s’est passé à Pâques, car la mort d’Abel a suscité Seth. C’est juste."],["sermons/1961/61-0423.html?q=antichrist#s89","61-0423 § 35 — Abraham et sa postérité après lui","Mais du temps d’Abraham, savez-vous comment on concluait une alliance jadis en Orient ? Ils tuaient une bête et ils se tenaient au milieu des morceaux de la bête morte ; ils la rédigeaient sur un parchemin ou sur la peau d’une brebis, tout ce qu’il y avait pour y coucher cette écriture hébraïque, l’alliance, tout ce qu’il y avait. Et ensuite, ils… Au-dessus du corps mort de cette bête, ils juraient que s’ils brisaient cette alliance, qu’ils deviennent comme cette bête morte."],["sermons/1963/63-0319.html?q=antichrist#s202","63-0319 § 190 — Le deuxième sceau","Bon, bon, d’abord… il est donc devenu un antichrist. Or, il ne pouvait pas être un antichrist en étant seulement un esprit. Il est donc devenu un antichrist, et cet esprit s’est emparé d’un homme qui enseignait les mêmes choses que ce que faisait l’esprit antichrist, et ensuite de l’esprit antichrist il est devenu un « faux prophète ». Maintenant, que dire d’un homme qui est dans une organisation ? Faites comme vous voudrez. Je ne sais pas ce que vous en pensez. Mais, c’est très bien."]],[["sermons/1962/62-1104E.html?q=communion#s38","62-1104E § 17 — L’ordination d’un ministre","Maintenant, il se fait peut-être un peu tard, on s’approche de vingt et une heures trente. Ainsi, maintenant nous allons tenir le service de communion. Bien, nous appelons cela “communion” mais ce n’est pas la communion. Communion veut dire parler, communier. Communier, c’est lorsque nous restons tranquilles et que nous parlons au Seigneur, c’est communiquer."],["sermons/1958/58-0515.html?q=communion#s191","58-0515 § 70 — Jésus-Christ est le même hier, aujourd’hui et éternellement","Vous y êtes, en parfaite unité de l’Esprit, parfaite unité, avec des mains posées sur vous, parfaite unité avec le Saint-Esprit, parfaite unité avec la puissance de Dieu, parfaite unité avec les Ecritures, cela doit être donc terminé. Inclinons la tête maintenant, offrons tous la prière à Dieu."],["sermons/1955/55-0122.html?q=communion#s22","55-0122 § 10 — Moïse, le grand serviteur","Moïse était là, sans communion, et rien n’est mentionné comme quelque chose que Dieu aurait fait pour lui pendant ces quarante ans, de surnaturel ou de n’importe quelle manière. Il n’avait pas de communion. Et dès que l’église perd la communion avec Dieu, les miracles s’arrêtent, les signes et les prodiges s’arrêtent, les réveils s’éteignent; et Dieu se retire carrément lorsque vous perdez la communion."],["sermons/1960/60-0630.html?q=communion#s30","60-0630 § 16 — L’approche à laquelle Dieu a pourvu pour communier","Et lorsque la communion a été brisée entre Dieu et l’homme, il a dû y avoir une sorte d’accord, des sortes de dispositions pour rétablir de nouveau cette communion qui a été brisée. Et Dieu a trouvé le plan ; et c’était au travers du sang d’une victime innocente, que Dieu a de nouveau ramené l’homme à la communion avec Lui."],["sermons/1954/54-0103E.html?q=communion#s304","54-0103E § 212 — Questions et réponses","Et maintenant Père, nous nous rendons compte que la communion fut premièrement servie en Egypte. Et ces gens qui ont pris la communion, l’agneau et le pain quand ils sortaient, ils ont voyagé pendant quarante ans dans le désert. Et il n’y avait pas un seul faible parmi eux quand ils sont sortis du désert. Ils avaient pris la communion."],["sermons/1955/55-0501A.html?q=communion#s123","55-0501A § 58 — La communion","Lorsque vous êtes en dehors de la communion, vos prières ne peuvent pas être exaucées. Tout est noir autour de vous lorsque vous êtes en dehors de la communion. Revenez donc à la Parole. La Parole tranche, Elle vous sépare : « Eh bien, vous ne devez pas faire ceci, vous ne deviez pas faire cela. C’est un péché. Vous n’avez plus de communion. Vous êtes sorti de la communion. » Voilà les eaux de séparation, elles vous disent ce que vous devez faire."],["sermons/1958/58-0112A.html?q=communion#s54","58-0112A § 30 — Pour accomplir ses prodiges","Et ceux qui marchent dans la Lumière sont mutuellement dans la communion, et le Sang de Jésus-Christ, le Fils de Dieu, nous purifie de tout péché. En marchant dans la Lumière, vous avez communion avec les baptistes, vous avez communion avec les méthodistes, vous avez communion avec les pentecôtistes. Vous avez communion avec les enfants de Dieu de chaque dénomination, si nous marchons dans la Lumière. Ne vous en faites pas, la Lumière vous conduira."],["sermons/1959/59-1115.html?q=communion#s177","59-1115 § 55 — Mon nouveau ministère","Frère George Wright a, pendant des années, préparé le vin de communion (et je termine), il a préparé le vin de communion pour l’église. Frère Roy Roberson là derrière m’avait téléphoné, disant : « Frère Branham, allons prendre le vin de communion chez frère Wright. » Il est assis ici, sa famille et lui."],["sermons/1960/60-0611B.html?q=communion#s48","60-0611B § 13 — La communion","Et maintenant, avant qu’il y ait communion, il doit y avoir un accord de base (Voyez ?), un accord de base. Et c’est vrai au possible. Et Dieu, avant que nous puissions avoir communion avec Lui, d’abord cela, tout ce qui nous fait désirer la communion, c’est quelque chose en nous qui la réclame."],["sermons/1962/62-0204.html?q=communion#s79","62-0204 § 61 — La communion","«La communion» c’est «parler» et la chose à laquelle vous parlez vous répond. Le mot même «communier» signifie «parler à ou être en relation avec quelque chose qui vous répond.» Et quand Dieu vous répond: c’est ça la communion. Mais pourtant nous, nous appelons communion, le pain et le vin."],["sermons/1961/61-0214.html?q=communion#s109","61-0214 § 53 — La base de la communion","Oui, la communion, la communion sous le Sang, l’unique remède de Dieu… Les dénominations nous sépareront; l’instruction nous séparera ; la science nous séparera. Mais le Sang de Jésus-Christ nous purifiera du péché. Nous sommes mutuellement en communion pendant que nous marchons dans la Lumière comme Il est Lui-même dans la Lumière, la Lumière de la Gloire de la Shekinah. Amen !"],["sermons/1963/63-0322.html?q=communion#s117","63-0322 § 107 — Le cinquième sceau","Maintenant, suivez attentivement. Quand l’antichrist a fait sa première apparition, sous quelle forme est-il apparu ? Le cheval blanc. Vous voyez, mais le plus innocent possible, juste une doctrine dans l’église. Ils voulaient une communion. Votre communion, c’est avec Christ. Mais eux, ils voulaient une communion. Ils ne pouvaient simplement pas supporter cela, ils voulaient..."]],[["sermons/1960/60-0724.html?q=mariage#s171","60-0724 § 40 — La Parole immuable de Dieu","Voyez-vous vers quel genre de foyer vient un Ange ? Un foyer qui observe les commandements de Dieu, un foyer des gens qui marchent correctement devant Dieu. Si vous voulez avoir l’honneur d’être visités par un Ange dans votre foyer, ayez un foyer prêt pour recevoir Sa visite, préparé et apprêté sous le Sang de l’Agneau. C’est à de telles maisons que les Anges du Seigneur viennent."],["sermons/1965/65-1125.html?q=mariage#s233","65-1125 § 213 — L’union invisible de l’épouse de Christ","Maintenant, remarquez : vous n’êtes pas seulement cela, mais vous allez à un mariage au ciel et vous portez la bague de mariage de la grâce prédestinée et imméritée, une bague de mariage de grâce, imméritée de votre part. Dieu l’a fait Lui-même. Il vous connaissait avant la fondation du monde, alors c’est là qu’Il vous a passé la bague de mariage, qu’Il a inscrit votre nom dans le Livre. Oh, quel Thanksgiving! Alléluia! Gloire à Dieu!"],["sermons/1965/65-0221M.html?q=mariage#s261","65-0221M § 189 — Le mariage et le divorce","Maintenant, quant au Mariage et au Divorce… Vous voyez, il faut que cela soit révélé. Tant que ce n’est pas révélé, vous ne savez pas ce qu’il en est. Seulement Il a promis qu’en ces derniers jours, qu’en cet âge, tous les mystères cachés de la Bible seraient révélés. Combien le savent? Apocalypse, chapitre 10! Jésus l’a promis, que tous ces mystères cachés, au sujet–au sujet du Mariage et du Divorce, que tous ces autres mystères cachés qu’il y a eus, seraient révélés au temps de la fin."],["sermons/1964/64-0823E.html?q=mariage#s205","64-0823E § 143 — Questions et réponses n°2","J’essaierai de les parcourir rapidement. Maintenant dans Genèse chapitre 6, verset 12, Dieu dit que toute chair avait corrompu... Oui, c’était le mariage, le divorce et toutes ces autres choses. La Bible dit: «Ce qui arriva du temps de Noé, où ils se mariaient et étaient donnés en mariage» comme cela et ainsi de suite. C’est l’un des signes de la fin des temps, seulement l’un des signes."],["sermons/1954/54-1206.html?q=mariage#s110","54-1206 § 30 — L’expectative","Elle a dit : « C’est vrai. » Elle a dit : « Mais je ne peux pas le lui dire, a-t-elle dit, j’ai trois enfants, Frère Branham. Cela brisera mon foyer. » Elle a dit : « Mon mari est un diacre là-bas dans une église, a-t-elle dit, si jamais je lui disais cela, a-t-elle dit, cela briserait notre foyer. »"],["sermons/1954/54-0902.html?q=mariage#s71","54-0902 § 28 — Témoignage sur l’Afrique du sud","J’ai dit : « Vous n’avez jamais péché contre Dieu ; c’est contre votre voeu de mariage envers votre mari que vous avez péché. Si vous étiez célibataire, ce serait différent, mais vous étiez une femme mariée, et c’est contre votre voeu de mariage que vous avez péché. »"],["sermons/1960/60-0716.html?q=mariage#s138","60-0716 § 43 — Des ce moment","Puis comme un jeune couple qui se marie. Oh ! Ils s’aiment autant que possible. La première chose, vous savez, je pourrais aller auprès de cette femme qui a quitté son foyer et dire : « Madame, pourquoi avez-vous quitté votre foyer ? Vous aviez un bon mari. »"],["sermons/1965/65-0911.html?q=mariage#s186","65-0911 § 109 — La puissance de Dieu pour la transformation","Cela vous coûtera votre foyer, vous coûtera votre emploi, cela vous coûtera tout ce que vous avez, et en plus de cela, votre âme. Cela brisera votre foyer, et cela fera peut-être qu’un autre homme élève vos enfants ou qu’une autre femme élève vos enfants."],["sermons/1960/60-0331.html?q=mariage#s43","60-0331 § 9 — Dès ce moment","Il a dit : « Un jour, je suis rentré à la maison, j’avais un bon foyer, mais, a-t-il dit, j’ai trouvé une lettre de divorce posée sur la table. » Il a dit : « Je l’aimais tellement que je ne pouvais pas l’oublier, et dès ce moment... » Vous y êtes. « Dès ce moment », quelque chose marque cela."],["sermons/1961/61-0723E.html?q=mariage#s262","61-0723E § 214 — Dieu mal compris","Beaucoup parmi eux pensaient qu’Il était né hors des liens sacrés du mariage, qu’Il était issu d’une famille mal réputée, où on avait de mauvais désirs, etc., qu’Il était un bâtard. Nous venons d’avoir une question là-dessus ; de tels enfants ne pouvaient même pas... Eh bien, les gens disaient : « Oh ! nous savons que Tu es né en dehors des liens sacrés du mariage, Tu as un démon. Et Tu essaies de nous enseigner ? Nous sommes des rabbins ! »"],["sermons/1962/62-0318E.html?q=mariage#s158","62-0318E § 153 — La Parole parlée est la semence originelle","Ensuite, elle s’est prostituée, comme la femme d’Adam l’avait fait en Éden, et comme la femme de Jéhovah l’avait fait à l’époque de Samuel, en se donnant un roi. Elle avait divorcé d’avec Dieu, son fiancé, et d’avec Sa Parole, et d’avec Son prophète, Son porte-Parole; et elle s’était prostituée, comme les autres nations. Et Dieu a divorcé d’avec elle. Il a fait la même chose aujourd’hui. C’est le même acte."],["sermons/1956/56-0923.html?q=mariage#s25","56-0923 § 25 — L’adoption spirituelle","Notre précieux Père céleste, comme jadis, combien beaucoup de pères et de mères ont élevé leurs enfants pour les placer dans Tes mains. Et Toi, Tu as dit: «Laissez venir à Moi les petits enfants, et ne les en empêchez pas, car le Royaume des Cieux est pour ceux qui leur ressemblent.» Et ce petit enfant qui était sans foyer, un foyer lui a été donné, et Toi, tu as placé dans leur coeur l’amour pour cet enfant."]],[["sermons/1961/61-1231M.html?q=habillement#s134","61-1231M § 103 — Vous devez naître de nouveau","Je vais m’adresser aux femmes pendant une minute. Quand une femme sait que la Parole de Dieu condamne les cheveux courts, le port des shorts, le port des pantalons et des vêtements immoraux, elle est séduite si elle n’a pas assez de décence pour laisser pousser ses cheveux et pour porter des vêtements qui conviennent à une chrétienne."],["sermons/1960/60-0610.html?q=habillement#s120","60-0610 § 65 — Le roi rejeté","Je crois que toute femme devrait être propre ; elle devrait être en beauté ; tout homme aussi, il devrait être beau et propre, mais être décent. Vous savez, si vous portez ces sales habits que portent les gens, ces sales shorts et… Il y a quelque temps, une femme m’a dit, elle a dit : « Frère Branham, je ne porte pas ces shorts. » Elle a dit : «Je porte des pantalons. »"],["sermons/1965/65-1031M.html?q=habillement#s264","65-1031M § 220 — La puissance de transformation","Regardez aujourd’hui. Regardez l’homme, essayant de porter les sous-vêtements de sa femme; et elle essaye de porter ses vêtements. Et il essaie de laisser pousser ses cheveux comme les siens et elle coupe les siens comme lui. Oh! la la! Les hommes essayant d’être des femmes, les femmes essayant d’être des hommes : c’est une perversion!"],["sermons/1965/65-1125.html?q=habillement#s116","65-1125 § 105 — L’union invisible de l’épouse de Christ","Vous voyez? C’est vrai. De nature, ils sont comme lui et elle. Oui, monsieur. Ses filles à elle ont le visage fardé, des cheveux courts, elles portent des vêtements d’homme, des pantalons. La Bible dit qu’elle ne devrait pas le faire. Elle se coupe les cheveux, c’est une honte pour elle. Vous dites : «Taisez-vous avec ça.»–C’est ce que dit la Parole. Je fais seulement ressortir la nature. C’est ce qu’elle fait."],["sermons/1964/64-0830E.html?q=habillement#s213","64-0830E § 118 — Questions et réponses n°4","Et vous, femmes, habillez-vous comme des femmes. Et vous, hommes, habillez-vous comme des hommes; n’essayez pas d’être efféminés, en portant des vêtements de femmes. Et vous, femmes, n’essayez pas d’être masculines en portant des vêtements d’hommes, parce que Dieu ne veut pas que vous fassiez cela; la Bible condamne cela."],["sermons/1958/58-0126.html?q=habillement#s30","58-0126 § 19 — Écoutez-le","Et en été, les femmes sortent vêtues de tout petits shorts qu’elles ne devraient même pas porter pour se présenter devant leurs maris, et elles tondent le gazon et se promènent dans la rue, vêtues de ces petits vêtements. Et vous voulez me dire que le Saint-Esprit est là-dedans ? « Vous les reconnaîtrez à leurs fruits. »"],["sermons/1956/56-0213.html?q=habillement#s73","56-0213 § 33 — Une vie cachée avec Christ","Mais cette femme a continué son bonhomme de chemin, et toutes les dames dans cette église portaient ces petits vêtements scandaleux, des shorts, et sortaient pour tondre la cour. Et elle a commencé à agir de même. Son père et les autres l’ont réprimandée, mais cela ne lui a servi à rien, elle était pareille aux autres femmes. Et elle a dit: « Mes soeurs le font, pourquoi pas moi? »"],["sermons/1963/63-1113.html?q=habillement#s75","63-1113 § 65 — Le signe de ce temps","Considérez nos femmes. C’était une mauvaise chose pour elles de se couper les cheveux ; la Bible dit que c’est mal. Mais elles le font quand même. C’est… La Bible dit qu’elles ne doivent pas le faire. Et porter ces vêtements qui ressemblent à des vêtements d’hommes, la Bible dit que c’est une abomination devant Dieu."],["sermons/1964/64-0726M.html?q=habillement#s213","64-0726M § 149 — Reconnaître votre jour et son message","Regardez, aujourd’hui. Les pousser à se couper les cheveux, à porter des shorts, des pantalons, à fumer; et elles se disent croyantes. Ne vous rendez-vous pas compte, soeur, ou, femme, je veux dire (Excusez-moi), pas ma soeur; faire une chose pareille, ne vous rendez-vous pas compte que c’est le diable ? Mais quoi..."],["sermons/1960/60-0611B.html?q=habillement#s147","60-0611B § 51 — La communion","Retirez une fille du rock-and-roll, laissez-la entrer dans cette communion, elle se nettoiera très vite à fond. Elle laissera pousser ces cheveux et portera une belle robe décente, elle ôtera les vieux shorts et les pantalons, et elle deviendra différente. On demandera : « Qu’est-il arrivé à cette femme ? »"],["sermons/1962/62-0407.html?q=habillement#s239","62-0407 § 106 — Les signes de sa venue","Il a dit : «Eh bien, les gens vous appellent ainsi. Pourquoi ne leur enseignez-vous pas de grandes choses, comment recevoir les dons de Dieu, au lieu de parler aux femmes de leurs cheveux courts et–et de leur manière de s’habiller, du maquillage et des histoires qu’elles font et des choses comme cela ? »"],["sermons/1965/65-1205.html?q=habillement#s101","65-1205 § 73 — Les choses qui doivent arriver","Il a dit : «Oh! Je le crois.» Il a dit : «Moi aussi, je suis pentecôtiste. Je crois que les femmes ne devraient pas avoir les cheveux courts, qu’elles ne devraient pas porter des pantalons, et toutes ces choses qu’elles font, se maquiller.» Il a dit : «Elles ne devraient pas faire ça, mais, a-t-il dit, vous, Dieu vous a appelé à prier pour les malades.»"]],[["sermons/1963/63-0724.html?q=tentation#s252","63-0724 § 205 — Dieu ne juge pas un homme sans l’avoir d’abord averti (avertissement, puis jugement)","Les gens disent : «Eh bien, je dois me préparer à mourir.» Oh! la la! je me prépare à vivre. Amen. Ce qu’il faut, c’est se préparer à vivre, vivre en Christ, une vie de victoire sur le péché, la mort, l’enfer, j’ai déjà ma victoire. Il est ma victoire, et je suis Sa preuve, et je suis une preuve de Sa victoire. Amen. C’est cela."],["sermons/1963/63-0825M.html?q=tentation#s237","63-0825M § 184 — Comment puis-je vaincre ?","Des vainqueurs, Seigneur, notre ardent désir, c’est d’être des vainqueurs, des vainqueurs. Seigneur Jésus, Tu as vaincu le monde. Maintenant, je Te prie de laisser chaque personne ce matin, rejeter tout péché et les fardeaux qui nous enveloppent si facilement, afin de courir avec persévérance dans la carrière qui nous est ouverte."],["sermons/1958/58-1004.html?q=tentation#s51","58-1004 § 45 — La foi, c’est notre victoire","Alors la foi triomphe de la mort. La foi, c’est la victoire sur la mort. La foi, c’est la victoire sur le péché. La foi, c’est la victoire sur la maladie. La foi, c’est la victoire sur l’inquiétude. La foi, c’est la victoire sur les frustrations. La foi, c’est la victoire sur le monde."],["sermons/1958/58-0329.html?q=tentation#s74","58-0329 § 28 — Le puissant Conquérant","Ainsi, les chrétiens qui sont ici ce soir ont la situation sous contrôle. Nous avons vaincu le péché ; nous avons vaincu la mort ; nous avons vaincu le séjour des morts ; nous avons vaincu la tombe ; nous avons vaincu la maladie, parce que Jésus est pour nous le Puissant Conquérant."],["sermons/1959/59-0329E.html?q=tentation#s130","59-0329E § 119 — Le signe du Messie","Je condamne le diable. Jésus-Christ t’a vaincu; Il a remporté la victoire au Calvaire; Il a triomphé de la mort, du diable, de l’enfer, et de la tombe, et Il est ressuscité le troisième jour, et Il est vivant éternellement. Sors d’ici, Satan; tu es vaincu. Quitte ces gens, et qu’ils soient guéris, au Nom du Seigneur Jésus-Christ."],["sermons/1960/60-0805.html?q=tentation#s303","60-0805 § 102 — L’agneau et la colombe","Satan, tu es vaincu. Les gens vont reconnaître cela d’ici peu, que tu es vaincu. Tu n’as plus de prise sur eux. Jésus-Christ, le Fils de Dieu, est ici, et Il t’a vaincu. Tu es vaincu ; tu as été vaincu il y a deux mille ans. Sors d’eux, au Nom de Jésus-Christ."],["sermons/1961/61-0611.html?q=tentation#s189","61-0611 § 145 — Apocalypse chapitre 5, 1","Vous y êtes, frères, c’est par l’humilité, par la douceur, par le Saint-Esprit que nous avons la victoire, non pas un très puissant et géant intellectuel, mais celui qui peut s’humilier, c’est l’homme qui a la victoire. L’homme qui peut être traité avec mépris et qui reste néanmoins serviteur de Dieu, c’est celui-là le vainqueur."],["sermons/1965/65-0220E.html?q=tentation#s252","65-0220E § 130 — Le lieu d’adoration que Dieu a choisi","Maintenant, Seigneur, ce défi a été relevé: Satan, le grand bluffeur, il n’a aucun droit de retenir un enfant de Dieu. Il est un être vaincu. Jésus-Christ, le seul lieu d’adoration, le seul vrai Nom, l’a vaincu au Calvaire. Et nous faisons valoir maintenant même Son Sang, par lequel Il a vaincu toute maladie, toute affection."],["sermons/1965/65-1205.html?q=tentation#s215","65-1205 § 154 — Les choses qui doivent arriver","Et, nous amenons ces gens devant Dieu. Satan, tu es vaincu! Tu es un être vaincu! Jésus-Christ t’a vaincu au Calvaire! Tu n’as aucun pouvoir! Tu es un imposteur! Nous repoussons ta main ce soir! Au Nom de Jésus-Christ, sortez de ces gens, vous, maladies et affections, et qu’ils soient libérés au Nom de Jésus-Christ, le Fils de Dieu!"],["sermons/1963/63-1112.html?q=tentation#s105","63-1112 § 96 — Monsieur, nous voudrions voir Jésus","Maintenant, considérons et voyons ce qu’Il était. Nous voyons que dès qu’Il a été baptisé, Dieu est venu sur Lui sous la forme d’une colombe, et Il est allé dans le désert pour quarante jours de tentation. Et là, Il a vaincu Satan d’abord par la Parole. Il a vaincu Satan par la Parole."],["sermons/1953/53-0609A.html?q=tentation#s230","53-0609A § 201 — Démonologie, domaine religieux","Alléluia ! Il a revêtu la Parole de Dieu. Il a vaincu Satan, chaque fois, par Elle. Il a vaincu la mort, par la Parole de Dieu. Alléluia ! Il a vaincu la mort. Et quand ils L’ont tué et qu’Il est mort pécheur, avec mes péchés et vos péchés sur Lui, Il est descendu, je peux Le voir frapper à la porte là-bas. Et ces âmes perdues sont venues et ont dit : « Mais, Qui es-Tu ? »"],["sermons/1962/62-0701.html?q=tentation#s220","62-0701 § 127 — Se revêtir de toutes les armes de Dieu","Quelle armée! Comme une armée puissante, le soldat chrétien marche. Amen. La grande victoire. Il est en nous. Pas moi, Il a déjà vaincu cela. Je n’ai pas à faire quelque chose, si ce n’est de croire en Lui et aller de l’avant (Oui, monsieur), car Il est ressuscité. Son Esprit est en nous, le grand Vainqueur. La Présence de la résurrection est en nous."]],[["sermons/1959/59-1120.html?q=minist%C3%A8re#s84","59-1120 § 40 — Un prophète comme Moïse","Maintenant, concernant ces offices et ces positions, parmi les offices, vous écoutez l’apôtre, son ministère. Vous écoutez le prophète, son ministère; les évangélistes, le docteur, le pasteur. Chacun a un ministère distinct. Et leurs ministères viennent de Dieu. Dieu les a établis dans l’Eglise dans ce but."],["sermons/1953/53-0506.html?q=minist%C3%A8re#s174","53-0506 § 40 — Jésus-Christ est le même hier, aujourd’hui et éternellement","On a donc pris une ambulance, on est allé prendre monsieur Hall, révérend Hall de l’église baptiste de Milltown. On l’a amené à Louisville. Docteur Able l’a examiné, il est revenu, et il ne pouvait pas parler à madame Hall. Alors, il a téléphoné le docteur Adair, il a parlé au docteur Adair, et le docteur m’a appelé."],["sermons/1964/64-0621.html?q=minist%C3%A8re#s72","64-0621 § 51 — Le procès","Eh bien, nous voyons que c’est toujours le ministère public qui doit représenter l’Etat. Je pense que c’est ça. Le ministère public… S’il y a un juriste assis ici, j’espère que je m’y prends bien. Le ministère public doit représenter l’Etat. Alors, le ministère public dans cette affaire-ci, c’est le diable, il accuse la Parole de Dieu."],["sermons/1963/63-0317M.html?q=minist%C3%A8re#s229","63-0317M § 211 — Dieu se cache, puis se révèle dans la simplicité","Certes, ils n’étaient pas obligés, mais il était quand même leur pasteur. Il était le pasteur de Jézabel. Elle ne voulait pas… Peut-être qu’elle en avait un d’un autre genre, mais–mais, l’envoyé de Dieu, c’était lui. Voyez-vous ? Il était le pasteur que Dieu avait envoyé pour elle. Elle le haïssait, mais il était malgré tout le pasteur."],["sermons/1960/60-0805.html?q=minist%C3%A8re#s103","60-0805 § 36 — L’agneau et la colombe","Vous avez simplement laissé tomber les barrières. Souvent, (il ne s’agit pas de ces frères-ci,) mais souvent, des prédicateurs pensent plus au bon de repas qu’à l’Evangile. Un évangéliste va à travers… C’est une honte ! Eh bien, l’autre jour, un évangéliste, un évangéliste célèbre s’adressant à moi, a dit : « Vous allez ruiner votre ministère. »"],["sermons/1954/54-0513.html?q=minist%C3%A8re#s259","54-0513 § 205 — La marque de la bête","Et c’est la leçon même d’hier soir: «Il avait dans Sa main sept étoiles», et chaque étoile devait être donnée à chaque âge de l’église comme Lumière (c’est vrai), tout comme il y a un apôtre là, il y a un apôtre là, et un apôtre là, et un apôtre là; «qui étaient sept Esprits (au début de notre leçon) qui se tenaient devant Dieu pour être envoyés aux Sept Âges de l’Eglise.»"],["sermons/1964/64-0412.html?q=minist%C3%A8re#s74","64-0412 § 53 — Un procès","Maintenant, le ministère public représente toujours l’Etat, si je comprends bien les tribunaux. Ainsi, le ministère public dans ce cas-ci représente le monde, et c’est Satan, le ministère public. Il représente le monde parce que le monde lui appartient. Il représente le monde, il est son ministère public."],["sermons/1961/61-0108.html?q=minist%C3%A8re#s479","61-0108 § 296 — Apocalypse chapitre 4, 3","L’un avance avec la perspicacité d’un homme; l’autre avance avec la rapidité d’un aigle; l’autre est un pasteur... L’un est évangéliste pour voler comme l’évangéliste. Vous voyez? L’autre est un pasteur; l’autre est vigoureux; l’autre est perspicace. Vous voyez, c’est gardé de tout côté, Dieu garde cet Evangile du Saint-Esprit! Croyez cela, frère. Très bien."],["sermons/1963/63-0628E.html?q=minist%C3%A8re#s369","63-0628E § 290 — Il y a ici plus que Salomon","Mais quand un évangéliste vient dans une ville, il fait toutes les prières, tous les baptêmes, alors, quand il s’en va, pour les gens, le pasteur est… Eh bien, les gens pensent que leur pasteur ne vaut rien. Votre pasteur est un homme de Dieu. Il vous a conduits en sécurité jusque-là ; il est capable de vous amener plus loin. Il est un homme instruit par Dieu."],["sermons/1961/61-0429M.html?q=minist%C3%A8re#s64","61-0429M § 62 — Un des hommes les plus méchants de la ville","Et pendant qu’elle promenait son regard à travers l’auditoire, elle a vu Simon le pharisien debout là, tenant ses discours devant les dignitaires de la ville. «Voici le docteur, le docteur d’Etat, le docteur en droit Dupont, le pasteur, et voici son associé, et voilà tous les dignitaires de différentes villes», ils se tenaient là, vous savez, pleins de dignité."],["sermons/1958/58-0316E.html?q=minist%C3%A8re#s198","58-0316E § 64 — La porte du coeur","Et peu après, le pasteur a senti sa grosse main se poser sur son épaule. Il a dit : « Pasteur. » Et le pasteur s’est arrêté. Le vieux Gabe avait le regard tourné vers le soleil, et alors, il s’est retourné. Et le pasteur a vu les larmes couler sur ses joues. Et il a dit : « Qu’y a-t-il, Gabe ? »"],["sermons/1957/57-0226.html?q=minist%C3%A8re#s68","57-0226 § 22 — Messieurs, nous voudrions voir Jésus","Un apôtre aujourd’hui, un apôtre moderne n’est rien d’autre qu’un missionnaire. Maintenant, si vous me dites ce que signifie le mot missionnaire, dites-moi alors ce que signifie un apôtre. Apôtre signifie un envoyé et missionnaire signifie un envoyé. C’est la même chose."]],[["sermons/1954/54-0809A.html?q=type#s30","54-0809A § 11 — Je restaurerai","En d’autres termes, si je n’avais jamais vu un être humain, ou si je ne m’étais jamais vu moi-même, et que je voyais mon ombre, j’aurais une idée de ce à quoi je ressemble à partir de mon ombre. Par conséquent, l’Ancien Testament, quand on Le lit, c’est l’ombre du Nouveau. Et toutes ces choses étaient des ombres et des types de ce temps dans lequel nous vivons aujourd’hui."],["sermons/1955/55-0223.html?q=type#s147","55-0223 § 51 — Job, serviteur de Dieu","Alors, Orpa a embrassé sa belle-mère et elle est retournée. Et ainsi Ruth, la Moabite était un beau type de l’Epouse des Gentils. Il se peut que ça blesse, un peu de théologie, mais Naomi était un type de l’Eglise juive, l’Eglise juive orthodoxe, qui a perdu ses biens, et Ruth est un type de la–la femme des nations, ce qui est un type de Christ, qui prend l’Eglise des Gentils."],["sermons/1953/53-0326.html?q=type#s18","53-0326 § 18 — Israël a la mer rouge, 1","Maintenant, ce que nous essayons de faire ce soir, c’est de projeter l’ombre de l’Ancien Testament sur le Nouveau Testament. «Et toutes les choses anciennes disent les Ecritures, étaient un type ou une ombre des choses à venir.» Eh bien, c’est une belle leçon ce soir, l’Exode. Hier soir, nous en avons fini avec les enfants d’Israël."],["sermons/1959/59-1216.html?q=type#s138","59-1216 § 84 — Qu’est-ce que le Saint-Esprit ?","Ils savaient que l’Eglise devait recevoir une puissance qui accomplirait dans l’Eglise les oeuvres mêmes de Christ, parce que comme une ombre, qui devient de plus en plus profonde et donne un reflet plus précis… Prenez une ombre ; plus on est loin de l’ombre, moins l’ombre va donner un bon reflet. Peu après, l’ombre s’approche de plus en plus, au point où l’arbre et l’ombre, c’est une seule et même chose."],["sermons/1956/56-1209A.html?q=type#s62","56-1209A § 26 — Dieu faisant sa promesse","Maintenant, dans le type où on Le voit comme l’Agneau, l’agneau était utilisé bien des fois, ou pratiquement toutes les fois ; et la première fois il a été utilisé comme un–un symbole de Christ. Là dans la Genèse où Dieu a pourvu à un agneau ; un agneau était un symbole qui représentait Christ parce que l’agneau était doux."],["sermons/1965/65-0725M.html?q=type#s142","65-0725M § 62 — Les oints du temps de la fin","La Bible nous dit que l’Ancien Testament était une ombre, un type des choses nouvelles, ou des choses qui devaient venir; ce n’est pas la chose réelle, mais c’est une ombre, un type des choses à venir."],["sermons/1953/53-0325.html?q=type#s11","53-0325 § 11 — Israël en Egypte","Et je le crois simplement ainsi. Et je crois que toute l’Ecriture enseigne que tout l’Ancien Testament était une ombre des choses à venir. Ainsi, si je me dirige vers ce mur, et que mon ombre soit là devant moi, elle montrera quelque chose qui me ressemble lorsque j’arriverai là. Cela montre si je suis un quadrupède, un oiseau, ou n’importe quoi d’autre, l’ombre le montrera."],["sermons/1961/61-1015M.html?q=type#s80","61-1015M § 66 — Questions et réponses","Eh bien, l’Eglise de ce jour est, dans son entièreté, l’antitype de ce type. Nous le savons. Il existe un type et un antitype. Eh bien, lorsqu’Israël était en voyage, de la Palestine–de l’Egypte vers la Palestine, c’était, dans le spirituel, un type de l’Eglise de ce jour en route vers la terre promise. Vous êtes tous d’accord avec cela, n’est-ce pas? Tous les théologiens sont d’accord que c’était un type."],["sermons/1953/53-1115A.html?q=type#s50","53-1115A § 20 — Parle au rocher","Jésus-Christ était en Moïse. Jésus-Christ était en Joseph. Joseph était un type parfait de Christ. Considérez-Le là, quand il était une ombre, c’est ce que Dieu avait fait. Et le seul moyen que j’ai… je connais, c’est le recours à des types, mais comment–comment puis-je prêcher cela n’ayant aucune instruction, si je ne regarde pas en arrière ? Et si je sais à quoi l’ombre ressemblait, j’aurai une certaine idée de ce à quoi ressemble la chose réelle."],["sermons/1963/63-0319.html?q=type#s29","63-0319 § 26 — Le deuxième sceau","Eh bien, c’est donc un mystère, lorsque le–l’Etre vivant a dit à Jean : « Viens seulement voir. » Et il n’a pas vu ce que c’était. Il n’a vu qu’un symbole. Et ce symbole, la raison pour laquelle c’était... Il a dit : « Viens voir », mais il a vu un symbole, il devait présenter cela à l’église sous forme d’un symbole, de manière à ce qu’ils veillent, jusqu’à ce que cela arrive au dernier âge, et alors, le Sceau serait ouvert."],["sermons/1958/58-0110.html?q=type#s13","58-0110 § 5 — Le puissant Conquérant","Eh bien, beaucoup d’enseignants peuvent être en désaccord sur cette idée, ou plutôt sur cet enseignement. Mais moi, je n’ai pas d’instruction, et j’étudie la Bible juste à partir des types. Et les types sont des ombres. Et si nous pouvons voir ce qu’est l’ombre de quelque chose, alors nous aurons une idée générale de la réalité."],["sermons/1964/64-0719M.html?q=type#s144","64-0719M § 90 — La fête des trompettes","Enoch et les autres l’ont érigée, il y a des années, et elle est là comme symbole. Exactement comme le soleil qui se lève et se couche; exactement comme l’arbre qui laisse tomber sa–sa feuille, et elle revient ensuite; comme le poisson, et les bêtes, et tout le reste, c’en est un symbole. La pyramide est là comme symbole."]],[["sermons/1964/64-0304.html?q=r%C3%A9surrection#s13","64-0304 § 13 — Messieurs, nous voudrions voir Jésus","Or, si vous étiez dans Ses pensées au commencement, si vous avez la Vie Eternelle, il n’y a qu’une forme de Vie Éternelle ; la Vie Eternelle n’a pas eu de commencement, et Elle n’a pas de fin. Donc, si vous avez la Vie Eternelle, vous étiez un attribut des pensées de Dieu avant qu’il y ait quoi que ce soit d’autre que Lui."],["sermons/1965/65-0911.html?q=r%C3%A9surrection#s275","65-0911 § 159 — La puissance de Dieu pour la transformation","Maintenant, suivez. Vous dites que vous avez la Vie éternelle. Nous croyons cela, que nous avons la Vie éternelle. Eh bien, Il n’y a qu’une seule forme de Vie éternelle, et c’est Dieu. Dieu est la seule chose qui soit éternelle. Alors, si vous avez la Vie éternelle, cette Vie qui est en vous a toujours existé, et vous étiez dans les reins de Dieu avant même qu’il y ait eu un monde."],["sermons/1959/59-0404.html?q=r%C3%A9surrection#s73","59-0404 § 30 — Quelles sont les oeuvres de Dieu ?","Connaître la Bible, c’est une chose ; mais connaître l’Auteur de la Bible, c’en est une autre. Ce n’est pas par la connaissance de la Bible que vous avez la Vie Eternelle ; mais quand vous Le connaissez Lui, vous avez la Vie Eternelle. C’est Le connaître, Lui. Vous pourriez ne pas connaître une seule Parole de Sa Bible, mais si vous Le connaissez dans Sa puissance de la résurrection, c’est la Vie Eternelle."],["sermons/1957/57-0323.html?q=r%C3%A9surrection#s152","57-0323 § 56 — Dieu dans sa Parole","Frère, connaître votre église, ce n’est pas la Vie Eternelle. Connaître le catéchisme, ce n’est pas la Vie Eternelle. Connaître tous les enseignements de votre église, ce n’est pas la Vie Eternelle. Connaître la Bible, ce n’est pas la Vie Eternelle ; Le connaître Lui, c’est ça la Vie Eternelle. Et le seul moyen par lequel vous pouvez Le connaître, c’est en naissant de nouveau de Son Esprit. Prions maintenant."],["sermons/1957/57-0728.html?q=r%C3%A9surrection#s155","57-0728 § 82 — Avoir soif de la vie","Il a dit: «Je suis la Résurrection et la Vie. Celui qui écoute Mes Paroles a… Celui qui écoute Mes Paroles a la Vie éternelle.» Il a dit: «Je suis la Résurrection et la Vie», c’est comme ça qu’Il l’a dit. «Vivra quand bien même il serait mort. Et quiconque vit et croit en Moi, ne mourra jamais.» Il a dit: «Croyez-vous cela ?»"],["sermons/1957/57-1002.html?q=r%C3%A9surrection#s108","57-1002 § 398 — Questions et réponses sur les hébreux 2","Maintenant, nous avons vu cela. Si un homme peut être pécheur et être puni pour toujours... Il ne peut être puni pour toujours, à moins qu’il ait la Vie éternelle. S’il a la Vie éternelle, il est sauvé. Voyez-vous? Donc, il n’y a qu’un seul type de Vie éternelle, et c’est «Zoe», la Vie de Dieu. Et cet homme ne peut périr."],["sermons/1965/65-1206.html?q=r%C3%A9surrection#s286","65-1206 § 266 — Les événements modernes rendus clairs par la prophétie","Remarquez comment Jésus S’est donc exceptionnellement fait connaître à ces disciples, et nous allons terminer, à ces deux disciples, Caïphe... ou plutôt Cléopas et son ami. Maintenant, nous sommes à la résurrection, le matin après la résurrection, la première résurrection. Quel beau matin, Jésus est ressuscité des morts et Il vit parmi Son peuple. Quelle merveilleuse pensée!"],["sermons/1962/62-0728.html?q=r%C3%A9surrection#s43","62-0728 § 20 — Dieu a pourvu à une voie","Or, la résurrection n’est pas un remplacement. La résurrection, c’est ramener la même chose qui était tombée. Eh bien, si ce morceau de papier tombe par terre, eh bien, si seulement je ramasse cet autre morceau de papier et que je le mette à la place de cet autre, ce n’est pas une résurrection ; c’est le remplacement. Mais la résurrection consiste à relever la même chose qui était tombée. C’est ça la résurrection."],["sermons/1965/65-1031A.html?q=r%C3%A9surrection#s56","65-1031A § 37 — Être conduit","La religion ne nous donne pas la Vie Eternelle. La religion est une couverture, mais elle ne nous donne pas la Vie Eternelle. Et pourtant, lui qui avait reçu l’enseignement de meilleurs maîtres qu’il y avait, il lui manquait cependant quelque chose. Et le jeune homme le savait, parce qu’il a demandé : «Bon Maître, que puis-je faire pour hériter la Vie Eternelle?»"],["sermons/1961/61-0618.html?q=r%C3%A9surrection#s156","61-0618 § 140 — Apocalypse chapitre 5, 2","Voyez-vous? Et vous ne pouvez pas avoir la Vie Eternelle, à moins d'être sauvé. Si vous avez la Vie Eternelle, alors vous ne pouvez pas être brûlé en enfer pour l'éternité. Vous serez puni pour vos péchés commis durant votre vie naturelle, mais vous ne pouvez pas avoir la Vie Eternelle en enfer. Si vous avez la Vie Eternelle, alors vous ne pouvez pas brûler pour toujours, parce qu'il n'y a qu'une forme de Vie Eternelle, et je suis sûr que l'église comprend cela."],["sermons/1964/64-0208.html?q=r%C3%A9surrection#s167","64-0208 § 159 — Le signe","Vous êtes donc candidat à la résurrection, car la puissance de la résurrection est déjà en vous. Le Signe, c’est la puissance de la résurrection, montrant que Jésus est ressuscité d’entre les morts, et que vous êtes ressuscité d’entre les morts, des choses mortes de l’incrédulité, et que vous êtes un… rendu vivant par la Parole de Jésus-Christ, et que vous croyez la Parole, et que la Parole vit en vous."],["sermons/1965/65-0119.html?q=r%C3%A9surrection#s56","65-0119 § 42 — Le Dieu qui est riche en miséricorde","Or, si vous avez la Vie Eternelle ce soir, si nous avons la Vie Eternelle, alors nous avons toujours existé, parce qu’il n’y a qu’une forme de Vie Eternelle. Nous avons toujours existé. Et la raison en est que nous sommes une partie de Dieu. Et Dieu est le seul Etre éternel."]],[["sermons/1960/60-0306.html?q=d%C3%A9livrance#s8","60-0306 § 4 — Il n’en était pas ainsi au commencement","Eh bien, demain soir, c’est une–une soirée libre pour nous. Les gens vont livrer des combats ici sur ce ring, diverses sortes de combats. Nous combattons l’ennemi, Satan. Mais les hommes vont livrer des combats, la boxe ou quelque chose du genre, ici demain soir. Et cela nous offre l’occasion de nous reposer juste un soir."],["sermons/1958/58-0202.html?q=d%C3%A9livrance#s66","58-0202 § 55 — Hâte-toi de te sauver la","Et chaque fois, les messagers qui étaient envoyés apportaient un message d’amour, de grâce et de délivrance. Le message de Dieu a toujours été un message de délivrance avant le jugement. Noé avait la délivrance. Lot avait la délivrance. Et bien que cela ait été un message de délivrance, le peuple l’a rejeté. C’est la grâce et la délivrance, mais les gens rejettent cela."],["sermons/1953/53-0601.html?q=d%C3%A9livrance#s14","53-0601 § 4 — Faites ce qu’il vous dira","J’ai… Il y a vingt ans, alors que j’étais un jeune garçon, j’ai trouvé Jésus-Christ précieux à mon coeur comme Sauveur. Je L’ai aimé depuis lors. J’ai livré beaucoup de durs combats. Comme vous le savez tous, vous connaissez ma vie, la vie n’a pas été un parterre de fleurs pour moi. Ça a été combat après combat."],["sermons/1962/62-0311.html?q=d%C3%A9livrance#s79","62-0311 § 60 — La plus grande bataille jamais livrée","Maintenant, avant de pouvoir se ranger en ordre de bataille, il faut d’abord choisir un terrain de rencontre, ou un lieu où se livrera la bataille, un lieu déterminé. Pendant la Première Guerre mondiale, il y a eu un tel emplacement, un no man’s land et des lieux où ils livraient bataille. Il fallait qu’il y ait un lieu qu’ils avaient déterminé."],["sermons/1962/62-0707.html?q=d%C3%A9livrance#s276","62-0707 § 230 — Jéhovah-Jiré 3","Satan, tu as perdu la bataille. Dieu est Jéhovah-Jiré. Le Seigneur a pourvu à un Sacrifice. Il a pourvu à un peuple. Il a pourvu à un appel à l’autel. Il a pourvu au Message. Il a pourvu à la grâce. Et Satan a perdu la bataille; au Nom de Jésus-Christ, il a perdu la bataille."],["sermons/1964/64-0402.html?q=d%C3%A9livrance#s103","64-0402 § 86 — Jéhovah-Jiré 1","Et remarquez quel type nous trouvons ici. Après que la bataille fut terminée, après que le–le véritable croyant eut combattu l’ennemi, brisé ses rangs et essayé d’arracher son frère, que la véritable Semence d’Abraham eut ramené ce frère rebelle, Melchisédek apparut et servit du vin et du pain, la communion, Il donna la communion après que la bataille fut terminée; Il lui servit la communion après la bataille."],["sermons/1958/58-0309E.html?q=d%C3%A9livrance#s41","58-0309E § 38 — L’église s’en ira-t-elle avant la tribulation ?","Bien que dans chaque âge les anges aient apparu, que les prophètes aient surgi, leur message a cependant toujours été la grâce, la miséricorde et la délivrance. Le message de Dieu a toujours été la délivrance, juste avant la fin des temps. Examinez cela dans les Ecritures; Noé prêcha la délivrance, et les gens se rirent de lui, et le ridiculisèrent, et se moquèrent de lui."],["sermons/1953/53-1129A.html?q=d%C3%A9livrance#s294","53-1129A § 109 — La foi qui a été transmise aux saints une fois pour toutes","Une fois je prêchais dans un stade de football ; et quand j’entrais, l’endroit était bondé, et je traversais en regardant. Il y avait une petite enseigne au-dessus de la porte. Elle disait : « Ce qui compte ce n’est pas la taille du chien dans le combat, c’est la taille du combat dans le chien. » C’est une idée valable. Ce qui compte ce n’est pas la taille du chien. C’est la taille du combat."],["sermons/1959/59-0423.html?q=d%C3%A9livrance#s167","59-0423 § 46 — La postérité d’Abraham","Aussitôt que la bataille fut terminée, qu’a-t-Il apporté? Le pain et le vin, la communion. Et ils ont pris la communion après que la bataille fut terminée. Combattons maintenant; ramenons le frère perdu. Jésus a dit: «J’en boirai du nouveau avec vous dans le Royaume de mon Père.» Quand la bataille sera terminée. Amen. Melchisédek est sorti à la rencontre d’Abraham et lui a donné la communion."],["sermons/1962/62-0706.html?q=d%C3%A9livrance#s223","62-0706 § 190 — Jéhovah-Jiré 2","Rappelez-vous qu’une fois, ils allaient à une bataille. Ils ne savaient comment livrer cette grande bataille. David se tenait là et partageait avec eux un morceau de viande et une cruche de vin. Mais l’Esprit tomba sur un homme, et il prophétisa et leur dit où rencontrer l’ennemi, et il en fut ainsi."],["sermons/1959/59-0415E.html?q=d%C3%A9livrance#s142","59-0415E § 59 — La foi d’Abraham","Observez Abraham. Il était là. Et il a rencontré Melchisédek, qui est le Roi de Salem, le Roi de Jérusalem, le Roi de paix, sans père, ni mère. Et remarquez, Il a béni Abraham après la bataille. A la fin de la bataille, Il a béni Abraham. Et remarquez ce qu’Il a fait : Il a apporté du vin et du pain qu’Il a donnés à Abraham. Le vin et le pain, c’est la communion. Il a pris la communion après la bataille."],["sermons/1962/62-0701.html?q=d%C3%A9livrance#s89","62-0701 § 39 — Se revêtir de toutes les armes de Dieu","Ainsi, quand Dieu… La première bataille qui ait jamais été livrée n’a pas été livrée sur la terre; elle a été livrée au ciel : Micaël et ses Anges contre Lucifer. Et ils ont été chassés du ciel. Et puis, cette grande armée du diable ainsi que tous ses petits démons sont tombés sur la terre, et Dieu savait qu’il y aurait une bataille."]],[["sermons/1960/60-0804.html?q=peur#s236","60-0804 § 60 — Pareil à l’aigle qui éveille sa couvée","N’ayez pas peur, frère dans le fauteuil roulant. N’ayez pas peur, soeur. N’ayez pas peur, frère. Vous qui avez le cancer, la maladie du coeur ou quoi que ce soit, n’ayez pas peur. Dieu vous a invité à vous emparer des ailes de la croix, dans cette Bible ici, la promesse de Dieu, et à vous envoler dans le ciel."],["sermons/1957/57-0908E.html?q=peur#s207","57-0908E § 381 — Hébreux chapitre 6, 2","Ainsi, il vous est impossible d’être perdu. Vous avez peur; et voilà pourquoi la peur, la peur... La crainte va de pair avec le doute. L’amour va de pair avec la foi. J’aime mon Père. Je n’ai pas peur de Lui, parce que je L’aime. Il ne me ferait pas de mal. Il me fera du bien. Si j’avais peur de Lui, je dirais : «Oh! je ne sais pas s’Il va le faire.»"],["sermons/1960/60-0515E.html?q=peur#s148","60-0515E § 114 — L’épître aux Ephésiens est comparable au livre de Josué","Et, oh ! je vous assure, certaines personnes ont peur de recevoir le Saint-Esprit, ils ont peur que je les fasse parler en langues. Ils ont peur que quelqu’un dise : « Tiens, c’est un de ces parleurs en langues. » Ils ont peur de venir à l’église se faire baptiser au Nom de Jésus-Christ, parce qu’ils en ont honte. Hum ! Oh !"],["sermons/1956/56-0723.html?q=peur#s145","56-0723 § 53 — Conduit par l’Esprit de Dieu","Maintenant, prenons une minute. Voici un homme qui possède toute la formation militaire. Il a en lui toute la théologie de séminaire. Il connaît la Bible, mais c’est un poltron. Il se tient là derrière le désert, il a peur de descendre en Egypte, il a peur de son ombre. Il a peur de s’y rendre, il a même peur de visiter ses bien-aimés."],["sermons/1962/62-0513M-2.html?q=peur#s152","62-0513M § 100 — Laisser échapper la pression","«Eh bien, direz-vous, je suis très inquiet, Frère Branham, je ne sais simplement pas.» Laissez échapper la pression. Amen. Dans la ville de refuge, Il a pris vos soucis, ainsi vous–vous n’avez pas à en avoir. Déchargez-vous sur Lui de vos soucis, car Il prend soin de vous. Ne vous tracassez pas au sujet de vos soucis, c’est Son affaire à Lui."],["sermons/1957/57-0519E.html?q=peur#s108","57-0519E § 35 — L’amour","C’est là qu’en est l’église. Vous avez toujours peur que cela n’arrive pas. C’est la raison pour laquelle ça n’arrive pas. Quand cette peur-là… L’amour bannit la crainte. Une fois que vous avez l’amour, la peur se dissipe. Mais tant que vous avez peur, l’amour ne peut pas opérer."],["sermons/1953/53-0509.html?q=peur#s57","53-0509 § 19 — La Colonne de feu","Le plus grand problème dans l’église aujourd’hui, c’est une grande peur. Les gens ont toujours peur, et cela vient du diable. N’ayez pas peur. Soyez courageux. Vous n’avez pas de quoi avoir... Il n’y a rien à craindre. Nous aborderons cela cette semaine, voyez, là-dedans et nous examinerons Dieu et verrons ce qu’Il était."],["sermons/1964/64-0500.html?q=peur#s531","64-0500 § 112 — Lettre audio à Lee Vayle","Et je me suis dit : «Eh bien, maintenant, je délire.» Vous voyez?J’avais peur, je dois l’avouer, Lee, j’avais peur. Et j’avais peur, me demandant pourquoi j’ai dû remonter là-haut. En effet, vous savez, Lee, que j’ai… j’ai plutôt été toute ma vie un homme des bois. Et je–je sais ce que cela signifie de se retrouver dans quelque chose de ce genre. Et j’avais peur."],["sermons/1962/62-0408.html?q=peur#s86","62-0408 § 22 — Présumer","Il a dit : « Dieu nous a donné la promesse, et la peur que nous inspirons est sur chacun d’eux. Et quoiqu’ils soient différents de nous, cependant ils ont peur de nous. » Certainement. Il a dit : « La peur–la peur de l’Eternel s’est emparée de chacun d’eux. Ils ont une peur bleue à cause de nous. » Il a dit : « Allons nous en emparer. Dieu nous l’a donné, cela nous appartient. Allons nous en emparer. »"],["sermons/1957/57-0114.html?q=peur#s303","57-0114 § 114 — La preuve infaillible de la résurrection","Vous avez peur, madame. Votre grand problème, c’est la peur, c’est que vous redoutez une intervention chirurgicale. C’est vrai. Et vous avez connu tout récemment une hémorragie, du sang qui coule. Et vous avez peur d’une intervention chirurgicale, c’est donc la raison pour laquelle vous n’aimeriez pas aller chez un médecin cette fois-ci, car vous avez peur d’une intervention chirurgicale."],["sermons/1951/51-0509.html?q=peur#s110","51-0509 § 33 — Témoignage","Jésus disait toujours : « N’ayez pas peur. » N’ayez pas peur. N’ayez pas peur. Ne faites pas cela. Si vous le faites, alors Dieu ne peut pas vous utiliser. Et si vous croyez réellement, alors Dieu peut vous utiliser. N’est-ce pas vrai ? Maintenant, ayez foi en Dieu. Je crois que c’est ce que Jésus a dit : « Ayez foi en Dieu. »"],["sermons/1965/65-1126.html?q=peur#s181","65-1126 § 167 — Les oeuvres sont l’expression de la foi","Alléluia! Nous savons aussi où nous irons à la fin de ce voyage. Dieu nous l’a promis. Il y a un Pays de l’autre côté de la rivière. Soyez sans peur dans votre témoignage. Amen! Si cela vous a été révélé, vous êtes sans peur. Peu importe ce que le monde entier… ce qu’on dira, vous êtes sans peur. Lorsque cela vous est révélé : «C’est la Vérité venant de Dieu.» Alors, vous pouvez être sans peur. Autrement, c’est impossible."]],[["sermons/1964/64-0215.html?q=doute#s29","64-0215 § 14 — Les influences","Eh bien, s’il y a un doute dans votre esprit, ne le faites pas du tout. S’il y a un doute quelque part, tenez-vous-en éloigné. Alors, vous voyez, vous vivez donc absolument par la foi, s’il n’y a aucun doute. S’il y a un doute, laissez donc cela. Ne vous en approchez pas du tout."],["sermons/1964/64-0412.html?q=doute#s143","64-0412 § 118 — Un procès","«Il n’a pas douté de la promesse de Dieu par incrédulité.» Peu importe combien de moqueurs ont dit : «Tu n’es pas… Tu n’y parviendras pas. C’est impossible! Ressaisis-toi! Tu es fou!» Il a dit qu’il se fortifiait davantage. C’est ce que fait la foi authentique. Elle ne connaît aucun doute. Mais si vous ne le savez pas, vous abandonnerez très vite."],["sermons/1963/63-1103.html?q=doute#s233","63-1103 § 206 — Allez réveiller Jésus","Eh bien, il n’y a qu’un seul péché, c’est l’incrédulité. C’est soit la foi, soit l’incrédulité. « Celui qui ne croit pas est déjà condamné. » Vous pouvez fumer, boire et faire ces choses, parce que vous ne croyez pas. Mais si vous croyez réellement, vous agirez autrement. Voyez ? C’est soit la foi, soit l’incrédulité qui est en vous."],["sermons/1955/55-0400.html?q=doute#s71","55-0400 § 71 — L’aveugle Bartimée","Bon, croyez-Le donc de tout votre coeur, mes enfants. Et le mot péché veut dire l’incrédulité. Il n’existe qu’un seul péché, c’est l’incrédulité. Tous les autres… Ces actes immoraux ne sont que des attributs de ce seul péché : l’incrédulité. « Celui qui ne croit pas est déjà condamné. » Voyez-vous ? Il vous faut croire."],["sermons/1964/64-0816.html?q=doute#s205","64-0816 § 157 — Confirmant sa Parole","Il a alors dit : « Si Tu es le Fils de Dieu… » Vous voyez, il a toujours douté de Cela. Il apprend toujours aux autres à douter de Cela. Il a appris à Ève à douter de Cela. Il a appris à Moïse, et il a appris à tous les autres à chercher à douter de Cela."],["sermons/1956/56-0722.html?q=doute#s81","56-0722 § 20 — Tout est possible à celui qui croit","Laissez-moi vous le montrer juste par un cas dans la Parole. La première fois que le diable a rencontré Jésus-Christ, il a douté de Lui. Le doute est toujours du diable. C’est ce qui engendra le premier péché. Il n’existe pas d’autre péché que le doute. L’incrédulité est l’unique péché originel. Commettre adultère n’est pas un péché; fumer la cigarette n’est pas un péché; s’enivrer n’est pas un péché. Ce sont des attributs de l’incrédulité. Amen."],["sermons/1958/58-0325.html?q=doute#s114","58-0325 § 42 — La foi par l’expérience","Qu’est-ce que le péché ? L’incrédulité. Boire, fumer, jouer à l’argent, commettre adultère, ce ne sont pas là des péchés. Ce sont les attributs de l’incrédulité. « Celui qui ne croit pas est déjà condamné. » Il n’y a que deux choses : C’est soit la foi, soit l’incrédulité. Vous êtes chargé ici ce soir de l’un ou de l’autre. Que Dieu soit miséricordieux !"],["sermons/1962/62-0311.html?q=doute#s408","62-0311 § 320 — La plus grande bataille jamais livrée","S’il peut vous amener à être incrédule à votre Arme, votre équipement, s’il vous amène à croire que votre Arme n’est pas assez puissante, il vous aura désarmé. Oh ! Frère Neville, j’espère que vous ne serez jamais incrédule à cela. Regardez. Il vous aura désarmé, quand il vous aura amené à être incrédule à cette Arme. Quand vous La déposez, votre combat s’arrête là. Vous êtes fichu. Tenez cette Arme ; ne La déposez pas. Nous voyons son incrédulité. Que..."],["sermons/1963/63-1115.html?q=doute#s270","63-1115 § 226 — La dislocation du monde","Pourquoi doutez-vous ? Ne doutez pas. Vous avez l’asthme, et vous avez une maladie de coeur, vous souffrez de l’arthrite, tout. Vous voulez que Dieu appelle numéro après numéro. Une fois qu’Il vous a parlé, c’est tout. Ne–ne doutez simplement pas. Souvenez-vous que c’est vrai. Croyez en Dieu, et vous aurez ce que vous vouliez. Amen."],["sermons/1961/61-0315.html?q=doute#s394","61-0315 § 222 — Un son confus","Quel est votre péché? Vous dites : «Frère Branham, je suis déjà chrétien.» Confessez votre péché; votre péché, c’est l’incrédulité. C’est le seul péché qui soit, c’est l’incrédulité. Seulement vous... Votre incrédulité vous éloigne de la chose. Chaque personne malade ici présent, confessez votre foi dans «par Ses meurtrissures nous avons été guéris». Observez ce qui arrive."],["sermons/1957/57-0901E.html?q=doute#s84","57-0901E § 60 — Hébreux chapitre 4","Mais cela ne rencontra pas une foi personnelle. Car aussitôt qu’ils atteignirent le désert, ils se mirent tous à murmurer. Et comme ils avaient douté, Dieu dit que c’était un péché. Ne doutez de rien. Croyez! Ne doutez pas, peu importe combien le cas est difficile, croyez-le!"],["sermons/1962/62-1007.html?q=doute#s103","62-1007 § 94 — La clé pour la porte","Dans Hébreux, chapitre 12, il est dit : « Nous donc aussi, puisque nous sommes environnés d’une si grande nuée de témoins, rejetons tout fardeau et toute incrédulité qui nous enveloppe si facilement. » Il est dit « péché »; en fait, le péché, c’est l’incrédulité. Voyez ? L’unique péché, c’est l’incrédulité. Et un « péché » veut dire « manquer le but. »"]],[["sermons/1962/62-1014M.html?q=patience#s245","62-1014M § 182 — La stature d’un homme parfait","Noé avait de la patience. Oui. Noé avait une véritable patience selon Dieu. Dieu a dit : « Je vais détruire ce monde par la pluie. » Et Noé a prêché cent vingt ans là-dessus. Beaucoup de patience ; même pas de la rosée est tombée du ciel. Il n’y avait rien. C’était aussi poussiéreux que jamais, pendant cent vingt ans, mais il était patient."],["sermons/1961/61-0128.html?q=patience#s105","61-0128 § 34 — Pourquoi ?","Eh bien, vous ne pouvez pas condamner le médecin pour cela, si le patient meurt juste sur le seuil du cabinet. Certainement pas. Le médecin est disposé à soigner le patient. Et vous ne pouvez pas condamner la toxine. Et il en a plein là à l’intérieur. Mais le patient… C’est parce que le patient ne veut pas entrer là prendre la toxine. Voilà pourquoi il est mort."],["sermons/1954/54-1003E.html?q=patience#s38","54-1003E § 38 — L’année de jubilé","«Et sachant ceci, que la tribulation produit la patience, la patience produit l’espérance; l’espérance ne rend pas confus.» Vous y êtes. Voyez-vous? «Les tribulations produisent la patience.» Etre patient. «Et l’espérance ne rend pas confus.» Et nous avons l’espérance ce soir. Dans toutes nos tribulations, elle agit toujours. Les tribulations nous rendent patients, attendant la Venue du Seigneur."],["sermons/1965/65-1127E.html?q=patience#s71","65-1127E § 48 — J’ai entendu, mais maintenant je vois","Bon, nous voyons qu’il est parlé ici de sa vie, de ses épreuves et de sa grande foi. Même Jésus, lorsqu’Il vint sur la terre, Il se référa à la patience de Job. Il dit : «N’avez-vous pas lu au sujet de la patience de Job?» La foi attend avec patience que la Parole promise s’accomplisse."],["sermons/1962/62-1104M.html?q=patience#s138","62-1104M § 125 — Les noms blasphématoires","La patience, et ainsi de suite, il y a une parodie de patience, une prétention d’être patient, une foi donnée par la nature, une vertu donnée par la nature. Il y a une tempérance donnée par la nature. Et toutes ces choses sont données par la nature."],["sermons/1962/62-0610E.html?q=patience#s2","62-0610E § 2 — Concerne et convaincu","J’apprécie vraiment toute votre patience, à rester assis en train de m’écouter prêcher pendant des heures, pour revenir ensuite le soir suivant. Vous pouvez certainement endurer tant de peine. Ainsi, je suis–je sais que vous avez beaucoup de patience."],["sermons/1957/57-0306.html?q=patience#s27","57-0306 § 12 — Dieu tient sa Parole, 1","La Bible dit qu’au temps de Noé, Dieu a usé de patience. Il ne voulait pas qu’aucun périsse. Et Il a dit : « Ce qui arriva au temps de Noé arrivera de même à la Venue du Fils de l’homme. » Je crois que la Venue du Seigneur aurait dû déjà avoir lieu. En effet, Il a dû attendre longtemps au temps de Noé. Il a dû attendre longtemps pour faire sortir Israël. Je crois qu’Il attend depuis longtemps. Mais, je crois que Sa patience envers nous tend à s’épuiser."]],[["sermons/1956/56-0108.html?q=promesse#s105","56-0108 § 24 — Dieu a une voie à laquelle il est pourvu","Non, nous venons avec assurance dans notre coeur : « Dieu a préparé une issue par Christ et je viens accepter cela. » C’est une chose facile quand vous regardez et que vous voyez qui a fait la promesse, si vous voyez que c’est Dieu qui a fait la promesse. Si Dieu a fait la promesse, Dieu est capable de tenir Sa promesse."],["sermons/1961/61-0226.html?q=promesse#s75","61-0226 § 24 — Jéhovah-Jiré","Quand Dieu fait une promesse, Il est obligé de tenir cette promesse. S’Il ne tient pas cette promesse, alors Il n’est pas Dieu. Mais s’Il tient cette promesse, le seul moyen pour que cette promesse vive, c’est par votre foi qui la vivifie. La Parole de Dieu est une semence."],["sermons/1961/61-0112.html?q=promesse#s575","61-0112 § 472 — Questions et réponses","«Frère, c’est une promesse. Dieu a fait la promesse. Croyez-vous qu’Il a été promis? Eh bien, ne doutez pas de Cela. Si vous croyez la promesse, le Saint-Esprit viendra donc en vous à n’importe quel moment. Attendez-Le. Abandonnez-Lui tout ce que vous avez, et dites : ‘Seigneur, je me tiens sur Ta promesse.’»"],["sermons/1960/60-0717.html?q=promesse#s238","60-0717 § 76 — N’ayez pas peur","Notre Père céleste, la Bible est vraiment pleine de promesses. Et chaque promesse est vraie. Chaque promesse nous appartient. Tu es mort afin que ces promesses soient accomplies en nous. Que les gens n’aient pas peur lorsqu’ils voient arriver cette chose dont Tu as parlé et qu’ils la voient se produire juste au milieu d’eux."],["sermons/1959/59-0415E.html?q=promesse#s49","59-0415E § 23 — La foi d’Abraham","Rappelez-vous, la promesse était à Abraham, tant qu’il restait dans son pays) la promesse était sans condition pour lui. Mais une fois qu’il sortait du pays, la promesse n’était plus valable. Et la promesse est pour vous tant que vous restez dans votre alliance avec Christ. Mais si vous en sortez, vous êtes… Tant pis pour vous. Mais tant que vous y êtes, Dieu vous gardera."],["sermons/1959/59-0125.html?q=promesse#s83","59-0125 § 65 — Soyez certain de Dieu","Même si la situation semble se désagréger de tous côtés, néanmoins cette foi ne bouge jamais, parce que vous êtes certain qu’Il est Dieu. Et s’Il est Dieu, Il tient Sa promesse. Il ne peut pas faire une promesse et la rompre. S’Il est Dieu, Il doit tenir Sa promesse. Oh ! J’aime ça ! Il doit y rester fidèle."],["sermons/1959/59-1216.html?q=promesse#s39","59-1216 § 26 — Qu’est-ce que le Saint-Esprit ?","Maintenant, j’aimerais En parler, parler du Saint-Esprit en tant que Signe, car Il est un Signe. Nous savons que–que toutes les promesses nous sont données par... Abraham était le père de la promesse, parce que Dieu a donné la promesse à Abraham et à sa postérité après lui. La promesse a été faite à Abraham et à sa postérité. Et ce Signe est destiné à un peuple de l’alliance."],["sermons/1964/64-0122.html?q=promesse#s24","64-0122 § 20 — Tournez le regard vers Jésus","Il nous a fait une promesse pour ce jour. Il nous a fait une promesse. Et notre promesse aujourd’hui doit être révélée aussi sûrement que l’a été celle d’Abraham, car nous sommes les enfants d’Abraham: «Etant morts en Christ, nous sommes la Semence d’Abraham, et les héritiers avec Lui selon la promesse.»"],["sermons/1955/55-0603.html?q=promesse#s130","55-0603 § 41 — Jésus-Christ est le même hier, aujourd’hui et éternellement","Si Dieu a fait une promesse, Dieu doit se tenir derrière Sa promesse. Et s’Il ne le fait pas, alors Sa promesse n’est pas valable, alors Il… Sa Parole est comme la mienne. Mais Dieu se tiendra derrière cela si vous vous tenez derrière Dieu. Et si vous osez vous avancer et Le prendre au Mot, Il le fera."],["sermons/1958/58-0524.html?q=promesse#s34","58-0524 § 12 — Jésus de Nazareth passe","C’est pareil avec Dieu. S’Il a fait une promesse, Il doit tenir cette promesse. S’Il ne tient pas cette promesse, alors Il n’est pas Dieu. Et si une certaine crise survient et que Dieu agit d’une certaine façon lors de cette crise-là, alors Il doit agir de même la seconde fois qu’Il agira, sinon Il avait mal agi la première fois."],["sermons/1964/64-0120.html?q=promesse#s34","64-0120 § 20 — Ses paroles infaillibles de promesse","La femme qui a touché Son vêtement n’en avait pas de promesse. Mais sa foi sans promesse lui a procuré la guérison. Or, si elle a pu, sans une promesse, obtenir la guérison par sa foi dans ce qu’elle faisait, à combien plus forte raison obtiendrons-nous notre guérison par la foi dans la promesse que Dieu manifeste et confirme devant nous, et Il nous l’a apportée par Sa Parole, Il est venu et a confirmé Sa Parole."],["sermons/1957/57-0613A.html?q=promesse#s64","57-0613A § 61 — Dieu tient sa Parole","Eh bien, c’est ça le problème avec beaucoup de croyants. Ils prennent simplement la parole de quelqu’un pour cela, ils ne cherchent pas à voir ce que leur Livre avait. Chaque promesse dans ce Livre est pour vous. Il n’existe aucune promesse en dehors du Livre, mais dans le Livre, ces promesses sont pour vous. Dieu vous les a données."]],[["sermons/1960/60-0711.html?q=pardon#s70","60-0711 § 20 — La porte dans la porte","Et ce n’est pas la taille de mon texte qui compte ce soir ; ce n’est pas la valeur du papier sur lequel il est écrit qui compte ; c’est ce qui est écrit sur le papier. C’est la Parole du Dieu vivant, une offre de pardon. Un pardon... C’est un pardon. La Parole est un pardon pour chaque homme, chaque femme, chaque garçon ou chaque fille qui La recevra."],["sermons/1963/63-1028.html?q=pardon#s35","63-1028 § 16 — Le pardon","De même, ce soir j’ai lu ceci, que Dieu nous donne toutes choses, et Il nous accorde le pardon ; c’est un pardon pour ceux qui désirent accepter la Parole de Dieu comme un pardon. Mais seulement cela… Le simple fait de lire cela ne signifie pas que vous êtes pardonné. C’est-à-dire que vous devez accepter cela comme votre pardon, que Dieu a donné Son Fils pour mourir à votre place, et alors c’est un pardon."],["sermons/1959/59-1001.html?q=pardon#s15","59-1001 § 4 — Qu’êtes-vous allés voir ?","Voyez, Paul était un chrétien depuis si longtemps qu’il–il savait ce que c’est pardonner, ce que signifiait pardonner quelqu’un. Il avait été lui-même pardonné. Et je pense que tout chrétien qui a vraiment été pardonné sait apprécier le pardon."],["sermons/1962/62-0318E.html?q=pardon#s373","62-0318E § 350 — La Parole parlée est la semence originelle","Les pharisiens, comme c’était vrai ! Ce matin, j’avais mentionné que nous allions y venir. Et j’ai déjà pris tout le temps que j’avais. Mais les–les pharisiens ont dit : « Cet Homme pardonne les péchés. Nous savons qu’Il est un blasphémateur. Dieu seul peut pardonner les péchés. Et cet Homme pardonne les péchés. » Ils ne savaient pas que C’était là la Parole. La Parole pardonne les péchés, parce qu’Elle est Dieu."],["sermons/1955/55-1113.html?q=pardon#s20","55-1113 § 7 — Jésus-Christ est le même hier, aujourd’hui et éternellement","Eh bien, je ne crois pas qu’il y ait quelqu’un sur la terre qui puisse vous pardonner vos péchés. Eh bien, si vous aviez péché contre moi et que vous me demandiez de vous pardonner ce que vous avez fait contre moi, ce serait en ordre, je pourrais vous pardonner cela. Mais il n’y a que Dieu seul qui peut vous pardonner les péchés que vous avez commis contre Lui, contre la Bible et contre la nature. Et c’est pareil pour la guérison."],["sermons/1963/63-0317M.html?q=pardon#s226","63-0317M § 208 — Dieu se cache, puis se révèle dans la simplicité","C’est alors qu’Il leur a dit que, « quand on arrivera dans les derniers jours, ils–ils blasphémeraient en faisant cela ». Il leur a pardonné, mais ça ne serait pas pardonné dans ces derniers jours. La conséquence à subir serait une séparation éternelle, « ne jamais être pardonné ni dans ce siècle ni dans le siècle à venir »."],["sermons/1961/61-0808.html?q=pardon#s211","61-0808 § 70 — Ta famille","Voyez-vous, donc Dieu, quand Il–quand ils ont rejeté Christ et L’ont traité de Béelzébul, Il a dit : « Je vous pardonne cela. (Voyez-vous ?) Je vous pardonne. Mais, a-t-Il dit : « Un jour le Saint-Esprit viendra », pour faire la même chose qu’Il faisait. Il a dit : « Un seul mot contre Cela ne sera point pardonné. »"],["sermons/1964/64-0215.html?q=pardon#s121","64-0215 § 90 — Les influences","Et Il a dit : « Moi, Je vous pardonne. » A ce moment-là, l’expiation n’avait pas encore été faite, mais... et Jésus n’était pas mort. « Mais, a-t-Il dit, quand le Saint-Esprit sera venu, parler contre cela ne vous sera jamais pardonné. » Quand le Saint-Esprit sera venu accomplir la même oeuvre qu’Il accomplissait alors, cela ne sera jamais pardonné."],["sermons/1959/59-0419E.html?q=pardon#s120","59-0419E § 51 — Montre-nous le père et cela nous suffit","Il a dit : « Maintenant, Je te pardonne tes péchés gratuitement; mais toi, tu veux la détruire. » Alors, je suis sorti de la vision; et j’ai vu qu’Il m’indiquait cette femme. «Moi, Je t’ai gratuitement pardonné.» Le péché est péché, qu’il soit petit ou grand. J’ai donc dit : « Ô Seigneur, pardonne-moi. »"],["sermons/1956/56-0731.html?q=pardon#s49","56-0731 § 11 — La résurrection de la fille de Jaïrus","Nous Te prions ce soir, ô Dieu, de nous pardonner chaque péché, chaque manquement que nous avons dans la vie. Nous prions que Ta grande grâce descende et nous pardonne. Pardonne chaque péché qui est sous la tente ce soir, ô Dieu, nous… Je Te prie, comme me tenant entre les vivants et les morts, de pardonner chaque offense. Et toutes nos petites divergences, nous Te prions de–de nous pardonner simplement d’avoir fait ces choses, et nous le mettons de côté pour T’adorer ce soir en Esprit et en Vérité."],["sermons/1953/53-1111.html?q=pardon#s33","53-1111 § 11 — La préparation","Pardonne-nous nos manquements. Pardonne-nous tous nos péchés, nous savons que nous en avons commis beaucoup, beaucoup. Et nous Te prions de nous pardonner, et de nous utiliser maintenant pour n’importe quel besoin que Tu as ce soir dans ce bâtiment. Je le demande au Nom de Jésus-Christ. Amen."],["sermons/1961/61-0409.html?q=pardon#s4","61-0409 § 2 — Messieurs, nous voudrions voir Jésus","Je ne crois pas qu’il y ait une personne qui puisse pardonner les péchés, à moins que ce soit un péché qui a été commis contre cette personne. Si vous avez péché contre moi et qu’ensuite vous me demandiez de vous pardonner, je pourrais le faire, et je le ferais. Mais je crois que les péchés que vous avez commis contre Dieu, c’est Dieu seul qui peut pardonner ces péchés."]],[["sermons/1963/63-0112.html?q=humilit%C3%A9#s67","63-0112 § 28 — L’influence","Bon. L’orgueil, il s’est enflé d’orgueil et se disait: «Quel grand homme je suis!» Il s’est tellement enflé d’orgueil qu’il a cherché à prendre la place d’un ministre. Il est entré au temple, il a pris–il a pris l’encensoir et il est allé à l’autel des parfums. Or, c’était… Seuls des hommes consacrés pouvaient faire ce travail."],["sermons/1963/63-0412E.html?q=humilit%C3%A9#s320","63-0412E § 292 — Dieu se cache dans la simplicité","Notre Père céleste, l’humilité–l’humilité de croire en Toi, oh! comme Tu te révèles dans l’humilité ! Oh ! comme nous voyons dans ces jours, et dans tous les autres, que l’église se retrouve dans cet état ! Alors Tu t’abaisses directement dans la fosse, venant de nulle part, Tu ramasses quelque chose, Tu l’oins, Tu l’envoies, mais cela sera rejeté, alors le monde sera jugé par cela."],["sermons/1959/59-1001.html?q=humilit%C3%A9#s108","59-1001 § 33 — Qu’êtes-vous allés voir ?","Oui, Jean était assez homme pour être doux et humble. Il était assez homme pour se tenir sur les rivages du Jourdain. Il n’avait pas besoin d’une grande synagogue ou d’un endroit pour prêcher. Il était humble. Il était sincère. Il était assez humble au point qu’il n’a pas réclamé beaucoup d’argent aux gens pour qu’il soit pasteur dans leur église. Il vivait de sauterelles et de miel sauvage."],["sermons/1963/63-1114.html?q=humilit%C3%A9#s133","63-1114 § 113 — Influence","Eh bien, deuxièmement, ils avaient les pieds couverts des ailes, à leurs pieds. Eh bien, cela représentait l’humilité. Oh ! voilà un mot qui n’existe plus aujourd’hui pour beaucoup. L’humilité dans Sa Présence. Nous humilier dans Sa Présence."],["sermons/1957/57-1211.html?q=humilit%C3%A9#s90","57-1211 § 34 — Messieurs, nous voudrions voir Jésus","Dieu ne vit pas dans l’éclat. Dieu habite dans l’humilité. L’éclat vient de Satan. Il habite dans l’humilité. Quand Il était ici sur terre, Il était le plus humble parmi les hommes, le plus pauvre parmi les hommes. Qui était celui qui voulait l’éclat ? Satan. Il voulait que son royaume soit plus glorieux que celui de Micaël, aussi l’avait-il établi au Nord, cherchant à dépasser l’autre par l’éclat, le fils de l’aurore."],["sermons/1963/63-0322.html?q=humilit%C3%A9#s8","63-0322 § 8 — Le cinquième sceau","Mais pensez-y. Ce soir, dans notre modeste petit tabernacle, nous invitons le Roi des rois, Dieu. Et nous ne... Il ne veut pas qu’on déroule des tapis, ni rien. Ce qu’Il veut, c’est qu’on Lui présente des coeurs humbles, pour qu’Il puisse prendre ces coeurs humbles et leur révéler les–les bonnes choses qu’Il a en réserve pour tous ceux qui L’aiment."],["sermons/1957/57-1208.html?q=humilit%C3%A9#s60","57-1208 § 24 — Je me tiens à la porte, et je frappe","L’orgueil, on sent juste qu’on a un pet–un petit complexe. Oh ! Vous ne voulez pas que Jésus touche à cela, car cela dégraderait votre rang social dans la communauté. Je préférerais dégrader de mon standing social dans la communauté plutôt qu’effacer mon nom du Livre de Vie de l’Agneau. Mais ils ne Le laisseront pas entrer. Ce petit orgueil Le tient dehors."],["sermons/1963/63-1130B.html?q=humilit%C3%A9#s119","63-1130B § 107 — L'influence","Humble. Moïse, un intellectuel; mais dans la présence de ce buisson ardent, il a ôté ses souliers. Il était sur une terre sainte. Il s’est humilié! L’humilité. C’est ce qui couvrait les pieds, l’humilité."],["sermons/1958/58-0617.html?q=humilit%C3%A9#s133","58-0617 § 42 — Voici, je me tiens à la porte et je frappe","Mais vous laissez le diable fourrer chaque chose piètre et impie qu’il peut fourrer dans cette âme et vous en êtes satisfait. C’est l’exacte vérité. «Oh! ne vous mêlez pas de ma vie privée. Et laissez mon petit orgueil tranquille. Vous savez, j’ai un peu d’orgueil. Je suis du Sud.» Je le suis moi aussi. Mais, frère, lorsque nous devenons chrétiens, nous perdons tout cela. C’est vrai. Nous devons être semblables à Christ."],["sermons/1958/58-0302.html?q=humilit%C3%A9#s70","58-0302 § 28 — La porte du coeur","Oh ! Cette petite vie privée que vous avez pour vous-même, cette petite porte à laquelle vous ne voulez pas que quelqu’un touche… Puis, il y a une autre petite porte là appelée l’orgueil. Oh ! comme vous aimez pointer votre petit nez en l’air ! L’orgueil. Vous pensez être quelqu’un."],["sermons/1962/62-0701.html?q=humilit%C3%A9#s151","62-0701 § 84 — Se revêtir de toutes les armes de Dieu","Mais pour aller vite, ces géants intellectuels impressionnent les humbles hommes de Dieu. Or, le peuple de Dieu a toujours été sans instruction et humble. Dites-moi juste une seule fois où il en a été autrement. Observez les deux fils. Observez les enfants de Caïn et de Seth. Abel a été tué, il était le type de la mort, l’ensevelissement et la résurrection de Christ. Seth le remplaça."],["sermons/1960/60-0515M.html?q=humilit%C3%A9#s104","60-0515M § 69 — Le roi rejeté","Aussitôt qu’un homme devient un grand docteur en théologie, ou qu’il a un petit quelque chose d’accrocher au bout de son nom, il devient plus ou moins un je-sais-tout. Les hommes de Dieu sont des hommes humbles. Le peuple de Dieu est constitué des hommes humbles."]],[["sermons/1965/65-1212.html?q=cons%C3%A9cration#s38","65-1212 § 38 — La communion","Même le sacrifice, Il a dit : «Vos jours sacrés et votre sacrifice sont devenus une puanteur à Mon nez.» Pourtant, Il leur avait prescrit d’offrir ce sacrifice. Mais la manière dont ils le faisaient, c’était devenu une puanteur, une odeur répugnante à Son nez (Ses narines), le sacrifice même que Lui avait ordonné."],["sermons/1964/64-0404.html?q=cons%C3%A9cration#s178","64-0404 § 157 — Jéhovah-Jiré 3","Jean, étant prophète, reconnut cette Parole car la Parole vint à lui; il reconnut que c’était là le Sacrifice. Et conformément à la Loi, le Sacrifice devait être lavé avant d’être offert. C’est exact. Il baptisa Jésus parce qu’Il était le Sacrifice qui devait venir. Avant de pouvoir entrer dans Sa vie publique, Il devait être baptisé, car le Sacrifice doit être lavé avant d’être offert. Amen. Il Le baptisa."],["sermons/1956/56-1001.html?q=cons%C3%A9cration#s180","56-1001 § 57 — Le ministère expliqué","Et cette reine a dit : « Je vais aller voir moi-même. » Maintenant, j’aimerais que vous remarquiez quel sacrifice elle a fait. Lorsque vous venez voir Dieu, vous ne venez pas sur un lit fleuri d’aisance ; vous devez faire un sacrifice. C’est le chemin du sacrifice. C’est le chemin de la mort. Vous devez mourir pour arriver à Lui."],["sermons/1961/61-1231E.html?q=cons%C3%A9cration#s104","61-1231E § 95 — Si Dieu est avec nous, où sont alors tous les prodiges?","Quand vous placez votre âme sur Son autel d’airain, de jugement, qu’arrive-t-il? S’Il est le même Dieu, Il agréera le sacrifice. Si vous l’avez offert avec sincérité sur Son autel, Il consumera ce sacrifice, et le monde sera ôté de vous. La fumée se dissipera. Le sacrifice sera consumé. Oui."],["sermons/1961/61-1015M.html?q=cons%C3%A9cration#s3","61-1015M § 3 — Questions et réponses","Et ce matin, avant de commencer, je crois que quelqu’un a dit qu’il y avait un bébé à consacrer. Billy m’a dit qu’il y a un bébé à consacrer. S’il en est ainsi, eh bien... Très bien. Apportons le petit ami pour le consacrer au Seigneur; ensuite nous répondrons aux questions, et après cela nous prierons pour les malades."],["sermons/1963/63-1116B.html?q=cons%C3%A9cration#s279","63-1116B § 242 — Les investissements","Le Juif posait sa main sur le sacrifice pour s’y connecter. Un jour, vous avez posé les mains sur Jésus et vous vous êtes connecté au Sacrifice. La Vie du Sacrifice est revenue sur vous. En fait, ce soir, je pouvais parler à l’église ce soir sur Le signe, et Il est sur vous maintenant."],["sermons/1964/64-0313.html?q=cons%C3%A9cration#s90","64-0313 § 60 — La voix du signe","Observez maintenant, ils étaient censés avoir la connaissance. Jésus a dit : «Laisse faire.» C’est vrai. «Mais il nous convient d’accomplir ainsi toute justice,» la Parole promise. Le sacrifice devait être lavé avant d’être présenté. Jean a baptisé Jésus parce que Celui-ci était le sacrifice. Vous voyez? Le sacrifice devait être lavé avant d’être présenté. Il est allé directement là et le sacrifice fut lavé, et alors Il a été présenté convenablement."],["sermons/1959/59-0415E.html?q=cons%C3%A9cration#s106","59-0415E § 41 — La foi d’Abraham","Trouvez donc des défauts en Lui, je vous dirais alors pourquoi vous ne pouvez pas être guéri. Mais lorsque votre Sacrifice est à vos yeux sans défaut, c’est qu’Il a été agréé par Dieu. Et puisque Il agrée le Sacrifice, Il accepte votre confession dans ce Sacrifice, et vous En devenez une partie. Amen."],["sermons/1950/50-0819.html?q=cons%C3%A9cration#s71","50-0819 § 19 — Montre-nous le père et cela nous suffit","Maintenant, si un autel, c’est tout ce que Dieu exige, c’est que Caïn était justifié. Et Caïn a offert un sacrifice sur l’autel. Est-ce vrai ? Eh bien, si un sacrifice et un autel, c’est tout ce que Dieu veut, c’est que Caïn était justifié. Donc, Caïn a aussi dressé un autel, alors il a adoré ; il a placé le sacrifice dessus, il s’est agenouillé et il a adoré Dieu. Mais Dieu n’a pas pris plaisir, car il n’avait pas une bonne approche."],["sermons/1953/53-1110.html?q=cons%C3%A9cration#s37","53-1110 § 12 — Je restaurerai","Mais Caïn est venu et a offert un sacrifice. Maintenant, écoutez. Caïn a bâti un autel, une église. Caïn a offert un sacrifice, exactement comme Abel. Et Caïn a adoré. Il n’est pas venu comme un incroyant. Il est venu comme un croyant. Il a levé les mains et a adoré Dieu exactement comme Abel. Eh bien, si tout ce que Dieu exige c’est être membre d’une église, un autel, une adoration, un sacrifice, alors Caïn était aussi juste qu’Abel."],["sermons/1964/64-0311.html?q=cons%C3%A9cration#s36","64-0311 § 33 — Dieu est identifié par ses caractéristiques","Et, remarquez, tous les deux étaient tout à fait fondamentalistes. Ce prophète fondamentaliste, Balaam, a dit : «Bâtissez-moi sept autels», c’est exactement le nombre de Dieu. «Et offrez sur chaque autel un sacrifice pur, un taureau», exactement le même sacrifice que ce qu’ils avaient dans le camp d’Israël. Et il a dit : «Sur chaque autel, offrez également un bélier», ce qui annonçait la Venue de Christ. Et là-bas, en Israël, ils offraient le même sacrifice."],["sermons/1963/63-0630M.html?q=cons%C3%A9cration#s249","63-0630M § 118 — Le troisième exode","Il n’y a qu’un seul lieu où Il puisse jamais rencontrer un homme, c’est sous le Sang répandu, comme en Eden. Cela n’a jamais changé. Le seul lieu de rencontre du temps de Job, c’était sous le sang de l’agneau de sacrifice. Le seul lieu de rencontre du temps d’Israël, c’était sous l’agneau de sacrifice, comme Il l’avait fait dans le jardin d’Eden, c’était sous l’agneau de sacrifice."]],[["sermons/1965/65-0911.html?q=sagesse#s84","65-0911 § 47 — La puissance de Dieu pour la transformation","Eh bien, c’est une bonne chose que d’avoir de la sagesse. Mais si la sagesse est contraire, si la sagesse n’est pas la bonne sagesse venant de Dieu, la sagesse Divine et qu’elle est une sagesse naturelle… Peu m’importe la connaissance que nous avons, ou l’instruction ou que sais-je encore, cela vient du diable. Dieu voulant, je vais vous le prouver dans quelques minutes. Elle est du diable."],["sermons/1962/62-0401.html?q=sagesse#s86","62-0401 § 74 — La sagesse contre la foi","Et ainsi, la–la sagesse sur laquelle je veux que vous soyez fixés avant que nous commencions … Il y a une sagesse de Dieu. La sagesse de Dieu consiste à s’en tenir à Sa Parole, mais Satan par sa sagesse a essayé de tordre la Parole; c’est donc de cette sagesse que je parle."],["sermons/1963/63-1229M.html?q=sagesse#s111","63-1229M § 95 — Il y a ici un homme qui peut allumer la lumière","Remarquez que c’étaient des sages. Et les sages aujourd’hui, pas les sages… La sagesse de ce monde est folie pour Dieu. Vous tous les savants, et vous qui comptez sur une grande érudition ou quelque chose comme ça, vous enseignant comment désintégrer un atome, cela ne peut pas vous donner la Vie. Rien ne peut vous donner la Vie, excepté la Parole parlée de Dieu. La seule manière dont la Vie peut venir, c’est par la Parole parlée de Dieu."],["sermons/1956/56-1207.html?q=sagesse#s251","56-1207 § 58 — Les dons","Maintenant, Dieu avait donné un don au temps de Salomon. Et Salomon avait un don de sagesse. Il était intelligent par la sagesse de Dieu, ce n’était pas par sa propre sagesse, mais par celle de Dieu. C’est ce qu’il avait demandé à Dieu, et Dieu le lui a donné."],["sermons/1960/60-0724.html?q=sagesse#s217","60-0724 § 49 — La Parole immuable de Dieu","Et elle n’a jamais rien écrit. C’est juste. Elle a fait là quelque chose de sage. Je l’ai vue mourir, gisant dans un accident de voiture. Dieu lui donnait une chance à ce moment-là. Mais elle fut assez sage pour ne rien écrire. Il n’y eut rien dans le journal ; elle a simplement laissé tomber cela. Donc, c’est une idée sage. Elle a seulement sauvé sa vie en faisant cela. Voyez-vous, Dieu est toujours Dieu."],["sermons/1961/61-0119A.html?q=sagesse#s50","61-0119A § 17 — Le baptême d’eau","Alors, je me demande, pourquoi Dieu écrirait une telle chose, et permettrait que cela soit confus. Même Jésus a remercié Son Père de ce qu’Il a caché cela aux yeux des sages et des intelligents, et l’a révélé aux enfants qui veulent apprendre. Eh bien, c’est fait de manière à dérouter les–les sages. Mais le Livre est une révélation."],["sermons/1963/63-1114.html?q=sagesse#s14","63-1114 § 11 — Influence","Ainsi donc, c’est pareil avec les Ecritures. C’est découpé comme cela, pour être caché aux yeux des sages et des intelligents ; voyez, ils sont comme les pharisiens, les grands érudits. Et Jésus a loué Dieu de ce que cela, de ce qu’Il a caché Cela aux yeux des sages et qu’Il le révèle aux enfants qui veulent apprendre."],["sermons/1956/56-0814.html?q=sagesse#s39","56-0814 § 25 — L’amour divin et la grâce souveraine (quand l’amour s’élance)","Jetons un regard sur Moïse. Regardez combien cela semblait ridicule. Maintenant, ceci, c’est à quelques-uns d’entre vous qui ne croient pas que Dieu fait des choses ridicules, d’après vos pensées. Voyez? La sagesse du monde est folie aux yeux de Dieu. C’est vrai. Peu importe le degré de sagesse que vous avez, vous êtes toujours fou aux yeux de Dieu. Et quelquefois, la sagesse de Dieu paraît une folie à l’esprit humain. C’est ainsi qu’elles sont opposées l’une à l’autre."],["sermons/1960/60-0911E.html?q=sagesse#s49","60-0911E § 42 — Les cinq identifications précises de la vraie église du Dieu vivant","Bien, tout ceci est un symbole, car c’est la révélation de Jésus-Christ, qui est scellée. Saviez-vous cela ? C’est une chose cachée et qui peut être révélée non pas par la pensée intellectuelle, mais uniquement par le Saint-Esprit, au moyen des dons de l’Esprit. « Celui qui a de la sagesse, qu’il compte le nombre de la bête. » Celui qui a de la sagesse, le don de sagesse, qu’il fasse ceci et fasse cela. Et voici la révélation."],["sermons/1960/60-1204E.html?q=sagesse#s404","60-1204E § 200 — La vision de Patmos","La tête blanche comme la laine, la justice, l’expérience, l’éloquence, la suffisance, la sagesse, l’âge, le blanc, l’ancienneté parlent de la sagesse. Il sait ce qu’Il est en train de faire. Il est la–Il est la Source de la sagesse. Il est la Source de l’expérience. Il est la Source de tout ce qui est bon. Par conséquent, Il est représenté par cette Personne semblable au Fils de l’homme et qui portait des cheveux blancs qui pendaient."],["sermons/1962/62-0319.html?q=sagesse#s60","62-0319 § 42 — Le signe de la semence du temps de la fin","Les gens sages, quand ils découvrent qu’ils sont des créatures du temps, ils se demandent ce qui va se passer quand le temps va s’arrêter. Je vais parler d’un homme du nom de Job pendant un petit moment. C’est le plus vieux livre de la Bible. Nous voyons que Job était, à son époque, l’un des hommes les plus sages au monde. Eh bien, il dit que, quand il allait au marché, les jeunes princes s’inclinaient devant lui à cause de sa sagesse."],["sermons/1955/55-0410M.html?q=sagesse#s97","55-0410M § 86 — La preuve de sa résurrection","Paul avait dit : «Je ne suis pas venu vers vous avec des discours persuasifs et la sagesse humaine. Car si je le faisais, alors votre foi serait bâtie sur la sagesse humaine. Mais je suis venu vous prêcher l’Evangile de la puissance de Dieu, la résurrection du Seigneur Jésus, afin que votre foi soit ferme.»"]],[["sermons/1960/60-0417S.html?q=%C3%A9preuves#s91","60-0417S § 51 — Je sais","Tous ces grands hommes nous prendraient une bonne partie de notre service du matin, si nous nous mettions à relever le fait qu’ils sont passés par les épreuves et ont vu Dieu. Ils sont passés par les épreuves et ils ont vu les Anges. Ils sont passés par les épreuves, ils ont eu des révélations et ont vu des signes, et des miracles, et autres."],["sermons/1951/51-0729A.html?q=%C3%A9preuves#s290","51-0729A § 81 — La résurrection de Lazare","Il tomba malade. Et parfois, Dieu éprouve votre foi. Croyez-vous cela ? Chaque fils qui vient à Dieu doit être éprouvé. Ne trouvez pas étrange les épreuves ardentes qui arrivent, car cela n’est fait que pour perfectionner votre foi, vous rapprocher davantage. Cela est plus précieux pour vous que de l’or. D’accord."],["sermons/1960/60-0804.html?q=%C3%A9preuves#s243","60-0804 § 62 — Pareil à l’aigle qui éveille sa couvée","Oh ! la la ! Dieu n’a pas peur de soumettre Ses aigles à–à une épreuve d’envol. Il n’a pas peur ; Il compte sur vous. Il n’a pas eu peur de soumettre Abraham à une épreuve d’envol. Il comptait sur lui. Il n’a pas peur de soumettre la postérité d’Abraham à une épreuve d’envol, car Il compte sur vous."],["sermons/1957/57-0818.html?q=%C3%A9preuves#s151","57-0818 § 109 — Les mémoriaux de Dieu éprouvés au fil du temps","Béni soit le Nom du Seigneur pour les tentations! «Quand je suis faible, c’est alors que je suis fort», a dit Paul. «Chaque fils qui vient à Dieu doit premièrement être éprouvé et testé.» Et ces épreuves sont plus douces et plus précieuses, pour vous, que l’or précieux. C’est un temps d’épreuves."],["sermons/1961/61-1217.html?q=%C3%A9preuves#s92","61-1217 § 76 — Le christianisme contre l’idolâtrie","Si vous avez de l’or authentique, vous n’aurez pas à vous inquiéter pour savoir si c’est bon ou pas; il tiendra bon devant l’épreuve n’importe où. Et le vrai Esprit de Dieu tiendra bon devant l’épreuve, car Il est éprouvé par la Parole de Dieu. «Sur ce roc, je bâtirai Mon Église.»"],["sermons/1955/55-0605.html?q=%C3%A9preuves#s132","55-0605 § 40 — La communion par la réconciliation du sang","Oh ! j’espère que vous saisirez cela. Chaque homme qui vient à Dieu doit d’abord être éprouvé. Les épreuves, les tribulations font partie de la vie du chrétien. Dieu ne promet pas un lit fleuri d’aisance. Chacun de vous qui acceptez votre guérison, attendez-vous à ce que le diable soit juste là pour vous tourmenter de toutes les manières qu’il peut. Car tout celui qui vient à Dieu doit d’abord être éprouvé."],["sermons/1959/59-1108.html?q=%C3%A9preuves#s42","59-1108 § 30 — Posséder les portes de l’ennemi","Considérons Elie, le Thischbite. Lorsque vint l’épreuve de force, il se croyait le seul dans le pays qui continuait à vivre pour Dieu. Et le roi allait lui faire subir une épreuve ; ils le persécutaient, et cette petite reine au visage fardé, du nom de Jézabel, le menaçait de mort. Quand on en arriva à l’épreuve de force, Elie posséda les portes de son ennemi et ramena toute la nation à Dieu. Dieu tient Sa promesse."],["sermons/1957/57-0810.html?q=%C3%A9preuves#s197","57-0810 § 59 — Jéhovah-Jiré","Maintenant, nous allons mettre Jéhovah-Jiré à l’épreuve ce soir. Dieu a dit dans Son Livre, dans Son glorieux Livre : « Eprouve-moi, dit l’Eternel. » Mettez-Le à l’épreuve sur n’importe quelle Parole. Beaucoup ici n’ont jamais assisté aux réunions auparavant, faites voir vos mains si c’est le cas. A peu près tout le monde ici a assisté aux réunions ; je pense, vous savez donc, excepté peut-être une ou deux personnes."],["sermons/1962/62-0121M.html?q=%C3%A9preuves#s88","62-0121M § 44 — Et ta postérité possédera la porte de son ennemi","Vous passez par un test. Dieu vous met à l’épreuve comme Il l’avait fait avec Abraham. Il soumet la postérité d’Abraham, après lui, à l’épreuve. Et aujourd’hui, la raison pour laquelle nous ne possédons pas la porte de l’ennemi, la raison pour laquelle il y a tant de choses parmi nous, c’est que nous ne sommes pas capables d’endurer l’épreuve. Et permettez-moi de vous dire quelque chose, le test de la Parole est indispensable."],["sermons/1965/65-1128M.html?q=%C3%A9preuves#s190","65-1128M § 168 — Le seul lieu d’adoration auquel Dieu a pourvu","Il a été éprouvé pour qu’on voie quelle était Sa position, voyez-vous, éprouvé de toutes les manières, éprouvé comme nous le sommes. Mais en Lui, rien du tout ne céda. Non, non. Il était le Fils de Dieu."],["sermons/1959/59-0815.html?q=%C3%A9preuves#s69","59-0815 § 34 — Pareil à l’aigle qui éveille sa couvée","C’est ce que Dieu fait pour Son Eglise. Il vous envoie des épreuves et des tribulations : « Chaque fils qui vient à Dieu doit être éprouvé et châtié par Dieu. » Il ne veut pas que vous vous accommodiez à ce monde. Peut-être qu’Il vous jette sur un lit de maladie. Peut-être qu’Il vous laisse attraper une maladie du coeur, une épine."],["sermons/1957/57-0908E.html?q=%C3%A9preuves#s100","57-0908E § 302 — Hébreux chapitre 6, 2","C’est ça la perfection. Et quand vous en arrivez à cela, vous êtes en Christ, et le monde est mort pour vous. Et vous marchez avec l’Agneau chaque jour, et vos pas sont dirigés par Dieu, dans ce que vous devez faire. Oh! que d’épreuves et d’afflictions nous rencontrons! Vous dites : «Passez-vous par des épreuves?» Bien sûr!"]],[["sermons/1963/63-1130B.html?q=pr%C3%A9parez#s163","63-1130B § 151 — L'influence","Mais ce garçon le savait, il était là. Qu’a-t-il fait? Il était en action. Il était prêt devant son patron. Il était prêt devant les prêtres. Il était prêt devant le conseil. Il était prêt à tout, car il avait reconnu Dieu et s’était humilié, et est entré en action avec son témoignage. Vous voyez, c’est cela un véritable serviteur."],["sermons/1964/64-0823M.html?q=pr%C3%A9parez#s249","64-0823M § 198 — Questions et réponses n°1","Nous devons simplement continuer à attendre la venue du Seigneur. Attendez simplement; gardez vos lampes nettoyées et toutes pleines d’huile. Priez chaque heure, non pas chaque jour, mais chaque heure. Continuez simplement à être prêts; soyez prêts; soyez doux et veillez..."],["sermons/1962/62-1124B.html?q=pr%C3%A9parez#s193","62-1124B § 57 — Les investissements","Il dit : «J’ai oublié toute ma connaissance pour connaître Christ.» Il était prêt à abandonner le grand enseignement qu’il avait reçu de Gamaliel. Il était prêt à se faire rembourser ses documents de l’organisation. Il était prêt car, après tout, ils allaient le bouter dehors. Mais il avait découvert quelque chose. Amen."],["sermons/1963/63-0324E.html?q=pr%C3%A9parez#s45","63-0324E § 44 — Le septième sceau","Nous pouvons voir les éléments qui sont prêts à le ramener. Nous pouvons voir les éléments qui sont prêts à faire entrer l’Eglise dans la Présence de Christ. Nous pouvons voir la–l’Epouse en train de prendre forme, de revêtir le vêtement de noces, de se préparer. Nous pouvons voir les lumières qui vacillent. Nous savons que nous sommes à la fin."],["sermons/1964/64-0315.html?q=pr%C3%A9parez#s266","64-0315 § 232 — L’influence","Ce grand prophète de Dieu qui était disposé à confesser que toutes leurs traditions étaient fausses, s’est agenouillé là, s’est fait purifier et alors, la Parole de Dieu pouvait venir à lui. Alors, il a dit : « Je suis prêt à aller, Seigneur. Je suis prêt. Je dirai ce que Tu me diras de dire. Je dirai ce que Tu me diras. » Il était prêt à partir."],["sermons/1956/56-0728.html?q=pr%C3%A9parez#s207","56-0728 § 50 — Remplir de fosses la vallée","C’est ce que nous devons faire ce soir, c’est de frayer une voie pour que le Saint-Esprit se déverse. Faites-le dans votre maison; faites-le dans votre église; faites-le en vous-même. Boutez tout hors du chemin; préparez-vous. Il y a un torrent qui va jaillir, si vous vous y préparez. Si vous ne vous préparez pas pour cela, vous ne le verrez jamais."],["sermons/1955/55-0223.html?q=pr%C3%A9parez#s54","55-0223 § 15 — Job, serviteur de Dieu","Mais un prêteur sur gages me fait toujours penser… Vous savez, le diable nous a placés dans un magasin de prêt sur gages, mais Christ nous a rachetés. Il y est entré comme nous, et Il nous a rachetés du magasin du diable de prêt sur gages. Voyez-vous? Il nous avait mis dans un magasin de prêt sur gages, mais Christ est venu, Il a payé le prix et nous sommes libres."],["sermons/1964/64-0614M.html?q=pr%C3%A9parez#s360","64-0614M § 292 — Dieu dévoilé","Ce que cette nation est, je le suis. Je suis fier de l’être. Je suis prêt à porter sa honte. Je suis prêt à porter l’opprobre, pour être Américain. C’est exact. Et je suis doublement prêt à le faire, pour Jésus-Christ ! Tout ce qu’Il a jamais été, je le suis. J’aime être identifié avec Lui."],["sermons/1957/57-0407M.html?q=pr%C3%A9parez#s104","57-0407M § 26 — Dieu tient sa Parole","C’est pour cette raison que je dis... si l’Eglise ne se prépare pas. Il est de votre devoir de vous préparer. « L’Epouse s’est préparée elle-même. » Les vêtements sont payés. Ils sont prêts, mais vous devez être prêts pour porter ces vêtements. « L’Eglise s’est préparée elle-même. »"],["sermons/1958/58-0720M.html?q=pr%C3%A9parez#s116","58-0720M § 48 — C’est par la foi que Moïse","Frère, je vais vous le dire, quand Israël fut prêt à minuit, ils avaient emballé tout ce qu’ils avaient dans ce monde et ils étaient prêts à partir. Que Dieu nous envoie un tel réveil ! Nous emballons tout et nous sommes prêts à partir. Le cri de minuit est en train de retentir : « Allez à Sa rencontre. » Vous feriez mieux d’avoir tout emballé. Vous feriez mieux de ne rien avoir de ce monde qui vous attire vers l’arrière, des cordes qui vous retiennent. Emballez ; soyons prêts ; nous partons."],["sermons/1960/60-1211M.html?q=pr%C3%A9parez#s184","60-1211M § 141 — Les dix vierges","Ce sera une venue secrète, personne ne saura quand cela arrivera. Il nous est recommandé d’être prêts et de veiller. Nous ne connaissons pas l’heure. Mais, quoi qu’il en soit, nous ne devancerons pas ceux d’autrefois ; car, dès que Jésus apparaît, toute la garde se lève ! Mort ou vivant, cela n’a pas d’importance."],["sermons/1961/61-1119.html?q=pr%C3%A9parez#s27","61-1119 § 24 — La force parfaite par la faiblesse parfaite","Car, en vérité, Seigneur, dans nos coeurs, nous croyons que Tu es prêt à accomplir une oeuvre avec Ton Eglise, prêt à La faire sortir du monde et à L’enlever dans le Royaume de Dieu. Mais, Seigneur, aide-nous à nous préparer pour cette heure-là. Que ce matin soit le moment, Seigneur, où nous tous nous rejetons «tout fardeau, et le péché qui nous enveloppe si facilement, afin de courir avec persévérance dans la carrière qui nous est ouverte.»"]],[["sermons/1956/56-0902.html?q=reconnaissant#s314","56-0902 § 91 — L’Écriture sur la muraille","Notre Père céleste, nous Te remercions ce soir pour toutes ces choses. Nous Te remercions pour la réunion, pour la Parole de Dieu, brute, qui sépare réellement. Le jugement commence dans la maison de Dieu. Nous Te remercions pour toutes ces choses. Nous Te remercions d’avoir sauvé les perdus et d’avoir épargné différentes nations de gens."],["sermons/1964/64-0308.html?q=reconnaissant#s230","64-0308 § 214 — Le signe","Gloire à Dieu ! Comme nous Te remercions, Seigneur Jésus, pour Ta bonté, Ta Présence. Oh ! nous Te remercions pour le Signe, Seigneur. Nous sommes sauvés et remplis de l’Esprit, le Saint-Esprit se déverse avec puissance dans nos corps en ce moment. Combien nous Te remercions pour cela, Père ! Oh ! c’est au Nom de Jésus que nous Te remercions. Amen. Amen."],["sermons/1954/54-0901.html?q=reconnaissant#s40","54-0901 § 18 — Ayez foi en Dieu","Nous Te remercions pour ceux qui ont été appelés à sortir. Tu as dit que ceux qui échapperaient en ce jour-là, le germe de l’Eternel, le peuple de Dieu serait magnifique. Et nous Te remercions pour la magnificence d’un peuple saint, pur et rempli du Saint-Esprit, qui vit pour Toi ; ils le sont par Ta grâce. Et nous Te remercions."],["sermons/1957/57-0310E.html?q=reconnaissant#s21","57-0310E § 11 — Écoutez-le","C’était quelque chose que j’avais à l’esprit : oui, remercier les gens pour cet auditorium, cette–cette arène-ci. J’aimerais les remercier, si l’un d’eux est présent, les gardiens et les autres, c’était vraiment gentil. C’est presque la deuxième ou la troisième fois que je me retrouve en cet endroit, et j’aimerais vraiment vous remercier."],["sermons/1955/55-0828E.html?q=reconnaissant#s107","55-0828E § 35 — Monsieur, nous voudrions voir Jésus","Eh bien, ce n’est pas moi ; c’est Lui. Maintenant, Il connaît cette femme. Il sait tout ce qui la concerne. Alors, si moi je suis Ses yeux, ou plutôt s’Il utilise mes yeux, et ma voix, pour essayer d’encourager Son enfant, nous remercions Dieu pour ça. Et cela devrait amener chacun de vous à être reconnaissant. Cela ne devrait-il pas vous rendre reconnaissant ? Dites : « Amen. »"],["sermons/1954/54-0825.html?q=reconnaissant#s3","54-0825 § 2 — Nous l’avons trouvé","Nous Te remercions pour ces vérités de l’Evangile. Nous Te remercions pour des hommes courageux aujourd’hui dans le monde, qui vont proclamer le plein Evangile du Seigneur Jésus-Christ, qui endurent la persécution, les critiques ou quoi que ce soit; rien ne les arrête. Leur vision demeure, car elle provient du calvaire. Et nous Te remercions pour cela."],["sermons/1955/55-0410M.html?q=reconnaissant#s191","55-0410M § 175 — La preuve de sa résurrection","Notre Père céleste, il se fait tard. L’heure est fort avancée, mais c’était à une heure avancée que Tu es apparu. Nous Te remercions pour Ta divine Parole. Nous Te remercions pour cet Evangile que nous prêchons et croyons. Nous Te remercions pour cet Evangile que Tu as confirmé comme étant la vérité."],["sermons/1954/54-1212.html?q=reconnaissant#s26","54-1212 § 26 — Il jura par lui-même","Et maintenant, alors que nous nous rassemblons aujourd’hui, nous Te remercions de nous avoir accordé un bon voyage à l’aller et au retour de New York. Nous Te remercions d’être avec l’église pendant que nous sommes ici, et pour beaucoup de choses. Oh ! Il y a des milliers de ces grandes bénédictions pour lesquelles nous devons Te remercier. Et Tu les connais toutes, et nous nous inclinons pour Te louer."],["sermons/1954/54-0307E.html?q=reconnaissant#s120","54-0307E § 30 — Vous croyez maintenant ?","Maintenant, j’aimerais prier, et prier pour ces mouchoirs. Notre Bienveillant Père céleste, alors que nous sommes assemblés ici dans cette salle pour une réunion d’adieu à cette campagne, ô Grand Jéhovah Dieu, nous Te remercions pour chaque âme qui a été sauvée. Nous Te remercions pour tout celui à qui Tu as donné le Saint-Esprit ; pour ceux qui ont renouvelé leurs voeux. Nous Te remercions pour chaque guérison que Tu as accordée aux gens."],["sermons/1950/50-0714.html?q=reconnaissant#s77","50-0714 § 22 — Sur ta Parole","Et je suis très reconnaissant de savoir que j’ai un rôle, que je suis compté parmi vous, la grande Eglise de Dieu qui se tient debout aujourd’hui pour le plein Evangile, pour la justice, et pour la puissance du Saint-Esprit dans ces derniers jours. Je suis reconnaissant pour vous, et je suis reconnaissant que Dieu m’ait accordé l’occasion d’être compté parmi vous, et d’être appelé votre frère, et soeur. Et c’est… Vous et moi, nous sommes frère et soeur."],["sermons/1953/53-1129E.html?q=reconnaissant#s161","53-1129E § 54 — Le témoignage","Et, ô Dieu saint, Divin Père, lorsque j’arriverai ce jour-là, que mon témoignage sonne aussi vrai que maintenant. Tu connais mon coeur. Et je suis très reconnaissant que Tu aies confirmé cela comme étant la vérité, pas parce que Ton serviteur l’a dit, mais parce que Tu as fait cela par la grâce divine. Et je suis très reconnaissant."],["sermons/1959/59-0419E.html?q=reconnaissant#s6","59-0419E § 3 — Montre-nous le père et cela nous suffit","Et je le dis aussi au nom des garçons, Léo et Gene. Ils veulent vous remercier pour les livres que vous avez achetés, les bandes, les disques. Et je désire vous remercier du fond de mon coeur pour l’offrande d’amour, l’offrande missionnaire. Je ferai vraiment de mon mieux pour l’utiliser pour le Royaume de Dieu, du mieux que je peux."]],[["sermons/1953/53-1130.html?q=t%C3%A9moignage#s172","53-1130 § 60 — L’éternel n’a-t-il parle qu’à Moïse ?","Si je parlais de moi-même, je serais un menteur. Je parle de Jésus-Christ. Il est la Vérité. Si je rends témoignage de moi-même, mon témoignage sera faux, mais ce n’est pas moi qui rends témoignage. C’est Dieu qui rend témoignage de moi, comme quoi j’ai dit la vérité, et je vous dis la vérité : Jésus-Christ vous a tous guéris. Amen."],["sermons/1963/63-0323.html?q=t%C3%A9moignage#s106","63-0323 § 107 — Le sixième sceau","La Bible dit ici qu’« ils avaient été immolés à cause de leur témoignage pour Dieu, ou à cause de la–la Parole de Dieu, et du témoignage qu’ils avaient rendu ». Or, nous avons vu que pour l’Epouse, c’était la Parole de Dieu et le témoignage de Jésus-Christ. Ceux-là ne portaient aucun témoignage de Jésus-Christ."],["sermons/1961/61-1105.html?q=t%C3%A9moignage#s285","61-1105 § 239 — Le témoignage d’un vrai témoin","Nous croyons Ceci. Nous croyons que la Parole est vraie. Nous voyons qu’Elle est vraie. Nous voyons qu’Il a prophétisé ceci pour les derniers jours. Nous voyons cela. Nous voyons Son arbre rendre témoignage. Nous voyons Ses fleurs rendre témoignage. Nous voyons Sa Parole rendre témoignage. Nous voyons Son Esprit rendre témoignage."],["sermons/1950/50-0815.html?q=t%C3%A9moignage#s202","50-0815 § 51 — L’attitude et qui est Dieu?","Tu es mort dans ce but-là. Tu as pris notre place à la croix. Tu as porté les infirmités dans Ton corps. Et maintenant, Seigneur, pour nous libérer… Et Tu as envoyé le Saint-Esprit, et Il en rend témoignage. Tu as envoyé la Parole; Elle en rend témoignage. Tu as envoyé des ministres; ils en rendent témoignage. Tu as envoyé Ton don; et il en rend témoignage."],["sermons/1953/53-0907A.html?q=t%C3%A9moignage#s74","53-0907A § 21 — Seigneur, montre-nous le père, et cela nous suffit","J’ai dit : « Moi, je ne peux pas être un guérisseur, monsieur, pas plus que vous ne pouvez être un sauveur, mais ai-je dit, Dieu ne rend jamais témoignage à un mensonge. Il rend témoignage à la vérité. Et si moi je rends témoignage à la Vérité, Dieu va me rendre témoignage. »"],["sermons/1957/57-0623.html?q=t%C3%A9moignage#s84","57-0623 § 33 — Croire du coeur","Et le soleil a rendu témoignage. Le voilà, c’est Lui le matériau que Dieu va utiliser dans la construction de Son Eglise. La lune et les étoiles rendirent témoignage. Quand Il mourait, les cieux rendirent témoignage ; la terre vomit, les rochers se fendirent ; la terre rendit témoignage. Et les saints qui dormaient sous terre, dans la poussière de la terre, se levèrent et rendirent témoignage."],["sermons/1953/53-1110.html?q=t%C3%A9moignage#s101","53-1110 § 39 — Je restaurerai","Dieu a rendu témoignage à Jésus-Christ par des signes et des prodiges. Il a rendu témoignage à Israël par des prodiges et des miracles surnaturels. Il a rendu témoignage à Son Eglise depuis le commencement par des signes et des prodiges. Observez ici maintenant dans ce dernier jour. Observez saint Paul. Ecoutez. Regardez par ici, tous."],["sermons/1950/50-0820E.html?q=t%C3%A9moignage#s265","50-0820E § 54 — Croyez-vous que je puisse faire cela ?","Pendant que je me tenais là en train de témoigner, disant : « Je dis la vérité. Et si je dis la vérité, Dieu me rendra témoignage, car je témoigne pour Lui. Et si je ne dis pas la vérité, Dieu ne me rendra pas témoignage. » Et j’ai dit : « Il rend témoignage par des signes et des prodiges. » Et j’ai dit : « Il peut témoigner… » Et à ce moment-là, Le voici venir. Et Il a rendu témoignage. Et Cela est là maintenant."],["sermons/1956/56-1004.html?q=t%C3%A9moignage#s74","56-1004 § 26 — Les témoins","Lorsqu’Il se mourait, Il a rendu témoignage qu’Il se mourait. Il est donc mort au point que le soleil a rendu témoignage qu’Il se mourait et qu’Il était mort. Le soleil a cessé de briller. Son petit frère, la lune, a rendu témoignage. Etudiez la Bible et vous comprendrez qu’à cette époque de l’année, la lune et le soleil brillent ensemble. Et la lune n’a pas brillé, parce qu’elle rendait témoignage qu’Il était mort."],["sermons/1961/61-0224.html?q=t%C3%A9moignage#s52","61-0224 § 19 — N’ayez pas peur","Eh bien, Simon, vous savez comment il est, il est toujours prêt à témoigner, et juste comme n’importe quel chrétien normal qui connaît vraiment Dieu, qui connaît le Seigneur Jésus, est prêt à donner très vite son témoignage. Et comme nous avions dit quelque chose à son sujet hier soir, je peux répéter son témoignage."],["sermons/1951/51-0413.html?q=t%C3%A9moignage#s54","51-0413 § 16 — Les oeuvres que je fais rendent témoignage de moi","Maintenant, je veux parler juste un instant, ou juste attirer votre attention sur ces quelques paroles que le Seigneur a dites : «Les oeuvres que Je fais rendent témoignage de Moi.» Les choses que Je fais, ce que je dis, c’est ce qui rend témoignage de moi. Et c’est ce qui rend témoignage de chaque personne."],["sermons/1963/63-0121.html?q=t%C3%A9moignage#s1","63-0121 § 1 — Zachée, l’homme d’affaires","Ce soir, tout le monde témoigne, partage de très grandes expériences. Et j’apprécie réellement ces choses. Et c’est comme si tout le monde avait un petit sens de l’humour dans son témoignage, et je pourrais ajouter ceci dans le mien. C’est comme la dame de couleur qui a voulu témoigner, il n’y a pas longtemps, elle a dit : «Ancien, puis-je témoigner?»"]],[["sermons/1955/55-0410M.html?q=esp%C3%A9rance#s92","55-0410M § 81 — La preuve de sa résurrection","Et avant que l’homme ne puisse ressusciter dans la résurrection avec Christ, il doit mourir complètement à lui-même, mourir complètement à tous ses associés mondains, mourir complètement à toutes ses habitudes mondaines; mourir complètement à tout ce qui est impie, pour ressusciter de nouveau."],["sermons/1954/54-0103M.html?q=esp%C3%A9rance#s84","54-0103M § 72 — Questions et réponses","Voici ce qu’il en est de deux témoins : c’est absolument le retour de Moïse et d’Elie. Et vous remarquerez, là, que ni l’un ni l’autre... Moïse est mort, mais où est-il allé? Il devait ressusciter. Et Elie a été enlevé sans même passer par la mort. Il devra mourir parce que chaque mortel doit mourir, ainsi il devra revenir. Voilà les deux témoins."],["sermons/1957/57-0809.html?q=esp%C3%A9rance#s231","57-0809 § 79 — L’aveugle Bartimée","Et pour que vous viviez aujourd’hui, physiquement, quelque chose a dû mourir. Si vous mangez du poisson, le poisson a dû mourir. Si vous mangez de la viande, la vache a dû mourir. Si vous mangez du pain, le blé a dû mourir. Si vous mangez des pommes de terre, cela a dû mourir. Su… Vous vivez des substances mortes. C’est exact."],["sermons/1960/60-1218.html?q=esp%C3%A9rance#s269","60-1218 § 229 — Le son confus","Ils ont dit : « La mort est certaine. » Non, non, la mort n’est pas certaine, assurément pas. Il pourrait y avoir un Enlèvement, il n’y aura alors pas de mort. La mort n’est pas aussi certaine. Non, non, pas en ce jour. Elle l’était il y a plusieurs années, mais elle ne l’est plus maintenant. La mort n’est pas aussi certaine."],["sermons/1957/57-0519E.html?q=esp%C3%A9rance#s139","57-0519E § 45 — L’amour","Et madame Wood a dit : « Billy, vous voulez dire que vous allez laisser ces petits opossums mourir de cette mort horrible. » Elle a dit : « Elle est morte. Et vous allez laisser ces petits opossums téter d’elle ce vieux lait, comme cela, et mourir de cette mort horrible ? » Elle a dit : « Frère Branham, c’est méchant. »"],["sermons/1963/63-1124M.html?q=esp%C3%A9rance#s208","63-1124M § 129 — Que ferai-je de Jésus appelé Christ ?","Remarquez, une fille est un produit de l’union de la mère et du père. Eh bien, voici quelque chose de choquant. Mais la mort (physique), la mort physique, c’est l’union de la mère Ève avec Satan, pour avoir douté de la Parole de Dieu. Ils s’étaient unis et ont produit la mort. Elle… La–la mort est un produit de l’union de Satan avec Ève."],["sermons/1959/59-0403.html?q=esp%C3%A9rance#s58","59-0403 § 20 — Vivant, mourant, enseveli, ressuscitant, revenant","L’amour qu’Il avait, comment Il l’a exprimé, comment Il a dû devenir ce qu’Il était afin de mourir pour nous sauver par Sa mort, lorsqu’Il est mort au Calvaire, il n’y a jamais eu de mort semblable à cette mort-là. Il nous est rapporté que lorsque le soldat romain a percé Son côté, de l’eau et du sang en sont sortis."],["sermons/1965/65-0425.html?q=esp%C3%A9rance#s34","65-0425 § 21 — Le lieu d’adoration auquel Dieu a pourvu","Christ, qui ne connaissait pas le péché, est devenu mon péché. Pour que je puisse prendre Sa place, Il a pris ma place. J’étais en Lui au Calvaire quand Il est mort. Je dus mourir là-bas, avec Lui, pour vivre. Puisque la loi du péché et de la mort est dans le corps, vous devez mourir pour être réconcilié avec Lui."],["sermons/1950/50-0818.html?q=esp%C3%A9rance#s11","50-0818 § 5 — Il en sera comme il m’a été dit","Et, remarquez, Abraham est mort ; Isaac est mort ; Jacob est mort ; les patriarches sont morts, mais Christ mourut : une séparation. A Sa mort, Dieu n’était pas avec Lui. Il dut endurer l’absence de Dieu à Sa mort afin que nous ayons la Présence de Dieu à notre mort. Voyez ? Et là, Dieu a fait tomber sur Lui notre jugement. Voilà notre jugement."],["sermons/1962/62-0518.html?q=esp%C3%A9rance#s168","62-0518 § 65 — Laisser échapper la pression","Voyez-vous ce que nos dénominations nous ont fait ? Un tas de sottises. Cela brise notre communion, brise les barrières, et cela met les gens sous tension, et tout, ils cherchent à combattre pour une organisation. Cela va mourir et périr. Cela n’a pas à mourir, c’est déjà mort. C’était mort dès le départ."],["sermons/1965/65-0120.html?q=esp%C3%A9rance#s48","65-0120 § 32 — Ne t’appuie pas sur ton intelligence","Mais souviens-toi d’une chose, mon fils, tu devras mourir. Peu importe toutes les études que tu as pu faire, toute la culture que tu as pu acquérir, tu devras quand même affronter la mort, parce qu’il est écrit que «l’homme doit mourir, après quoi vient le Jugement». Et Dieu, quand... La mort n’est pas si grave, mais de passer en Jugement, c’est ça qui est grave."],["sermons/1962/62-0311.html?q=esp%C3%A9rance#s347","62-0311 § 270 — La plus grande bataille jamais livrée","Vous savez, vous êtes morts, votre vie est cachée. Qu’est-ce qui est mort ? Vous êtes mort à vos sens, vous êtes mort à votre conscience (Votre propre volonté humaine dirait : « Oui, je pense que je... ») mort à vos raisonnements, mort à toutes ces choses, et vous êtes enseveli au Nom de Jésus-Christ et ressuscité avec Lui. Et partout où Il est, vous y êtes aussi."]]];
